module cylinder_with_hex_recess(size, thickness) {
    // Base cylinder
    cylinder(h=thickness, r=size/2, center=false);

    // Hexagonal recess
    // Hexagon is centered on the bottom of the cylinder
    // 3/4 of the hexagon's width is on the side of the cylinder
    // 1/4 of the hexagon's width is on the bottom of the cylinder
    // The hexagon's side length is 2*thickness
    // The hexagon's height is thickness
    // The hexagon's center is at the bottom center of the cylinder
    // The hexagon's vertices are:
    //   (0, -thickness), (thickness, -thickness/2), (thickness, -thickness/2 + 2*thickness/3),
    //   (thickness, -thickness/2 + 4*thickness/3), (thickness, -thickness/2 + 6*thickness/3),
    //   (thickness, -thickness/2 + 8*thickness/3), (thickness, -thickness/2 + 10*thickness/3),
    //   (thickness, -thickness/2 + 12*thickness/3), (thickness, -thickness/2 + 14*thickness/3),
    //   (thickness, -thickness/2 + 16*thickness/3), (thickness, -thickness/2 + 18*thickness/3),
    //   (thickness, -thickness/2 + 20*thickness/3), (thickness, -thickness/2 + 22*thickness/3),
    //   (thickness, -thickness/2 + 24*thickness/3), (thickness, -thickness/2 + 26*thickness/3),
    //   (thickness, -thickness/2 + 28*thickness/3), (thickness, -thickness/2 + 30*thickness/3),
    //   (thickness, -thickness/2 + 32*thickness/3)
    // The hexagon's vertices are translated to the bottom center of the cylinder
    translate([0, -thickness/2]) {
        // Rotate the hexagon by 120 degrees to fit on the side of the cylinder
        rotate([0, 120]) {
            // Draw the hexagon
            hull() {
                polygon([
                    [0, -thickness/2],
                    [thickness/4, -thickness/2 + 2*thickness/3],
                    [thickness/4, -thickness/2 + 4*thickness/3],
                    [thickness/4, -thickness/2 + 6*thickness/3],
                    [thickness/4, -thickness/2 + 8*thickness/3],
                    [thickness/4, -thickness/2 + 10*thickness/3],
                    [thickness/4, -thickness/2 + 12*thickness/3],
                    [thickness/4, -thickness/2 + 14*thickness/3],
                    [thickness/4, -thickness/2 + 16*thickness/3],
                    [thickness/4, -thickness/2 + 18*thickness/3],
                    [thickness/4, -thickness/2 + 20*thickness/3],
                    [thickness/4, -thickness/2 + 22*thickness/3],
                    [thickness/4, -thickness/2 + 24*thickness/3],
                    [thickness/4, -thickness/2 + 26*thickness/3],
                    [thickness/4, -thickness/2 + 28*thickness/3],
                    [thickness/4, -thickness/2 + 30*thickness/3],
                    [thickness/4, -thickness/2 + 32*thickness/3]
                ]);
            }
        }
    }
}

// Call the function with the specified size and thickness
cylinder_with_hex_recess(32, 10);

module shaft_collar(size, thickness) {
    // Define the main body shape
    cylinder(d=size-thickness, h=size+2*thickness, center=true, chamfer_radius=thickness);

    // Subtract the holes from the body
    difference() {
        // Remove the central hole
        cylinder(d=size-thickness, h=thickness, center=true, chamfer_radius=thickness);

        // Remove the outer ring hole
        cylinder(d=(size-thickness)*0.8, h=thickness, center=true, chamfer_radius=thickness);

        // Remove the inner ring hole
        cylinder(d=(size-thickness)*0.6, h=thickness, center=true, chamfer_radius=thickness);

        // Remove the small hole
        cylinder(d=(size-thickness)*0.4, h=thickness, center=true, chamfer_radius=thickness);
    }
}

