module shaft_collar(thickness, diameter) {
    // Create the base of the shaft collar
    cylinder(diameter, thickness, center=false, chamferRadius=1);

    // Create the mounting holes
    for (i = [0:3:4]) {
        // Calculate the coordinates for each hole
        angle = 360 * i / 4;
        x = diameter / 2 * cos(angle);
        y = diameter / 2 * sin(angle);

        // Create the mounting hole
        cylinder(diameter/10, thickness, center=false, chamferRadius=1, location=[x, y, thickness/2]);
    }
}

