module corner_gusset(size, thickness, chamfer) {
    // Dimensions
    size = size * 1000; // Convert to millimeters
    thickness = thickness * 1000; // Convert to millimeters
    chamfer = chamfer * 1000; // Convert to millimeters

    // Center the object
    translate([0, 0, size / 2]) {
        // Base
        translate([0, 0, thickness / 2]) {
            difference() {
                cube([size, size, thickness]);
                translate([0, 0, thickness]) {
                    cube([size, size, thickness / 2]);
                }
            }
            translate([0, size, thickness / 2]) {
                cube([size, size, thickness / 2]);
            }
        }
        // Chamfer
        translate([chamfer / 2, chamfer / 2, thickness / 2]) {
            cube([size - 2 * chamfer, size - 2 * chamfer, thickness - 2 * chamfer]);
