        // Chamfer the primary edges
        translate([thickness, thickness, thickness]) {
            cylinder(r=thickness, h=size - (2 * thickness) - 2 * thickness);
        }

        // Corners
        difference() {
            translate([0, 0, 0]) {
                cylinder(r=thickness, h=size - (2 * thickness) - 2 * thickness);
            }

            translate([size, 0, 0]) {
                cylinder(r=thickness, h=size - (2 * thickness) - 2 * thickness);
            }

            translate([0, size, 0]) {
                cylinder(r=thickness, h=size - (2 * thickness) - 2 * thickness);
            }

            translate([0, 0, size]) {
                cylinder(r=thickness, h=size - (2 * thickness) - 2 * thickness);
