    translate([0, 0, length / 2]) cube([diameter * 2, diameter * 2, thickness]);

    // Holes in the spacer
    translate([0, 0, thickness / 2 - holeDiameter / 2]) difference() {
        cylinder(holeDiameter, diameter, thickness);
        translate([diameter / 2, diameter / 2, -thickness / 2]) difference() {
            cylinder(holeDiameter, diameter, thickness);
        }
    }

    // Subtracted hole on the top surface
    translate([0, 0, -thickness / 2]) difference() {
        cylinder(holeDiameter, diameter, thickness);
    }
}

