module corner_gusset(
    size = 35,
    thickness = 4
) {
    // Main body
    cylinder(r1 = size / 2, r2 = size / 2 - thickness, h = size, center = true, resolution = 100);

    // First hole (centered at the top)
    translate([0, size / 2, size / 2 - thickness]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);

    // Second hole (centered at the bottom)
    translate([0, -size / 2, size / 2 - thickness]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);

    // Third hole (centered at the right)
    translate([size / 2 - thickness, 0, size / 2 - thickness]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);

    // Fourth hole (centered at the left)
    translate([-size / 2 + thickness, 0, size / 2 - thickness]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);

    // Sixth hole (centered at the back)
    translate([0, 0, size / 2 - thickness - thickness / 2]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);

    // Seventh hole (centered at the front)
    translate([0, 0, size / 2 - thickness + thickness / 2]) cylinder(r1 = thickness / 2, r2 = thickness / 2, h = thickness, center = true);
}

