// Create the flat mounting plate
module flatMountPlate(size, thickness) {
    // Calculate the dimensions
    $width = size - 2 * thickness;
    $height = size - 2 * thickness;

    // Create the top face
    rotate([0, 90, 0]) {
        translate([thickness, thickness, thickness]) {
            box(size=[width, height, thickness], center=true);
        }
    }

    // Create the bottom face
    translate([-thickness, -thickness, -thickness]) {
        box(size=[width, height, thickness], center=true);
    }

    // Create the center hole
    translate([thickness, thickness, thickness]) {
        rotate([0, 90, 0]) {
            difference() {
                cylinder(r=$centerHoleDiameter/2, h=$centerHoleDepth, center=true);
                cylinder(r=$centerHoleDiameter/2, h=$centerHoleDepth, center=true, $fn=$fn/2);
            }
        }
    }
}

