        }

        // Draw the sides of the recess
        translate([0, -collar_thickness/2, 0]) {
            cylinder(r=hex_side_length/2, h=collar_thickness, center=true);
        }

        translate([-collar_width/2, -collar_thickness/2, 0]) {
            cylinder(r=hex_side_length/2, h=collar_thickness, center=true);
        }
    }
}

