// Define global parameters
module hex_recess(radius, height, clearance, offset, height_offset) {
    translate([0, height_offset, 0]) {
        // Hex recess
        difference() {
            // Hexagon
            difference() {
                hull() {
                    circle(r);
                    translate([-radius/2, -radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([radius/2, radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([-radius/2, radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([radius/2, -radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                }
                difference() {
                    translate([-radius/2, -radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([radius/2, radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([-radius/2, radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                    translate([radius/2, -radius/2, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
                }
            }
        }
        translate([radius, 0, 0]) cylinder(r=radius, h=height*2+ clearance, center=true, resolution=200);
    }
}

