}

module shaftCollar(radius, thickness, recessHeight, recessRadius, recessDepth) {
    // Define the shaft collar
    cylinder(h=thickness, r1=radius, r2=radius - recessHeight, center=true);

    // Define the hexagonal recess
    hexagonPoints = [
        [0, recessRadius],
        [1, recessRadius],
        [1, recessRadius + recessDepth],
        [1, recessRadius],
        [0, recessRadius]
    ];
    hexagon = hull(points=hexagonPoints);

    // Subtract the hexagonal recess from the shaft collar
    result = cylinder(h=thickness, r1=radius, r2=radius - recessHeight, center=true) - hexagon;
}

