    corner_radius = size / 2.0 - thickness / 2.0;

    // Create the corner gusset
    difference() {
        // Create the base of the corner gusset
        difference() {
            sphere(corner_radius);
            translate([0, 0, thickness / 2]) {
                cylinder(diameter=2*corner_radius, height=thickness);
            }
        }
        translate([size, size, thickness / 2]) {
            cylinder(diameter=2*corner_radius, height=thickness);
        }
        translate([-size, size, thickness / 2]) {
            cylinder(diameter=2*corner_radius, height=thickness);
        }
        translate([-size, -size, thickness / 2]) {
            cylinder(diameter=2*corner_radius, height=thickness);
        }
    }

    // Create the mounting holes
    translate([0, 0, 0]) {
        difference() {
            cylinder(diameter=10, height=10);
            translate([0, 0, 5]) {
                cylinder(diameter=10, height=10);
            }
            translate([0, 10, 5]) {
                cylinder(diameter=10, height=10);
            }
            translate([10, 0, 5]) {
                cylinder(diameter=10, height=10);
            }
            translate([10, 10, 5]) {
                cylinder(diameter=10, height=10);
            }
        }
    }
}

