module LBracket(
    size = 71,  // mm
    thickness = 7, // mm
    hole_diameter = 2, // mm
    hole_depth = 0.1 // mm
) {
    // Main body of the L-bracket
    cube([size, size, size - thickness]);

    // Top hole for the handle
    translate([size/2 - hole_diameter/2, size/2, thickness/2 + hole_depth])
    cylinder(diameter=hole_diameter, height=hole_depth);

    // Bottom hole for the handle
    translate([size/2 - hole_diameter/2, -size/2, thickness/2 + hole_depth])
    cylinder(diameter=hole_diameter, height=hole_depth);

    // Front hole for the handle
    translate([size/2 - hole_diameter/2, size/2, -size/2 + hole_depth])
    cylinder(diameter=hole_diameter, height=hole_depth);

    // Back hole for the handle
    translate([size/2 - hole_diameter/2, -size/2, -size/2 + hole_depth])
    cylinder(diameter=hole_diameter, height=hole_depth);
}

