module flat_mounting_plate(size, thickness) {
    // Define the outer rectangle of the plate
    rectangle(size[0], size[1]);

    // Calculate the diameter of each hole
    hole_diameter = (size[0] - thickness) / 4;

    // Calculate the center coordinates of the holes
    hole_center_x = (size[0] - thickness) / 2;
    hole_center_y = (size[1] - thickness) / 2;

    // Create the holes using the cylinder operation
    difference() {
        // Create the outer rectangle
        rectangle(size[0], size[1]);

        // Create the holes using the cylinder operation
        for (x = [hole_center_x-hole_diameter/2, hole_center_x+hole_diameter/2]) {
            for (y = [hole_center_y-hole_diameter/2, hole_center_y+hole_diameter/2]) {
                cylinder(diameter=hole_diameter, height=thickness);
            }
        }
    }
}

