    difference() {
        // Top surface of the L-bracket
        translate([0, size[1], 0]) cube(size - [0, holeDiameter, 0]);

        // Front surface of the L-bracket
        translate([-size[0], 0, size[1]]) cube(size - [holeDiameter, 0, 0]);

        // Bottom surface of the L-bracket
        translate([0, 0, size[1]]) cube(size - [holeDiameter, 0, 0]);

        // Back surface of the L-bracket
        translate([size[0], 0, 0]) cube(size - [holeDiameter, 0, 0]);
    }

    // Central through-hole
    translate([size[0]/2 - holeDiameter/2, size[1]/2 - holeDiameter/2, size[1]/2 - holeDiameter/2]) difference() {
        cylinder(diameter = holeDiameter, height = size[1]);
    }
}

