module hexa_rubik(hex_rad) {
  translate([0, hex_rad, 0]) {
    translate([0, 2*hex_rad, 0]) {
      translate([0, 3*hex_rad, 0]) {
        cube([2*hex_rad, 2*hex_rad, thickness]);
      }
    }
    translate([0, hex_rad, thickness/2]) {
      translate([0, 2*hex_rad, thickness/2]) {
        translate([0, 3*hex_rad, thickness/2]) {
          cube([2*hex_rad, 2*hex_rad, thickness]);
        }
      }
    }
  }
}

