    linear_extrude(thickness) {
        difference() {
            cylinder(d=68, h=thickness, $fn=100);
            sphere(r=30, h=thickness);
            translate([0, 0, thickness/2]) rotate([0, 0, 90]) sphere(r=20, h=thickness);
        }
