    // Subtracting hole geometries
    difference() {
        translate([0, 0, thickness/2 - 5]) cylinder(d=40, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=20, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=10, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=5, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=3, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=2, h=5);
        translate([0, 0, thickness/2 - 5]) cylinder(d=1, h=5);
    }

    // Rotating hole for alignment
    rotate([0, 0, 90]) translate([0, 0, thickness/2]) cylinder(r=10, h=5);
}

