module u_channel_bracket(size, thickness) {
    // Define the dimensions of the bracket
    module bracket(size, thickness) {
        // Define the dimensions of the mounting holes
        module holes(diameter, spacing) {
            // Draw the holes
            for (i = [1:4]) {
                translate([i * spacing, 0, 0]) {
                    circle(diameter, r=0.5*diameter);
                }
            }
        }

        // Draw the bracket body
        difference() {
            cube(size, center=true);
            translate([-thickness/2, 0, 0]) {
                circle(diameter, r=0.5*diameter);
            }
            translate([thickness/2, 0, 0]) {
                circle(diameter, r=0.5*diameter);
            }
            translate([0, -thickness/2, 0]) {
                circle(diameter, r=0.5*diameter);
            }
            translate([0, thickness/2, 0]) {
                circle(diameter, r=0.5*diameter);
            }
        }

        // Add the mounting holes
        holes(3mm, 8mm);
    }

    // Draw the bracket with the specified size and thickness
    bracket(size, thickness);
}

