    difference() {
        cylinder(r=size/2+thickness, h=size/2-thickness, center=true);
        translate([0, 0, thickness]) cylinder(r=size/2+thickness, h=2*thickness, center=true);
    }

    // Inner flange
    difference() {
        cylinder(r=size/2-thickness, h=size/2-thickness, center=true);
        translate([0, 0, thickness]) cylinder(r=size/2-thickness, h=2*thickness, center=true);
    }
}

