        translate([0, 0, thickness]) {
            cylinder(r1=thickness, r2=size-2*chamfer, h=thickness+2*chamfer);
        }
    }

    // Define the secondary outer edge
    translate([0, 0, thickness]) {
        cylinder(r1=thickness, r2=size, h=thickness);
    }

    // Define the internal hole for the flange
    translate([0, 0, thickness]) {
        cylinder(r1=thickness, r2=size, h=thickness/2);
