module cylindricalSpacer(
  diameter = 38,
  thickness = 6
) {
  // Create the main body of the spacer
  cylinder(
    r = diameter / 2,
    h = thickness,
    center = [0, 0, thickness / 2]
  );

  // Create the outer ring for the spacer
  cylinder(
    r = diameter / 2 + thickness,
    h = thickness,
    center = [0, 0, 0]
  );

  // Create the hole in the middle of the spacer
  cylinder(
    r = diameter / 4,
    h = thickness,
    center = [0, 0, thickness / 2]
  );

  // Subtract the hole from the main body
  difference() {
    cylinder(
      r = diameter / 2,
      h = thickness,
      center = [0, 0, thickness / 2]
    );
    cylinder(
      r = diameter / 4,
      h = thickness,
      center = [0, 0, thickness / 2]
    );
  }
}

