module hexagonal_standoff(size, thickness) {
  // Parameters
  size = size || 24; // Overall size in mm
  thickness = thickness || 6; // Thickness of the standoff in mm

  // Main body
  cylinder(r=size/2, h=size/2, center=true, chamfer=true, center_radius=thickness/2);

  // Hexagonal hole
  // Define the vertices of the hexagon
  vertex(0, 0, size);
  vertex(size/2, -thickness, 0);
  vertex(size, -thickness/2, 0);
  vertex(size/2, 0, -size);
  vertex(0, thickness, -size);
  vertex(-size/2, thickness, 0);
  vertex(-size, thickness/2, 0);
  vertex(-size/2, 0, size);

  // Hexagonal hole - extrude along the X-axis
  translate([size/2, 0, 0]) {
    extrude([0, thickness, 0]) {
      hexagon(size=thickness*2);
    }
  }

  // Hexagonal hole - extrude along the Y-axis
  translate([0, size/2, 0]) {
    extrude([thickness, 0, 0]) {
      hexagon(size=thickness*2);
    }
  }

  // Hexagonal hole - extrude along the Z-axis
  translate([0, 0, size/2]) {
    extrude([0, 0, thickness]) {
      hexagon(size=thickness*2);
    }
  }
}

// Example usage
hexagonal_standoff(size=24, thickness=6);

