        translate([size/2, size/2, size/2]) {
            hexagon(hex_size = size/2, thickness = thickness/2, chamfer = chamfer);
        }
    }

    // Top of the standoff
    difference() {
        cube(size = size, center = true);
        translate([size/2, size/2, size/2]) {
            hexagon(hex_size = size/2, thickness = thickness/2, chamfer = chamfer);
