module u_channelBracket(
    size = 48, // Overall size in mm
    thickness = 9, // Thickness in mm
    hole_diameter = 5, // Diameter of the through-hole in mm
    hole_depth = 1 // Depth of the through-hole in mm
) {
    // Create the basic U-channel shape
    difference() {
        // Bottom face
        translate([0, 0, 0]) cube([size, size, thickness]);
        // Top face
        translate([0, 0, thickness]) cube([size, size, thickness]);
        // Bottom corners
        translate([0, 0, thickness]) cube([thickness, thickness, thickness]);
        translate([size, 0, thickness]) cube([thickness, thickness, thickness]);
        translate([0, size, thickness]) cube([thickness, thickness, thickness]);
        translate([size, size, thickness]) cube([thickness, thickness, thickness]);
    }
    // Create the through-hole
    translate([0, 0, hole_depth / 2]) sphere(r = hole_diameter / 2);
}

