module flange_bushing(size, thickness) {
    // Define the dimensions of the bushing
    // size: overall diameter (89mm)
    // thickness: wall thickness (11mm)
    // Circular mounting holes: four arranged in a rectangular pattern

    // Calculate the radius of the circular mounting holes
    mounting_radius = size / 4;

    // Define the rectangular pattern for the holes
    hole_width = mounting_radius * 2;
    hole_height = mounting_radius * 2;

    // Define the offset between the holes
    hole_offset = mounting_radius / 4;

    // Create the body of the bushing
    cylinder(d=size, h=thickness, center=true);

    // Create the mounting holes
    for (i = [0:size-2:hole_width]) {
        for (j = [0:size-2:hole_height]) {
            translate([i, j, mounting_radius]) cylinder(d=hole_radius, h=thickness, center=true, chamfer=true);
        }
    }
}

