// Create the U-channel bracket
union() {
  // Base of the U-channel
  linear_extrude(thickness, $fn=32) {
    polygon([
      [0, 0],
      [size, 0],
      [size, thickness],
      [0, thickness]
    ]);
  };

  // Top part of the U-channel
  linear_extrude(thickness, $fn=32) {
    polygon([
      [size / 2, thickness],
      [size / 2, thickness + hex_height],
      [size, thickness + hex_height],
      [size / 2, thickness]
    ]);
  };

  // Bottom part of the U-channel
  linear_extrude(thickness, $fn=32) {
    polygon([
      [size / 2, 0],
      [size / 2, -hex_height],
      [size, -hex_height],
      [size / 2, 0]
    ]);
  };

  // Hexagonal recess
  difference() {
    cylinder(r=hex_radius, h=hex_height, center=true);
    translate([0, hex_height / 2, 0]) {
      polygon([
        [0, hex_height],
        [hex_radius, 0],
        [hex_radius, hex_height],
        [0, hex_height]
      ]);
    };
  };
}

