        cylinder(h=thickness, r=5, $fn=50); // Top corner hole
    }
    translate([-size/2, size/2, thickness/2]) {
        cylinder(h=thickness, r=5, $fn=50); // Bottom corner hole
    }
    translate([-size/2, -size/2, thickness/2]) {
