module pipe_flange(radius, thickness) {
    // Create the base of the pipe flange
    cylinder(r=radius+thickness, h=thickness, center=true, chamfer=1mm);

    // Create four circular mounting holes arranged in a rectangular pattern
    difference() {
        union() {
            translate([0, radius, 0]) cylinder(r=thickness/2, h=radius+thickness, center=true, chamfer=1mm);
            translate([radius, radius, 0]) cylinder(r=thickness/2, h=radius+thickness, center=true, chamfer=1mm);
            translate([2*radius, radius, 0]) cylinder(r=thickness/2, h=radius+thickness, center=true, chamfer=1mm);
            translate([3*radius, radius, 0]) cylinder(r=thickness/2, h=radius+thickness, center=true, chamfer=1mm);
        }
        translate([radius, radius, -thickness]) cube([4*radius, 2*radius, thickness]);
    }
}

