module corner_gusset(size, thickness) {
    // Calculate the dimensions for the gusset
    width = size;
    height = size;
    diameter = 2 * thickness;
    hole_diameter = diameter / 2;
    hole_spacing = diameter / 2;

    // Draw the base of the gusset
    translate([-(width / 2), -(height / 2), thickness / 2]) {
        difference() {
            // Base part
            cube([width, height, thickness]);

            // Holes for mounting
            translate([-(hole_spacing), -(hole_spacing), thickness / 2]) {
                cylinder(diameter=hole_diameter, height=hole_diameter);
            }
            translate([hole_spacing, -(hole_spacing), thickness / 2]) {
                cylinder(diameter=hole_diameter, height=hole_diameter);
            }
            translate([-(hole_spacing), hole_spacing, thickness / 2]) {
                cylinder(diameter=hole_diameter, height=hole_diameter);
            }
            translate([hole_spacing, hole_spacing, thickness / 2]) {
                cylinder(diameter=hole_diameter, height=hole_diameter);
            }
        }
    }
}

