    cylinder(r=30, h=size/2, center=true, chamfer=5);
    // Outer cylindrical part
    cylinder(r=size/2+thickness, h=size/2, center=true, chamfer=5);
    // Inner cylindrical part
    cylinder(r=size/2-thickness, h=size/2, center=true, chamfer=5);
    // Mounting holes
    translate([0, size/2-thickness, 0]) cylinder(r=mount_hole_diameter/2, h=size/2, center=true, chamfer=5);
    translate([0, size/2-thickness, 0]) cylinder(r=mount_hole_diameter/2, h=size/2, center=true, chamfer=5);
    translate([size/2-thickness, 0, 0]) cylinder(r=mount_hole_diameter/2, h=size/2, center=true, chamfer=5);
    translate([size/2-thickness, 0, 0]) cylinder(r=mount_hole_diameter/2, h=size/2, center=true, chamfer=5);
}

