module pipe_flange(radius, thickness, height) {
    // Main body of the pipe flange
    translate([0, 0, height/2])
    cylinder(r=radius, h=height);

    // Subtracted holes
    translate([radius, 0, height/2])
    cylinder(r=thickness/2, h=height/2);

    translate([radius, 0, -height/2])
    cylinder(r=thickness/2, h=height/2);

    translate([0, thickness, height/2])
    cylinder(r=radius, h=height/2);

    translate([-radius, thickness, height/2])
    cylinder(r=radius, h=height/2);

    translate([radius, thickness, -height/2])
    cylinder(r=radius, h=height/2);

    translate([-radius, thickness, -height/2])
    cylinder(r=radius, h=height/2);
}

