module circular_pipe_flange(r, t) {
    // Define the main body of the pipe flange
    difference() {
        cylinder(r - t, r + t, 100, center=true, chamfer=0);
        // Define the holes with the specified depth
        for (i = [1:5]) {
            translate([0, 0, i * t]) {
                difference() {
                    cylinder(r - t, r + t, 50, center=true, chamfer=0);
                    translate([0, 0, 2 * t]) {
                        difference() {
                            cylinder(r - t, r + t, 25, center=true, chamfer=0);
                            translate([0, 0, 3 * t]) {
                                difference() {
                                    cylinder(r - t, r + t, 20, center=true, chamfer=0);
                                    translate([0, 0, 4 * t]) {
                                        cylinder(r - t, r + t, 15, center=true, chamfer=0);
                                        translate([0, 0, 5 * t]) {
                                            cylinder(r - t, r + t, 10, center=true, chamfer=0);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

