// Parameterized cylindrical spacer with mounting holes
// Overall size: 50mm x 50mm (diameter), 4mm thick
module cylindricalSpacer(diameter, thickness) {
    // Create the cylinder
    cylinder(diameter=diameter, height=thickness);

    // Define the hole radius
    holeRadius = diameter / 4;

    // Define the hole spacing
    holeSpacing = diameter / 4;

    // Define the number of holes along each axis
    numHoles = 3; // Example: 3 holes along each axis

    // Create the mounting holes
    for (y = range(numHoles)) {
        for (x = range(numHoles)) {
            // Calculate the hole position
            holeX = (x * holeSpacing) - holeRadius;
            holeY = (y * holeSpacing) - holeRadius;

            // Create the hole
            translate([holeX, holeY, 0]) {
                cylinder(diameter=holeRadius, height=2 * holeRadius);
            }
        }
    }
}

