            cylinder(radii=[hole_radius, hole_radius], height=size, center=true, resolution=100);
        }
    }

    // Bottom face
    translate([0, 0, 0]) {
        rotate([90, 0, 0]) {
            cylinder(radii=[hole_radius, hole_radius], height=size, center=true, resolution=100);
        }
    }

    // Side faces
    translate([0, size/2, 0]) {
        rotate([0, 0, 90]) {
            cylinder(radii=[hole_radius, hole_radius], height=size, center=true, resolution=100);
        }
    }

    translate([size/2, 0, 0]) {
        rotate([0, 0, 90]) {
            cylinder(radii=[hole_radius, hole_radius], height=size, center=true, resolution=100);
        }
    }

    // Mounting holes
    translate([hole_radius, hole_radius, thickness]) {
        rotate([0, 0, 0]) {
            cylinder(radii=[hole_radius, hole_radius], height=thickness, center=true, resolution=100);
        }
    }

    translate([size/2 - hole_radius, hole_radius, thickness]) {
        rotate([0, 0, 0]) {
            cylinder(radii=[hole_radius, hole_radius], height=thickness, center=true, resolution=100);
        }
    }

    translate([hole_radius, size/2 - hole_radius, thickness]) {
        rotate([0, 0, 0]) {
            cylinder(radii=[hole_radius, hole_radius], height=thickness, center=true, resolution=100);
        }
    }

    translate([size/2 - hole_radius, size/2 - hole_radius, thickness]) {
        rotate([0, 0, 0]) {
            cylinder(radii=[hole_radius, hole_radius], height=thickness, center=true, resolution=100);
        }
    }
}

