module LBracket(size, thickness) {
    // Define the overall dimensions
    size_x = size * 2.5;
    size_y = size;
    size_z = thickness;

    // Create the body of the bracket
    difference() {
        // Create the frame
        difference() {
            // Create the base
            difference() {
                // Create the top
                difference() {
                    // Create the bottom
                    difference() {
                        // Create the body
                        union() {
                            // Create the top rectangle
                            translate([0, size_y, -size_z / 2])
                                rectangle([size_x, size_y, size_z / 2]);

                            // Create the bottom rectangle
                            translate([0, -size_y, -size_z / 2])
                                rectangle([size_x, size_y, size_z / 2]);

                            // Create the side rectangles
                            translate([-size_x / 2, 0, -size_z / 2])
                                rectangle([size_x / 2, size_y, size_z / 2]);

                            translate([size_x / 2, 0, -size_z / 2])
                                rectangle([size_x / 2, size_y, size_z / 2]);
                        }
                    }
                }
            }
        }
    }
}

