module u_channel_bracket(diameter, height, thickness) {
    // Top face
    linear_extrude(height) {
        difference() {
            translate([0, 0, thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
            translate([0, 0, -thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
        }
    }

    // Middle face
    linear_extrude(height) {
        difference() {
            translate([0, 0, thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
            translate([0, 0, -thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
        }
    }

    // Bottom face
    linear_extrude(height) {
        difference() {
            translate([0, 0, thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
            translate([0, 0, -thickness / 2]) {
                circle(r = diameter / 2, center = [0, 0, 0]);
            }
        }
    }

    // Hole in the middle face
    translate([0, 0, thickness / 2]) {
        cylinder(r = diameter / 2, h = thickness / 4, center = [0, 0, 0]);
    }
}

