module hexagonal_standoff(
    size = 35, // mm
    thickness = 15 // mm
) {
    // Create the main body of the standoff
    cube([size, size, thickness]);

    // Define the hexagonal hole dimensions
    hex_size = size / 2;
    hex_height = thickness / 2;
    hex_radius = hex_size / (2 * tan(PI / 6));

    // Define the center of the hexagonal hole
    hex_center = [hex_size / 2, hex_size / 2, 0];

    // Create the hexagonal hole
    intersection() {
        // Define the center of the hexagonal hole
        hex_center = [hex_size / 2, hex_size / 2, 0];

        // Create the vertices of the hexagon
        vertices = [
            [hex_center[0] - hex_radius, hex_center[1] + hex_radius, hex_height],
            [hex_center[0] + hex_radius, hex_center[1] + hex_radius, hex_height],
            [hex_center[0] + hex_radius, hex_center[1] - hex_radius, hex_height],
            [hex_center[0] - hex_radius, hex_center[1] - hex_radius, hex_height],
            [hex_center[0] - hex_radius, hex_center[1] + hex_radius, -hex_height],
            [hex_center[0] + hex_radius, hex_center[1] + hex_radius, -hex_height],
            [hex_center[0] + hex_radius, hex_center[1] - hex_radius, -hex_height],
            [hex_center[0] - hex_radius, hex_center[1] - hex_radius, -hex_height]
        ];

        // Create the hexagon
        polyhedron(vertices, faces);
    };

    // Subtract the hexagonal hole from the main body
    difference() {
        cube([size, size, thickness]);
        intersection() {
            vertices = [
                [hex_center[0] - hex_radius, hex_center[1] + hex_radius, hex_height],
                [hex_center[0] + hex_radius, hex_center[1] + hex_radius, hex_height],
                [hex_center[0] + hex_radius, hex_center[1] - hex_radius, hex_height],
                [hex_center[0] - hex_radius, hex_center[1] - hex_radius, hex_height],
                [hex_center[0] - hex_radius, hex_center[1] + hex_radius, -hex_height],
                [hex_center[0] + hex_radius, hex_center[1] + hex_radius, -hex_height],
                [hex_center[0] + hex_radius, hex_center[1] - hex_radius, -hex_height],
                [hex_center[0] - hex_radius, hex_center[1] - hex_radius, -hex_height]
            ];

            polyhedron(vertices, faces);
        };
    };
}

