module cylindrical_spacer(size, thickness) {
    // Create the cylindrical body
    cylinder(h = thickness, d = size * 2, center = true, start_radius = 0, end_radius = size * 2);

    // Calculate the center of the cylindrical body
    translate([0, 0, thickness/2]) {
        // Create the holes
        difference() {
            // Create the holes in the corners
            difference() {
                cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                translate([size*2/2, size*2/2, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
                translate([-size*2/2, size*2/2, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
                translate([-size*2/2, -size*2/2, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
            }
            difference() {
                cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                translate([size*2/2, 0, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
                translate([0, size*2/2, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
                translate([0, -size*2/2, -thickness/2]) {
                    cylinder(h = thickness, d = 5, center = true, start_radius = 0, end_radius = 5);
                }
            }
        }
    }
}

