module cylinder_spacer(radius, height, outer_radius, inner_radius, thickness) {
    // Create the main body
    cylinder(body_radius=outer_radius, height=height, center=true);

    // Create the holes
    difference() {
        cylinder(body_radius=outer_radius, height=height, center=true);
        cylinder(body_radius=inner_radius, height=height, center=true);
    };

    // Ensure all subtracted hole geometries extend past the main body on the Z-axis
    difference() {
        cylinder(body_radius=outer_radius, height=height, center=true);
        difference() {
            cylinder(body_radius=outer_radius, height=thickness, center=true);
            cylinder(body_radius=outer_radius, height=thickness, center=true);
        };
    };

    // Create the bottom cap
    cylinder(radius=outer_radius, height=thickness, center=true);

    // Create the top cap
    cylinder(radius=outer_radius, height=thickness, center=true);

    // Ensure all subtracted hole geometries extend past the main body on the Z-axis
    difference() {
        cylinder(body_radius=outer_radius, height=height, center=true);
        difference() {
            cylinder(body_radius=outer_radius, height=thickness, center=true);
            cylinder(body_radius=outer_radius, height=thickness, center=true);
        };
    };
}

