            translate([0, 0, thickness - chamferWidth]) cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
        }
    }

    // Secondary outer edges
    difference() {
        cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
        translate([0, size, 0]) cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
        translate([size, 0, 0]) cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
    }

    // Secondary inner edges
    difference() {
        cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
        translate([size / 2, size / 2, thickness - chamferWidth]) cylinder(d = 2 * chamferWidth, h = size - 2 * chamferWidth);
    }

    // Top and bottom edges
    translate([0, 0, thickness / 2]) cylinder(d = size - 2 * chamferWidth, h = thickness);
    translate([0, 0, size - thickness / 2]) cylinder(d = size - 2 * chamferWidth, h = thickness);
}

