module LBracket(size = 50, thickness = 5, chamfer = 2) {
    // Define the L-bracket geometry
    // Base
    difference() {
        cube([size, thickness, thickness]);
        translate([0, thickness / 2, thickness / 2]) {
            difference() {
                cube([size, thickness, thickness]);
                translate([chamfer, 0, 0]) {
                    cube([chamfer, thickness, thickness]);
                }
            }
        }
    }

    // Top
    difference() {
        cube([size, thickness, thickness]);
        translate([0, thickness / 2, size / 2]) {
            difference() {
                cube([size, thickness, thickness]);
                translate([chamfer, 0, 0]) {
                    cube([chamfer, thickness, thickness]);
                }
            }
        }
    }
}

