module l_bracket(size, thickness) {
    cylinder(r=10, h=2*thickness, center=1);
    translate([0, thickness, 0]) {
        translate([-10, 0, 0]) {
            cylinder(r=10, h=2*thickness, center=1);
        }
        translate([10, 0, 0]) {
            cylinder(r=10, h=2*thickness, center=1);
        }
    }
    translate([0, 0, -thickness]) {
        translate([0, -thickness, 0]) {
            cylinder(r=10, h=2*thickness, center=1);
        }
        translate([0, thickness, 0]) {
            cylinder(r=10, h=2*thickness, center=1);
        }
    }
}

// Create a hexagonal recess
module hex_recess(size) {
    translate([0, 0, 0]) {
        translate([-size/2, 0, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([size/2, 0, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([0, -size/2, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([0, size/2, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
    }
}

// Create a hole in the L-bracket
module hole(size) {
    translate([0, 0, 0]) {
        translate([-size/2, 0, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([size/2, 0, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([0, -size/2, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
        translate([0, size/2, 0]) {
            cylinder(r=size/2, h=size/2, center=1);
        }
    }
}

