    // Subtracted holes
    translate([-size/2, size/2, thickness/2]) {
        difference() {
            cylinder(d=size, h=thickness, center=true);
            translate([-size/4, size/4, thickness/2]) {
                sphere(r=size/8);
            }
        }
    }

    translate([-size/2, -size/2, thickness/2]) {
        difference() {
            cylinder(d=size, h=thickness, center=true);
            translate([-size/4, -size/4, thickness/2]) {
                sphere(r=size/8);
            }
        }
    }

    translate([size/2, -size/2, thickness/2]) {
        difference() {
            cylinder(d=size, h=thickness, center=true);
            translate([size/4, -size/4, thickness/2]) {
                sphere(r=size/8);
            }
        }
    }

    translate([size/2, size/2, thickness/2]) {
        difference() {
            cylinder(d=size, h=thickness, center=true);
            translate([size/4, size/4, thickness/2]) {
                sphere(r=size/8);
            }
        }
    }
}

