    // Second subtractive hole
    translate([radius - 1, 0, thickness + 2]) cylinder(r = radius - 2, h = thickness, center = true);

    // Third subtractive hole
    translate([radius - 2, 0, thickness + 2]) cylinder(r = radius - 3, h = thickness, center = true);

    // Fourth subtractive hole
    translate([radius - 3, 0, thickness + 2]) cylinder(r = radius - 4, h = thickness, center = true);

