module flanged_bushing(radius, height, wall_thickness, outer_radius, inner_radius) {
    // Main body
    cylinder(radius, height, center = [0, 0, height/2]);

    // Flange
    translate([0, 0, -wall_thickness/2]) {
        cylinder(radius, wall_thickness, center = [0, 0, 0]);
    }

    // Hole in the body
    translate([0, 0, -wall_thickness/2]) {
        cylinder(radius, height, center = [0, 0, 0]);
        translate([0, 0, wall_thickness/2]) {
            difference() {
                cylinder(radius, height, center = [0, 0, 0]);
                cylinder(inner_radius, height, center = [0, 0, 0]);
            }
        }
    }

    // Outer hole
    translate([0, 0, -wall_thickness/2]) {
        cylinder(radius, height, center = [0, 0, 0]);
        translate([0, 0, wall_thickness/2]) {
            difference() {
                cylinder(radius, height, center = [0, 0, 0]);
                cylinder(outer_radius, height, center = [0, 0, 0]);
            }
        }
    }
}

