// Define the corner gusset parameters
module corner_gusset(params = [89, 15]) {
    // Main body
    difference() {
        // Define the main body geometry
        // Example: A rectangular prism
        cube([params[0], params[0], params[2]]);

        // Define the inner circle
        circle(r = 3, d = params[0] / 2);

        // Define the outer circle
        circle(r = 4, d = params[0] / 2);
    }

    // Subtracted hole geometries
    difference() {
        // Define the hole geometry on the bottom edge
        translate([params[0] / 2, params[0] / 2, params[2]]) cylinder(r = 1, h = params[2] - 1);

        // Define the hole geometry on the top edge
        translate([-params[0] / 2, params[0] / 2, params[2]]) cylinder(r = 1, h = params[2] - 1);

        // Define the hole geometry on the left edge
        translate([params[0] / 2, params[0] / 2, params[2]]) cylinder(r = 1, h = params[2] - 1);

        // Define the hole geometry on the right edge
        translate([-params[0] / 2, params[0] / 2, params[2]]) cylinder(r = 1, h = params[2] - 1);
    }
}

