module flanged_bushing(radius, thickness, hex_radius, hex_height) {
  // Define the outer cylinder
  cylinder(r = radius + thickness / 2, h = thickness, center = [0, 0, 0], chamfer = [0.1, 0.1, 0.1]);

  // Define the hexagonal recess
  difference() {
    // Inner hexagon
    difference() {
      // Hexagon center
      translate([radius, 0, 0]) {
        difference() {
          // Inner hexagon vertices
          circle(r = hex_radius, segments = 6);
          translate([0, hex_radius, 0]) circle(r = hex_radius, segments = 6);
          translate([-hex_radius, 0, 0]) circle(r = hex_radius, segments = 6);
          translate([0, -hex_radius, 0]) circle(r = hex_radius, segments = 6);
          translate([hex_radius, 0, 0]) circle(r = hex_radius, segments = 6);
        }
      }
      // Hexagon corners
      translate([radius, 0, thickness / 2]) sphere(r = hex_radius / 4);
      translate([-radius, 0, thickness / 2]) sphere(r = hex_radius / 4);
      translate([0, radius, thickness / 2]) sphere(r = hex_radius / 4);
      translate([0, -radius, thickness / 2]) sphere(r = hex_radius / 4);
    }

    // Outer hexagon
    translate([radius, 0, thickness / 2]) difference() {
      // Outer hexagon vertices
      circle(r = hex_radius, segments = 6);
      translate([0, hex_radius, thickness / 2]) circle(r = hex_radius, segments = 6);
      translate([-hex_radius, 0, thickness / 2]) circle(r = hex_radius, segments = 6);
      translate([0, -hex_radius, thickness / 2]) circle(r = hex_radius, segments = 6);
      translate([hex_radius, 0, thickness / 2]) circle(r = hex_radius, segments = 6);
    }

    // Hexagon corners
    translate([radius, 0, thickness / 2]) sphere(r = hex_radius / 4);
    translate([-radius, 0, thickness / 2]) sphere(r = hex_radius / 4);
    translate([0, radius, thickness / 2]) sphere(r = hex_radius / 4);
    translate([0, -radius, thickness / 2]) sphere(r = hex_radius / 4);
  }

  // Center hole
  translate([radius + thickness / 4, 0, 0]) sphere(r = hex_radius / 4);
}

