module flanged_bushing(
    outer_radius = 65,
    thickness = 10,
    chamfer_size = 2
) {
    // Define the outer edge with chamfer
    cylinder(
        radius = outer_radius - chamfer_size,
        height = thickness,
        center = [0, 0, 0]
    );

    // Define the flange
    cylinder(
        radius = chamfer_size,
        height = thickness,
        center = [0, thickness / 2, 0]
    );

    // Union to create the final bushing
    union() {
        cylinder(
            radius = outer_radius,
            height = thickness,
            center = [0, 0, 0]
        );

        cylinder(
            radius = chamfer_size,
            height = thickness,
            center = [0, thickness / 2, 0]
        );
    }
}

