module shaft_collar(size, thickness) {
    // Outer cylinder
    cylinder(r=0.5*size, h=size, center=true, $fn=100);

    // Hexagonal recess
    // Hexagon vertices
    translate([0, thickness/2, 0]) {
        polygon([
            [0, 0],
            [1, 0.866],
            [0.5, 0.5],
            [-0.5, 0.5],
            [-1, 0.866],
            [0, 0]
        ]);
    }

    // Remove the hexagonal recess
    difference() {
        union() {
            cylinder(r=0.5*size, h=size, center=true, $fn=100);
            translate([0, thickness/2, 0]) {
                polygon([
                    [0, 0],
                    [1, 0.866],
                    [0.5, 0.5],
                    [-0.5, 0.5],
                    [-1, 0.866],
                    [0, 0]
                ]);
            }
        };
        cylinder(r=0.5*size-0.5*thickness, h=size-2*thickness, center=true, $fn=100);
    }
}

