module u_channel_bracket(size=25, thickness=14, hex_diameter=10, hex_height=5) {
    // Define the U-channel
    u_channel(size, thickness, hex_diameter, hex_height);

    // Define the hexagonal recess
    hex_recess(hex_diameter, hex_height);

    // Subtract the hexagonal recess from the U-channel
    difference() {
        u_channel(size, thickness, hex_diameter, hex_height);
        hex_recess(hex_diameter, hex_height);
    }
}

// Define the U-channel module
module u_channel(size, thickness, hex_diameter, hex_height) {
    // Define the bottom part of the U-channel
    difference() {
        rectangle(size[0], size[1], thickness);
        translate([0, 0, thickness / 2]) {
            cylinder(hex_diameter, hex_height, hex_diameter / 2);
        }
        translate([size[0], 0, thickness / 2]) {
            cylinder(hex_diameter, hex_height, hex_diameter / 2);
        }
    }
}

// Define the hexagonal recess module
module hex_recess(hex_diameter, hex_height) {
    // Define the center of the hexagon
    center = [hex_diameter / 2, hex_diameter / 2, hex_height / 2];

    // Define the points of the hexagon
    points = [
        [hex_diameter / 2, hex_diameter / 2, hex_height / 2],
        [hex_diameter / 2, -hex_diameter / 2, hex_height / 2],
        [-hex_diameter / 2, -hex_diameter / 2, hex_height / 2],
        [-hex_diameter / 2, hex_diameter / 2, hex_height / 2],
        [-hex_diameter / 2, -hex_diameter / 2, hex_height / 2],
        [hex_diameter / 2, hex_diameter / 2, hex_height / 2]
    ];

    // Create the hexagon
    polygon(points);
}

// Call the main module with the desired parameters
u_channel_bracket(size=25, thickness=14, hex_diameter=10, hex_height=5);

module mounting_plate(size=53mm, thickness=7mm, chamfer=2mm) {
    // Define the corners of the plate
    // This is a simple 2D polygon representing the corners
    polyhedron(
        [size/2, size/2, thickness/2], // Top-left corner
        [size/2, size/2, -thickness/2], // Top-right corner
        [size/2, -size/2, thickness/2], // Bottom-right corner
        [size/2, -size/2, -thickness/2], // Bottom-left corner
        [0, size/2, thickness/2], // Top-center corner
        [0, size/2, -thickness/2], // Top-center corner
        [-size/2, size/2, thickness/2], // Bottom-center corner
        [-size/2, size/2, -thickness/2], // Bottom-center corner
        [0, -size/2, thickness/2], // Bottom-center corner
        [0, -size/2, -thickness/2] // Bottom-center corner
    );
}

// Call the module with specific parameters
mounting_plate(53mm, 7mm, 2mm);

// Define the dimensions
module corner_gusset(size, thickness) {
    // Create the corner gusset body
    difference() {
        cylinder(d=size-2*thickness, h=thickness, $fn=50);
        // Add the central through-hole
        difference() {
            cylinder(d=size-2*thickness, h=thickness, $fn=50);
            sphere(r=thickness/2);
        }
    }
}

// Example usage
corner_gusset(size=50, thickness=14);

module flanged_bushing(size, thickness) {
    // Main body
    translate([0, 0, 0]) {
        cylinder(r1=size/2, r2=size/2+thickness/2, h=size+thickness, center=false);
    }

    // Top flange
    translate([0, 0, size+thickness/2]) {
        cylinder(r1=thickness/2, r2=size/2+thickness/2, h=thickness, center=false);
    }

    // Bottom flange
    translate([0, 0, -size-thickness/2]) {
        cylinder(r1=thickness/2, r2=size/2+thickness/2, h=thickness, center=false);
    }

    // Outer flange
    translate([0, 0, -size-2*thickness/2]) {
        cylinder(r1=size/2, r2=size/2+thickness/2, h=2*thickness, center=false);
    }
}

