module rectangular_base_project_enclosure_base(
    base_thickness = 8mm,
    base_width = 21mm,
    base_length = 21mm
) {
    // Base plate
    translate([base_length / 2, base_width / 2, -base_thickness / 2]) {
        cube([base_length, base_width, base_thickness]);
    }

    // Extended mounting tab
    translate([base_length / 2, base_width / 2, -base_thickness / 2]) {
        difference() {
            cube([base_length, base_width, base_thickness]);
            translate([0, 0, base_thickness / 2]) {
                rectangle(width = base_length, height = 2);
            }
        }
    }
}

