// Parameterized OpenSCAD code for a cylindrical spacer
module cylinder_spacer(size, thickness, through_hole_diameter) {
    // Define the cylinder
    cylinder(size - 2 * thickness, thickness);

    // Define the through-hole
    difference() {
        cylinder(through_hole_diameter / 2, thickness);
        translate([0, 0, thickness - through_hole_diameter / 2]);
        cylinder(through_hole_diameter / 2, thickness);
    }
}

