// Parameterized Cylindrical Spacer
module cylindrical_spacer(
    length = 68,  // mm
    thickness = 4,  // mm
    chamfer_radius = 2  // mm
) {
    // Create the cylindrical part
    cylinder(
        r = length / 2,
        h = thickness,
        center = [0, 0, 0],
        chamfer = [0, 0, chamfer_radius]
    );

    // Create the secondary cylindrical part
    cylinder(
        r = length / 2,
        h = thickness,
        center = [0, 0, -thickness],
        chamfer = [0, 0, chamfer_radius]
    );
}

// Call the module with parameters
cylindrical_spacer();

