module structural_l_bracket(
    diameter = 20, // mm
    height = 70, // mm
    depth = 10  // mm
) {
    // Define the main body of the bracket
    cube([diameter, height, depth]);

    // Define the hole for the screw
    difference() {
        union() {
            translate([0, height - 5, depth]) {
                cylinder(r = diameter / 2, h = 10, center = true);
            }

            translate([diameter / 2, height - 5, depth]) {
                cylinder(r = diameter / 2, h = 10, center = true);
            }
        }

        translate([diameter / 2, 0, depth]) {
            cylinder(r = diameter / 2, h = 10, center = true);
        }

        translate([diameter / 2, height, 0]) {
            cylinder(r = diameter / 2, h = 10, center = true);
        }

        translate([diameter / 2, height, diameter]) {
            cylinder(r = diameter / 2, h = 10, center = true);
        }

        translate([diameter / 2, height, diameter / 2]) {
            cylinder(r = diameter / 2, h = 10, center = true);
        }
    }
}

