        // Center hole
        translate([size/2, size/2, thickness/2]) cylinder(r=holeDiameter/2, h=size+thickness, center=false, segments=50);
        // Second hole
        translate([size/2, size/2, thickness/2]) cylinder(r=holeDiameter/2, h=size+thickness, center=false, segments=50);
        // Third hole
        translate([size/2, size/2, thickness/2]) cylinder(r=holeDiameter/2, h=size+thickness, center=false, segments=50);
        // Fourth hole
        translate([size/2, size/2, thickness/2]) cylinder(r=holeDiameter/2, h=size+thickness, center=false, segments=50);
    }
}

