module l_bracket(
    size = [96, 6],
    hole_diameter = 2,
    hole_spacing = 4
) {
    // Create the rectangular part of the L-bracket
    difference() {
        // Bottom part
        translate([0, size[1] - hole_spacing, 0])
        rectangle(size = [size[0], hole_spacing * 2], $fn = 100);

        // Top part
        translate([0, size[1], 0])
        rectangle(size = [size[0], hole_spacing * 2], $fn = 100);

        // Vertical part
        translate([size[0] / 2, 0, 0])
        rectangle(size = [hole_spacing, size[1]], $fn = 100);
    }

    // Add mounting holes
    for (i = [0:3]) {
        translate([i * (hole_spacing + hole_spacing / 2), hole_spacing / 2, 0])
        cylinder(diameter = hole_diameter, height = size[1], $fn = 100);
    }
}

