  cylinder(h=size, r=size/2 - thickness/2, center=true, $fn=100);

  // Create the mounting holes
  for (i = [0:num_holes-1]) {
    translate([ hole_diameter/2 + i * (2 * hole_diameter + thickness), 0]) {
      cylinder(h=thickness, r=hole_diameter/2, center=true, $fn=100);
    }
  }
}

