// Define the parameters
module pipe_flange(radius, thickness, height) {
    // Draw the main pipe
    cylinder(r=radius, h=height, center=true);

    // Draw the outer ring
    difference() {
        cylinder(r=radius, h=height, center=true);
        cylinder(r=radius+thickness, h=height, center=true);
    }

    // Draw the inner ring
    difference() {
        cylinder(r=radius, h=height, center=true);
        cylinder(r=radius-thickness, h=height, center=true);
    }

    // Draw the outer hole
    difference() {
        cylinder(r=radius, h=height, center=true);
        cylinder(r=radius+thickness, h=height, center=true);
        cylinder(r=radius+thickness/2, h=height, center=true);
        cylinder(r=radius-thickness/2, h=height, center=true);
    }

    // Draw the inner hole
    difference() {
        cylinder(r=radius, h=height, center=true);
        cylinder(r=radius-thickness, h=height, center=true);
        cylinder(r=radius-thickness/2, h=height, center=true);
        cylinder(r=radius+thickness/2, h=height, center=true);
    }
}

