  difference() {
    cylinder(r=base_width/2, h=base_height, center=true);
    translate([0, base_height/2, 0]) {
      cylinder(r=base_width/2, h=thickness, center=true);
    }
  }

  // Mounting tab
  translate([base_width/2, base_height/2, 0]) {
    difference() {
      cylinder(r=tab_width/2, h=tab_height, center=true);
      translate([0, tab_height/2, 0]) {
        cylinder(r=tab_width/2, h=thickness, center=true);
      }
    }
  }
}

