module pipe_flange(radius, thickness, outer_radius, inner_radius) {
    // Main body
    cylinder(radius=radius, height=outer_radius - inner_radius, center=true, resolution=200);

    // Add holes with extended Z-axis
    difference() {
        cylinder(radius=radius, height=thickness, center=true, resolution=200);
        difference() {
            cylinder(radius=radius, height=outer_radius - thickness - 5, center=true, resolution=200);
            cylinder(radius=inner_radius, height=outer_radius - thickness - 5, center=true, resolution=200);
        }
    }
}

