module circular_pipe_flange(radius, thickness, height) {
    // Define the center of the pipe
    translate([radius, radius, 0]) {
        // Create the body of the pipe
        cylinder(r=radius, h=height, center=true, resolution=50);
    }

    // Create the holes in the pipe body
    translate([radius, radius, 0]) {
        difference() {
            cylinder(r=radius - thickness/2, h=height, center=true, resolution=50);
            cylinder(r=radius + thickness/2, h=height, center=true, resolution=50);
        }
    }

    // Set the Z-axis to extend past the main body
    translate([0, 0, thickness + height]) {
        // Create the holes on the Z-axis
        difference() {
            cylinder(r=radius - thickness/2, h=height, center=true, resolution=50);
            cylinder(r=radius + thickness/2, h=height, center=true, resolution=50);
        }
    }
}

