module hex_standoff(
    size = 74,
    thickness = 13,
    hex_radius = 3.2,
    hex_height = 2.2
) {
    // Create a hexagonal standoff with the given dimensions
    union() {
        // Create the base of the standoff
        difference() {
            cube([size, size, thickness]);
            cylinder(d = hex_radius, h = thickness, r1 = hex_radius - 0.1, r2 = hex_radius - 0.2, center = true);
            cylinder(d = hex_radius, h = hex_height, r1 = hex_radius - 0.1, r2 = hex_radius - 0.2, center = true);
        }

        // Create the recess for the hex nut
        difference() {
            cube([hex_radius * 2, hex_radius * 2, thickness]);
            cylinder(d = hex_radius * 1.5, h = thickness, r1 = hex_radius * 1.4, r2 = hex_radius * 1.5, center = true);
        }
    }
}

