// Flanged Bushing Parameterized OpenSCAD Code
// Overall Size: 28mm x 14mm
// Flange Width: 12mm
// Flange Depth: 10mm
// Mounting Holes: 4 circular arranged in a rectangular pattern

module flanged_bushing() {
    // Flange
    flat_cylinder(r = 6, h = 14, $fn = 50);
    flat_cylinder(r = 10, h = 10, $fn = 50);

    // Flange Width
    difference() {
        flat_cylinder(r = 6, h = 14, $fn = 50);
        flat_cylinder(r = 10, h = 10, $fn = 50);
    }

    // Flange Depth
    difference() {
        flat_cylinder(r = 6, h = 14, $fn = 50);
        flat_cylinder(r = 10, h = 10, $fn = 50);
