module flanged_bushing(size, thickness) {
  // Define the main body
  cylinder(d=size - thickness, h=thickness, center=true, chamfer=true, chamfer_radius=0.1);

  // Define the hole
  hole(d=size - thickness - 0.2, r=0.2, center=true);

  // Subtract the hole from the main body to prevent artifacts on the Z-axis
  cylinder(d=size - thickness, h=thickness, center=true, chamfer=true, chamfer_radius=0.1, difference=hole);

  // Add the flange to the main body
  cylinder(d=size, h=thickness, center=true, chamfer=true, chamfer_radius=0.1, union=flanged_bushing);
}

