// Define the size and thickness of the mounting plate
$fn = 36; // For better quality circles
$pg = 26; // Overall size (mm)
$pd = 12; // Thickness (mm)

// Define the number of mounting holes
num_holes = 4;

// Calculate the radius of the holes
hole_radius = $pg / (2 * num_holes);

// Define the gap between the holes
hole_gap = $pd / (2 * num_holes);

// Calculate the total width of the holes
total_width = hole_radius * 2 * num_holes;

// Calculate the total height of the holes
total_height = hole_radius * 2 * num_holes;

// Calculate the total depth of the holes
total_depth = hole_radius * 2 * num_holes;

// Calculate the center of the holes
hole_center_x = $pg / 2;
hole_center_y = $pg / 2;
hole_center_z = $pd / 2;

// Create the rectangular pattern of holes
for (i = [1:num_holes]) {
    for (j = [1:num_holes]) {
        translate([hole_radius * (i - 1) + hole_gap * (i - 1), hole_radius * (j - 1) + hole_gap * (j - 1), hole_center_z]) {
            cylinder(r=hole_radius, h=$pg, center=true, chamfer=2);
        }
    }
}

// Create the mounting plate body
difference() {
    cube([2*$pg, 2*$pg, $pd], center=true);
    translate([-$pg/2, -$pg/2, -$pd/2]) {
        sphere(r=hole_radius, $fn=36);
    }
}

