module hexagonal_standoff(
    side_length = 10,
    body_depth = 37,
    hole_depth = 12,
    body_width = side_length * 2,
    body_height = 0.5 * side_length * sqrt(3),
    hole_diameter = 5,
    hole_width = 0.5 * hole_diameter,
    hole_height = 0.5 * hole_diameter
) {
    // Body
    translate([0, 0, body_depth]) {
        box(size = [body_width, body_height, hole_depth]);
    }

    // Hole
    translate([0, 0, body_depth - hole_depth]) {
        cylinder(r = hole_diameter / 2, h = hole_height, center = true, segments = 32);
    }

    // Subtracting hole geometry from the body
    translate([0, 0, hole_depth]) {
        box(size = [body_width, body_height, hole_depth], center = true);
    }
}

