module hexagonal_standoff(size, thickness) {
    // Define the side length of the hexagon
    side_length = size - 2 * thickness;

    // Define the height of the hexagon
    height = thickness;

    // Define the radius of the hexagon
    radius = side_length / 2;

    // Calculate the angle of the hexagon
    angle = 60 * (M_PI / 180);

    // Define the vertices of the hexagon
    vertices = [
        [0, 0, 0],
        [radius, 0, 0],
        [radius * cos(angle), radius * sin(angle), 0],
        [0, radius, 0],
        [-radius * cos(angle), radius * sin(angle), 0],
        [0, -radius, 0]
    ];

    // Define the faces of the hexagon
    faces = [
        [0, 1, 2, 3, 4, 5],
        [0, 2, 4],
        [1, 3, 5],
        [6, 4, 2]
    ];

    // Create the hexagon using a difference() subtraction
    difference() {
        cylinder(h=height, r=radius, center=true);
        polygon(points=vertices);
    }
}

