// Parameterized U-Channel Bracket
module UChannelBracket(
    width = 38,
    height = 38,
    depth = 14,
    hole_diameter = 4,
    hole_offset = 2
) {
    // Main body
    translate([width/2, height/2, 0]) {
        cylinder(r=depth/2, h=height, $fn=100);
    }

    // Holes on the X-axis
    for (x=-depth/2+hole_offset, x<=depth/2-hole_offset, x=x+2*hole_offset) {
        translate([x, height/2, 0]) {
            cylinder(r=hole_diameter/2, h=height, $fn=100);
        }
    }

    // Holes on the Z-axis
    for (z=-depth/2+hole_offset, z<=depth/2-hole_offset, z=z+2*hole_offset) {
        translate([width/2, z, 0]) {
            cylinder(r=hole_diameter/2, h=height, $fn=100);
        }
    }

    // Holes on the Y-axis
    for (y=-depth/2+hole_offset, y<=depth/2-hole_offset, y=y+2*hole_offset) {
        translate([width/2, height/2, y]) {
            cylinder(r=hole_diameter/2, h=height, $fn=100);
        }
    }
}

