module shaftCollar(radius, thickness) {
    // Main body of the collar
    cylinder(d=radius+2*thickness, h=48-thickness, center=true);

    // Subtract the 3D rendering artifacts by adding the outer surface of the main body
    difference() {
        cylinder(d=radius+2*thickness, h=48-thickness, center=true);
        cylinder(d=radius, h=48-thickness, center=true);
    }

    // Add the outer surface of the main body to ensure the subtracted hole geometries extend past the main body on the Z-axis
    union() {
        cylinder(d=radius+2*thickness, h=48-thickness, center=true);
        cylinder(d=radius, h=48-thickness, center=true);
    }
}

