            translate([0, 0, 0]) {
                difference() {
                    cube([length, width, depth]);
                    // Add any extra outer surface if needed
                    // ...
                }
            }
        }
    }

    // Holes
    translate([0, 0, depth - hole_depth]) {
        difference() {
            cube([length, width, hole_depth]);
            // Add any extra hole if needed
            // ...
        }
    }

    translate([0, width - hole_depth, depth - hole_depth]) {
        difference() {
            cube([length, hole_depth, hole_depth]);
            // Add any extra hole if needed
            // ...
        }
    }
}

