module structural_l_bracket(
  size = 32, 
  thickness = 13, 
  mounting_holes = 4, 
  mounting_hole_diameter = 5, 
  mounting_hole_spacing = 10, 
  mounting_hole_center = [0, 0, 0]
) {
  // Base
  difference() {
    cube([size, size, thickness]);
    translate([size / 2, size / 2, thickness / 2])
      cube([thickness, thickness, size]);
  }

  // Mounting holes
  for (i = range(mounting_holes)) {
    translate([
      mounting_hole_center[0] + (i % 2) * mounting_hole_spacing,
      mounting_hole_center[1] + (i % 2) * mounting_hole_spacing,
      mounting_hole_center[2]
    ])
