module corner_gusset(size, thickness) {
    // Define the main body of the corner gusset
    union() {
        // Draw the front side of the gusset
        translate([0, 0, -thickness/2]) box([size, size, thickness], center=true);

        // Draw the back side of the gusset
        translate([0, 0, thickness/2]) box([size, size, thickness], center=true);
    }

    // Define the top surface of the gusset
    translate([0, 0, 0]) rotate([0, 0, 45]) cylinder(r=thickness/2, h=size, center=true);

    // Define the bottom surface of the gusset
    translate([0, 0, size]) rotate([0, 0, 45]) cylinder(r=thickness/2, h=size, center=true);

    // Define the left side of the gusset
    translate([-thickness/2, 0, 0]) rotate([0, 90, 0]) cylinder(r=thickness/2, h=size, center=true);

    // Define the right side of the gusset
    translate([thickness/2, 0, 0]) rotate([0, -90, 0]) cylinder(r=thickness/2, h=size, center=true);

    // Define the front edge of the gusset
    translate([0, thickness/2, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=size, center=true);

    // Define the back edge of the gusset
    translate([0, -thickness/2, 0]) rotate([90, 0, 0]) cylinder(r=thickness/2, h=size, center=true);

    // Define the top edge of the gusset
    translate([0, 0, thickness/2]) rotate([0, 0, 45]) cylinder(r=thickness/2, h=size, center=true);

    // Define the bottom edge of the gusset
    translate([0, size, thickness/2]) rotate([0, 0, 45]) cylinder(r=thickness/2, h=size, center=true);
}

