    difference() {
        difference() {
            difference() {
                cube(size);
                translate([0, 0, size / 2]) {
                    cylinder(r=size / 4, h=size / 2);
                }
            }
            translate([size / 4, 0, size / 2]) {
                cylinder(r=size / 4, h=size / 2);
            }
            translate([size / 2, size / 4, size / 2]) {
                cylinder(r=size / 4, h=size / 2);
            }
        }
        translate([0, size / 4, size / 2]) {
            cylinder(r=size / 4, h=size / 2);
        }
        translate([size / 4, size / 2, size / 4]) {
            cylinder(r=size / 4, h=size / 2);
        }
        translate([size / 2, size / 4, size / 4]) {
            cylinder(r=size / 4, h=size / 2);
        }
    }
}

