    cylinder(size = [diameter, diameter, thickness], chamfer = chamferRadius);

    // Create the secondary cylindrical part that will be cut away
    cylinder(size = [diameter, diameter, height - thickness], chamfer = chamferRadius);

    // Combine the two parts with union to create the spacer
    difference() {
        cylinder(size = [diameter, diameter, thickness], chamfer = chamferRadius);
        cylinder(size = [diameter, diameter, height - thickness], chamfer = chamferRadius);
