        cylinder(center = [0, 0, thickness/2 + 1], radius = overall_size/2 - 1, height = 1, center_z = thickness/2 + 1);
        cylinder(center = [0, 0, thickness/2 + 1], radius = overall_size/2 - 1, height = 1, center_z = thickness/2);
        cylinder(center = [0, 0, thickness/2 + 1], radius = overall_size/2 - 1, height = 1, center_z = thickness/2);
    }
}

