module corner_gusset(size=73, thickness=13, chamfer=2) {
    // Calculate the dimensions for the corners
    corner_height = size - (thickness * 2);
    corner_width = size / 2 - chamfer;

    // Draw the base of the corner gusset
    difference() {
        cylinder(h=size, d=thickness, center=false, end=true);
        translate([0, 0, thickness / 2]) cylinder(h=thickness, d=corner_width, center=false, end=true);
    }

    // Draw the top of the corner gusset
    translate([0, corner_height, thickness / 2]) cylinder(h=thickness, d=corner_width, center=false, end=true);

    // Draw the chamfer on the primary outer edges
    translate([chamfer / 2, 0, thickness / 2]) cylinder(h=corner_height, d=chamfer, center=false, end=true);
    translate([size - chamfer / 2, 0, thickness / 2]) cylinder(h=corner_height, d=chamfer, center=false, end=true);
    translate([0, chamfer / 2, corner_height / 2]) cylinder(h=thickness, d=chamfer, center=false, end=true);
    translate([0, size - chamfer / 2, corner_height / 2]) cylinder(h=thickness, d=chamfer, center=false, end=true);
}

