module corner_gusset(size=70mm, thickness=9mm, chamfer=2mm) {
  // Primary outer edges
  difference() {
    translate([0, 0, thickness/2])
      cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);
    translate([0, 0, -thickness/2])
      cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);
  }

  // Secondary edges
  translate([0, size/2, thickness/2])
    cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);
  translate([0, -size/2, thickness/2])
    cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);
  translate([size/2, 0, thickness/2])
    cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);
  translate([-size/2, 0, thickness/2])
    cylinder(r1=size/2 - chamfer, r2=size/2, h=size - thickness);

  // Chamfer on primary outer edges
  translate([0, 0, thickness/2 - chamfer])
    cylinder(r1=size/2, r2=size/2, h=size - thickness);
  translate([0, 0, -thickness/2 + chamfer])
    cylinder(r1=size/2, r2=size/2, h=size - thickness);
  translate([size/2, 0, thickness/2 - chamfer])
    cylinder(r1=size/2, r2=size/2, h=size - thickness);
  translate([-size/2, 0, thickness/2 - chamfer])
    cylinder(r1=size/2, r2=size/2, h=size - thickness);
}

