module corner_gusset(size, thickness, hole_diameter, hole_spacing) {
    // Create the base of the corner gusset
    difference() {
        cube([size, size, thickness]);
        // Add mounting holes
        for (x = [0:((size - hole_diameter) / hole_spacing):((size - hole_diameter) / hole_spacing)]) {
            for (y = [0:((size - hole_diameter) / hole_spacing):((size - hole_diameter) / hole_spacing)]) {
                translate([x * hole_spacing, y * hole_spacing, thickness / 2 - hole_diameter / 2]) cylinder(diameter = hole_diameter, height = hole_diameter);
            }
        }
    }
}

