module pipe_flange(size=71, thickness=4) {
    // Define the center of the pipe flange
    translate([size/2, size/2, 0]) {
        // Create the circular pipe flange
        difference() {
            // Create the pipe body
            union() {
                // Create the top face
                cylinder(r=size-2*thickness, h=thickness, center=true, end=true);
                // Create the bottom face
                cylinder(r=size-2*thickness, h=thickness, center=true, end=true);
                // Create the sides
                intersection() {
                    // Create the left side
                    cylinder(r=thickness, h=size-2*thickness, center=true, end=true);
                    // Create the right side
                    cylinder(r=thickness, h=size-2*thickness, center=true, end=true);
                }
            }
            // Create the mounting holes
            difference() {
                // Create the mounting hole centers
                translate([size/2, size/2, 0]) {
                    // Create the left mounting hole
                    cylinder(r=thickness/2, h=size-2*thickness, center=true, end=true);
                    // Create the right mounting hole
                    cylinder(r=thickness/2, h=size-2*thickness, center=true, end=true);
                }
                // Create the central mounting hole
                cylinder(r=thickness/2, h=size-2*thickness, center=true, end=true);
            }
        }
    }
}

