module UChannelBracket(
    diameter = 12.5,
    height = 31,
    depth = 7,
    holeSize = 3.5,
    holeDepth = 4
) {
    // Base
    difference() {
        union() {
            // Base body
            cube([height, depth, diameter]);

            // Hole in the base
            translate([0, 0, holeSize + holeDepth])
                cube([height - holeSize, depth - holeSize, holeSize]);
        }
    }

    // Front section
    translate([0, 0, height - holeSize - holeDepth])
        difference() {
            union() {
                // Front body
                cube([depth, holeSize + holeDepth, diameter]);

                // Front hole
                translate([0, holeSize + holeDepth, holeSize + holeDepth])
                    cube([depth - holeSize, holeSize - holeSize, holeSize]);
            }
        }
}

