);

module bushing(size=85, thickness=12, hexRadius=5.33, hexHeight=7.62) {
    // Outer ring of the bushing
    cylinder(r=size/2, h=thickness, center=false, chamfer=true, chamferRadius=0.5);

    // Hexagonal recess
    difference() {
        // Hexagon
        intersection() {
            // Hexagon sides
            union() {
                rotate([0, 0, 90]) circle(d=hexRadius);
                rotate([0, 90, 0]) circle(d=hexRadius);
                rotate([0, 180, 0]) circle(d=hexRadius);
                rotate([0, 270, 0]) circle(d=hexRadius);
            }

            // Hexagon corners
            union() {
                translate([0, -hexHeight/2, 0]) circle(d=hexRadius);
                translate([0, hexHeight/2, 0]) circle(d=hexRadius);
                translate([-hexRadius, 0, -hexHeight/2]) circle(d=hexRadius);
                translate([hexRadius, 0, -hexHeight/2]) circle(d=hexRadius);
            }
        }

        // Flange
        translate([size/2, 0, thickness/2]) cylinder(r=hexRadius-0.5, h=hexHeight, center=true, chamfer=true, chamferRadius=0.5);
    }
}

