module corner_gusset(size, thickness) {
    // Define the main body
    linear_extrude(thickness + 2) {
        square([size, size]);
    }

    // Define the holes
    // Top hole
    translate([0, 0, thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }

    // Bottom hole
    translate([0, 0, -thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }

    // Left hole
    translate([-thickness / 2, 0, thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }

    // Right hole
    translate([thickness / 2, 0, thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }

    // Top hole on the back
    translate([0, 0, -thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }

    // Bottom hole on the back
    translate([0, 0, thickness / 2]) {
        cylinder(r=2, h=thickness - 2);
    }
}

