module circular_pipe_flange(param = [65, 5]) {
  // Define the main body of the pipe flange
  translate([0, 0, -param[1]]) {
    cylinder(r = param[0] - param[1], h = param[0] - param[1], center = true, segments = 32);
  }

  // Define the subtracted hole geometries
  translate([param[0] - param[1], 0, 0]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }

  translate([0, param[0] - param[1], 0]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }

  translate([param[0] - param[1], param[0] - param[1], 0]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }

  translate([0, 0, param[0] - param[1]]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }

  translate([param[0] - param[1], 0, param[0] - param[1]]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }

  translate([0, param[0] - param[1], param[0] - param[1]]) {
    cylinder(r = param[1] - 1, h = param[1] - 1, center = true, segments = 32);
  }
}

