module corner_gusset(length, width, thickness) {
    // Define the corner gusset
    // Length and width are the overall dimensions of the gusset
    // Thickness is the thickness of the gusset

    // Define the mounting holes
    // Mounting holes are arranged in a rectangular pattern
    // Each hole is circular with a diameter of 2mm

    // Create the corner gusset
    difference() {
        // Create the base of the gusset
        translate([0, 0, thickness/2]) {
            cylinder(r=10, h=length-2*thickness);
        }

        // Create the top of the gusset
        translate([0, width-2*thickness, thickness/2]) {
            cylinder(r=10, h=length-2*thickness);
        }

        // Create the front of the gusset
        translate([length-2*thickness, 0, thickness/2]) {
            cylinder(r=10, h=length-2*thickness);
        }

        // Create the back of the gusset
        translate([0, 0, 3*thickness/2]) {
            cylinder(r=10, h=length-2*thickness);
        }

        // Create the side of the gusset
        translate([thickness/2, thickness/2, 0]) {
            cylinder(r=10, h=length-2*thickness);
        }

        // Create the mounting holes
        for (x = [0:width-2*thickness:width]) {
            for (y = [0:length-2*thickness:length]) {
                translate([x, y, thickness/2]) {
                    cylinder(r=2, h=thickness);
                }
            }
        }
    }
}

