corner_gusset(80, 80, 12);

module shaft_collar(
  outer_diameter = 81,
  thickness = 10,
  mounting_hole_diameter = 5,
  mounting_hole_spacing = 15,
  mounting_hole_center_distance = 30
) {
  difference() {
    cylinder(
      diameter = outer_diameter,
      height = thickness,
      resolution = 100
    );
    translate([0, 0, thickness]) {
      circle(
        diameter = mounting_hole_diameter,
        center = [outer_diameter / 2, 0, 0]
      );
      translate([outer_diameter / 2, mounting_hole_spacing, 0]) {
        circle(
          diameter = mounting_hole_diameter,
          center = [outer_diameter / 2, mounting_hole_spacing * 2, 0]
        );
      }
      translate([outer_diameter / 2, mounting_hole_spacing * 3, 0]) {
        circle(
          diameter = mounting_hole_diameter,
          center = [outer_diameter / 2, mounting_hole_spacing * 4, 0]
        );
      }
      translate([outer_diameter / 2, mounting_hole_center_distance, 0]) {
        circle(
          diameter = mounting_hole_diameter,
          center = [outer_diameter / 2, mounting_hole_center_distance, 0]
        );
      }
    }
  }
}

