module flanged_bushing(size, thickness) {
    // Flange part
    translate([0, size/2, 0]) {
        box(size-x, thickness, x/4);
    }
    translate([0, -size/2, 0]) {
        box(size-x, thickness, x/4);
    }

    // Circular mounting holes
    for (i=[0:3]) {
        translate([x/4, i*thickness/2, 0]) {
            cylinder(r=size/2 - thickness/2, h=thickness, center=true);
        }
    }
}

