// Define the pipe flange parameters
module pipe_flange(size = 63mm, thickness = 4mm) {
    // Create the pipe flange body
    difference() {
        cylinder(r1=size/2-thickness, h=size/2, center=true);
        cylinder(r1=size/2+thickness, h=size/2, center=true);
        difference() {
            cylinder(r1=size/2, h=size/2-thickness, center=true);
            cylinder(r1=size/2, h=size/2+thickness, center=true);
        }
    }

    // Add the mounting holes
    translate([10mm, 0, 0]) rotate([0, 0, 90]) translate([0, 0, -thickness]) cylinder(r=2mm, h=size/2, center=true);
    translate([10mm, 0, 0]) rotate([0, 90, 0]) translate([0, 0, -thickness]) cylinder(r=2mm, h=size/2, center=true);
    translate([10mm, 0, 0]) rotate([0, 0, 180]) translate([0, 0, -thickness]) cylinder(r=2mm, h=size/2, center=true);
    translate([10mm, 0, 0]) rotate([0, 180, 0]) translate([0, 0, -thickness]) cylinder(r=2mm, h=size/2, center=true);
}

