        translate([0, 0, thickness / 2]) {
            difference() {
                cylinder(r1=size / 2 - thickness / 2, r2=size / 2, h=thickness - hole_diameter);
                cylinder(r1=size / 2 - hole_diameter / 2, r2=size / 2 - hole_diameter / 2, h=hole_diameter);
            }
        }
    }
}

