module flanged_bushing(radius, flange_width, hole_radius) {
    // Create the outer cylinder
    cylinder(diameter=flange_width+radius, height=flange_width, center=true, chamfer=true, end=1);

    // Subtract the hole
    difference() {
        cylinder(diameter=flange_width+radius, height=flange_width, center=true, chamfer=true, end=1);
        cylinder(diameter=hole_radius, height=flange_width, center=true, chamfer=true, end=0);
    }
}

