        cylinder(h=thickness-2*chamfer_radius, r1=size/2-2*chamfer_radius, r2=size/2+chamfer_radius, $fn=20);
        cylinder(h=thickness-2*chamfer_radius, r1=size/2-2*chamfer_radius, r2=size/2+chamfer_radius, $fn=20);
