module cylindricalSpacer(size = [35, 15, 4]) {
    // Define the cylinder body
    cylinder(r = size[0]/2, h = size[1], center = [0, 0, 0], chamfer = 0.2);

    // Define the mounting holes
    linearExtrude(height = size[2], center = [0, 0, size[1]/2]) {
        translate([0, 0, size[2]/2]) {
            circle(d = size[0]/2 - 2, $fn = 12);
        }
    }

    // Define the mounting holes arrangement
    linearExtrude(height = size[2], center = [0, 0, size[1]/2]) {
        translate([0, 0, size[2]/2]) {
            circle(d = size[0]/2 - 2, $fn = 12);
            translate([0, size[0]/2 - 4, 0]) {
                circle(d = size[0]/2 - 2, $fn = 12);
            }
            translate([0, -size[0]/2 + 4, 0]) {
                circle(d = size[0]/2 - 2, $fn = 12);
            }
            translate([-size[0]/2 + 4, 0, 0]) {
                circle(d = size[0]/2 - 2, $fn = 12);
            }
        }
    }
}

