module shaft_collar(size, thickness) {
    // Base plate with a thickness of 'thickness'
    union() {
        sphere(r=size/2, center=[0, 0, size/2]);
        cylinder(r=thickness/2, h=size-2*thickness, center=[0, 0, size/2], chamfer=[0, 0, thickness/2]);
    }

    // Extended mounting tab
    cylinder(r=thickness/2, h=2*thickness, center=[0, 0, size/2], chamfer=[0, 0, thickness/2]);
}

