module structural_lbracket(
    size = 30,  // Overall size in mm
    thickness = 5,  // Thickness in mm
    hole_diameter = 1.5,  // Diameter of mounting holes in mm
    hole_spacing = 5  // Spacing between mounting holes in mm
) {

    // Create the main body of the L-bracket
    cylinder(
        r1 = size / 2 - thickness / 2,
        r2 = size / 2 + thickness / 2,
        h = size,
        center = true,
        chamfer = 1.0,
        chamfer_r = size / 4,
        chamfer_offset = -thickness / 2
    );

    // Create the mounting holes
    for (i = [0:size/hole_spacing-1]) {
        for (j = [0:size/hole_spacing-1]) {
            translate([i*hole_spacing, j*hole_spacing, -thickness/2]) {
                cylinder(
                    r = hole_diameter / 2,
                    h = thickness,
                    center = true,
                    chamfer = 1.0,
                    chamfer_r = hole_diameter / 4,
                    chamfer_offset = -thickness / 2
                );
            }
        }
    }
}

