module flanged_bushing(size=43, thickness=6, chamfer=2) {
    // Define the radius and height of the cylinder
    radius = size / 2;
    height = thickness + chamfer;

    // Create the cylinder with a chamfered outer edge
    cylinder(r=radius - chamfer, h=height - chamfer, chamfer=chamfer, $fn=50);  // $fn=50 for smoother corners

    // Create the flange
    flange_height = chamfer / 2;
    flange_radius = radius - flange_height;

    // Create the flange using a cylindrical cap and a cylindrical hole
    cylinder(r=flange_radius, h=flange_height, chamfer=flange_height, $fn=50);

    // Create the hole in the center of the cylinder
    cylinder(r=radius, h=thickness - chamfer, chamfer=chamfer, $fn=50);
}

