module u_channel_bracket(
    diameter = 6mm,
    height = 32mm,
    hole_diameter = 4mm,
    hole_spacing = 10mm,
    hole_rows = 2,
    hole_columns = 2
) {
    difference() {
        // Define the U-channel body
        translate([0, 0, 11]) {
            difference() {
                // Create the U-channel
                translate([0, height/2, -11])
                    rotate([90, 0, 0])
                    cube([diameter, height, 2*thickness]);

                translate([diameter/2, height/2, -11])
                    rotate([0, 90, 0])
                    cube([diameter, height, 2*thickness]);

                translate([diameter, 0, -11])
                    rotate([90, 0, 0])
                    cube([diameter, height, 2*thickness]);

                translate([diameter/2, 0, -11])
                    rotate([0, 90, 0])
                    cube([diameter, height, 2*thickness]);
            }

            // Add mounting holes
            for (i = [0:(hole_rows-1)]) {
                for (j = [0:(hole_columns-1)]) {
                    translate([hole_spacing*(j+0.5), hole_spacing*(i+0.5), -11])
                        rotate([0, 0, 0])
                        cylinder(hole_diameter/2, height, hole_diameter);
                }
            }
        }
    }
}

