module u_channel_bracket(size, thickness) {
    // Main body
    difference() {
        translate([0, 0, thickness/2]) {
            cube([size[0], size[1], thickness], center=true);
        }
        translate([size[0], 0, -thickness/2]) {
            cube([size[0], size[1], thickness], center=true);
        }
        translate([0, size[1], thickness/2]) {
            cube([size[0], size[1], thickness], center=true);
        }
        translate([0, -size[1], thickness/2]) {
            cube([size[0], size[1], thickness], center=true);
        }
    }

    // Holes
    translate([size[0]/4, 0, thickness/2]) {
        hole(size[0]/4, 0, thickness/2);
    }

    translate([size[0]/4, -size[1]/4, thickness/2]) {
        hole(size[0]/4, -size[1]/4, thickness/2);
    }

    translate([size[0]/4, size[1]/4, thickness/2]) {
        hole(size[0]/4, size[1]/4, thickness/2);
    }

    translate([size[0]/4, -size[1]/4, -thickness/2]) {
        hole(size[0]/4, -size[1]/4, -thickness/2);
    }

    translate([-size[0]/4, 0, thickness/2]) {
        hole(-size[0]/4, 0, thickness/2);
    }

    translate([-size[0]/4, -size[1]/4, thickness/2]) {
        hole(-size[0]/4, -size[1]/4, thickness/2);
    }

    translate([-size[0]/4, size[1]/4, thickness/2]) {
        hole(-size[0]/4, size[1]/4, thickness/2);
    }

    translate([-size[0]/4, -size[1]/4, -thickness/2]) {
        hole(-size[0]/4, -size[1]/4, -thickness/2);
    }
}

