module u_channel_bracket(size, thickness, chamfer) {
    // Define the main body of the bracket
    union() {
        // Top face
        cube([size[0], size[1], thickness], center=true);

        // Bottom face
        cube([size[0], size[1], thickness], center=true, rotate=[0,90,0]);

        // Left face
        cube([thickness, size[1], size[0]], center=true, rotate=[90,0,0]);

        // Right face
        cube([thickness, size[1], size[0]], center=true, rotate=[-90,0,0]);

        // Front face
        cube([size[0], thickness, size[1]], center=true, rotate=[0,0,90]);

        // Back face
        cube([size[0], thickness, size[1]], center=true, rotate=[0,0,-90]);
    }

    // Chamfer on the primary outer edges
    chamfered_faces([
        [0, 0, 0], [0, size[1], 0], [size[0], size[1], 0], [size[0], 0, 0],
        [0, 0, thickness], [0, size[1], thickness], [size[0], size[1], thickness], [size[0], 0, thickness],
        [0, 0, size[1]], [0, size[1], size[1]], [size[0], size[1], size[1]], [size[0], 0, size[1]]
    ], chamfer, chamfer);
}

