module circular_pipe_flange(radius, thickness) {
  // Main body
  cylinder(d = 2*radius, h = thickness, center = true);

  // Holes
  translate([0, 0, thickness/2]) {
    sphere(r = radius - thickness/2, center = true);
  }

  // Ensure holes extend past the main body on the Z-axis
  translate([0, 0, thickness/2 + 0.01]) {
    sphere(r = radius - thickness/2, center = true);
  }
}

