module Flange(size, thickness) {
    // Define the outer circle of the flange
    cylinder(r=size/2, h=size, center=true, chamfer=thickness/2, chamfer_top=true);

    // Define the inner circle of the flange
    cylinder(r=size/2-thickness/2, h=size, center=true, chamfer=thickness/2, chamfer_top=true);

    // Define the central through-hole
    difference() {
        difference() {
            cylinder(r=size/2-thickness/2, h=size, center=true, chamfer=thickness/2, chamfer_top=true);
            cylinder(r=thickness/2, h=size/2, center=true, chamfer=thickness/2, chamfer_top=true);
        }
        cylinder(r=size/2-thickness/2, h=size/2, center=true, chamfer=thickness/2, chamfer_top=true);
    }
}

