module flat_mounting_plate(size = 27, thickness = 9, chamfer = 2) {
    // Outer edge chamfer
    cylinder(r = chamfer, h = size - 2*chamfer, center = true);
    // Inner edge chamfer
    cylinder(r = chamfer, h = size - 2*chamfer, center = true, start = [0, 0, -thickness]);
    // Inner flat surface
    polygon(points = [
        [0, 0],
        [size, 0],
        [size, thickness],
        [0, thickness]
    ]);
    // Outer flat surface
    polygon(points = [
        [0, 0],
        [size, 0],
        [size, size - thickness],
        [0, size - thickness]
    ]);
}

