    cylinder(d = size/2 + thickness/2, h = size - thickness, center = true);

    // Top part
    cylinder(d = size/2 + thickness/2, h = size - thickness, center = true, chamfer = chamferSize);

    // Side part
    difference() {
        // Front side
        cylinder(d = size - thickness, h = 2 * chamferSize + thickness/2, center = true, chamfer = chamferSize);

        // Back side
        cylinder(d = size - thickness, h = 2 * chamferSize + thickness/2, center = true, chamfer = chamferSize);

        // Corner
        cylinder(d = size/2, h = 2 * chamferSize + thickness/2, center = true, chamfer = chamferSize);
    }
}

