module bushing(size, thickness) {
    // Define the overall size and thickness
    size = size || 62mm;
    thickness = thickness || 3mm;

    // Calculate the outer and inner radii
    radius_outer = size / 2;
    radius_inner = radius_outer - thickness / 2;

    // Create the flange
    cylinder(radius_outer, thickness, center=[0, 0, thickness / 2]);

    // Create the mounting holes
    for (i = [0:3]) {
        for (j = [0:3]) {
            difference() {
                translate([radius_outer * cos(2 * PI * i / 4), radius_outer * sin(2 * PI * i / 4), thickness / 2])
                cylinder(radius_inner, thickness, center=[0, 0, thickness / 2]);
            }
        }
    }
}

