module project_enclosure_base(
    width = 82,
    height = 82,
    thickness = 9,
    chamfer_size = 2
) {
    // Define the base as a rectangular prism
    difference() {
        cube([width, height, thickness], center = [true, true, true]);
        // Chamfer the primary outer edges
        translate([chamfer_size, chamfer_size, 0]) {
            cube([width - 2 * chamfer_size, height - 2 * chamfer_size, thickness], center = [true, true, true]);
        }
        translate([chamfer_size, 0, chamfer_size]) {
            cube([width - 2 * chamfer_size, height, thickness - 2 * chamfer_size], center = [true, true, true]);
        }
        translate([0, chamfer_size, chamfer_size]) {
            cube([width, height - 2 * chamfer_size, thickness - 2 * chamfer_size], center = [true, true, true]);
        }
        translate([0, 0, chamfer_size]) {
            cube([width - 2 * chamfer_size, height - 2 * chamfer_size, thickness - 2 * chamfer_size], center = [true, true, true]);
        }
    }
}

