    difference() {
        cube([width + 2*chamfer_thickness, height + 2*chamfer_thickness, chamfer_thickness]);
        difference() {
            cube([width, height, 4 - chamfer_thickness]);
            translate([chamfer_thickness, chamfer_thickness, 0]) {
                cube([width - 2*chamfer_thickness, height - 2*chamfer_thickness, chamfer_thickness]);
            }
        }
    }

    // Create the primary outer edges
    difference() {
        cube([width, height, chamfer_thickness]);
        difference() {
            cube([width, height, 4 - chamfer_thickness]);
            translate([chamfer_thickness, chamfer_thickness, 0]) {
                cube([width - 2*chamfer_thickness, height - 2*chamfer_thickness, chamfer_thickness]);
            }
        }
    }
}

