module rectangular_project_enclosure_base(thickness, primary_chamfer, edge_chamfer, height, width) {
  // Create the primary outer edges with a chamfer
  linear_extrude(height) {
    circle(d=primary_chamfer/2);
    translate([0, primary_chamfer/2, 0]) rotate([0, 90, 0]) circle(d=primary_chamfer/2);
    translate([width, primary_chamfer/2, 0]) rotate([0, 180, 0]) circle(d=primary_chamfer/2);
    translate([width, height-primary_chamfer/2, 0]) rotate([0, 270, 0]) circle(d=primary_chamfer/2);
  }

  // Create the edge chamfer
  linear_extrude(edge_chamfer) {
    circle(d=edge_chamfer/2);
    translate([0, edge_chamfer/2, 0]) rotate([0, 90, 0]) circle(d=edge_chamfer/2);
    translate([width, edge_chamfer/2, 0]) rotate([0, 180, 0]) circle(d=edge_chamfer/2);
    translate([width, height-edge_chamfer/2, 0]) rotate([0, 270, 0]) circle(d=edge_chamfer/2);
  }

  // Create the base with the primary outer edges and edge chamfer
  translate([0, 0, 0]) {
    linear_extrude(thickness) {
      circle(d=primary_chamfer/2);
      translate([0, primary_chamfer/2, 0]) rotate([0, 90, 0]) circle(d=primary_chamfer/2);
      translate([width, primary_chamfer/2, 0]) rotate([0, 180, 0]) circle(d=primary_chamfer/2);
      translate([width, height-primary_chamfer/2, 0]) rotate([0, 270, 0]) circle(d=primary_chamfer/2);
    }
    difference() {
      circular_prism(radius=primary_chamfer/2, height=thickness);
      circular_prism(radius=primary_chamfer/2, height=edge_chamfer);
      circular_prism(radius=edge_chamfer/2, height=edge_chamfer);
      circular_prism(radius=edge_chamfer/2, height=edge_chamfer);
    }
  }
}

