module pipe_flange(radius, thickness) {
    // Create the flange body
    difference() {
        cylinder(d=radius + thickness, h=2 * radius, center=[0, 0, -thickness / 2]);
        translate([0, 0, -thickness / 2]) {
            hex(radius, length=radius * 2);
        }
    }

    // Subtract the hexagonal recess
    hex_nut_recess(radius, thickness);
}

