module pipe_flange(thickness, diameter) {
    // Base plate
    translate([0, -thickness/2, 0]) {
        cylinder(r=diameter/2, h=thickness);
    }

    // Extended mounting tab
    translate([0, thickness/2, thickness/2]) {
        cylinder(r=diameter/4, h=diameter/2);
    }

    // Union the base plate and the extended mounting tab
    union() {
        translate([0, -thickness/2, 0]) {
            cylinder(r=diameter/2, h=thickness);
        }
        translate([0, thickness/2, thickness/2]) {
            cylinder(r=diameter/4, h=diameter/2);
        }
    }
}

