module flat_mounting_plate(size = 68, thickness = 3) {
    // Define the body of the plate
    translate([0, 0, 0]) cube([size, size, thickness]);

    // Define the center through-hole
    difference() {
        // Subtract the hole from the main body of the plate
        translate([size / 2 - thickness / 2, size / 2 - thickness / 2, thickness / 2])
            cube([thickness, thickness, thickness]);
        translate([size / 2 + thickness / 2, size / 2 + thickness / 2, thickness / 2])
            cube([thickness, thickness, thickness]);
    }
}

