module u_channel_bracket(
    width = 79,
    height = 11,
    depth = 11,
    hole_diameter = 2,
    hole_depth = 5
) {
    // Main body
    difference() {
        cube([width, height, depth]);
        // Front face hole
        translate([width/2, hole_depth/2, 0]) difference() {
            cylinder(hole_diameter/2, hole_depth);
            translate([-hole_diameter/2, 0, 0]) cylinder(hole_diameter/2, hole_depth);
        }
        // Back face hole
        translate([width/2, -hole_depth/2, 0]) difference() {
            cylinder(hole_diameter/2, hole_depth);
            translate([hole_diameter/2, 0, 0]) cylinder(hole_diameter/2, hole_depth);
        }
        // Top face hole
        translate([width/2, 0, hole_depth/2]) difference() {
            cylinder(hole_diameter/2, hole_depth);
            translate([0, hole_diameter/2, 0]) cylinder(hole_diameter/2, hole_depth);
        }
        // Bottom face hole
        translate([width/2, 0, -hole_depth/2]) difference() {
            cylinder(hole_diameter/2, hole_depth);
            translate([0, -hole_diameter/2, 0]) cylinder(hole_diameter/2, hole_depth);
        }
    }
}

