        height = height - thickness,
        center = true
    );

    // Inner cylinder for the flange
    cylinder(
        radius = inner_radius,
        height = thickness,
        center = true,
        chamfer = 1
    );

    // Difference between outer and inner cylinders to create the flange
    difference() {
        cylinder(
            radius = outer_radius,
            height = height - thickness,
            center = true
        );
        cylinder(
            radius = inner_radius,
            height = thickness,
            center = true,
            chamfer = 1
        );
    }

    // Additional holes can be added here using union, intersection, etc.
}

