  cylinder(diameter - 2*chamfer, $thickness);
  translate([0, 0, chamfer]) cylinder(diameter - 2*chamfer, $thickness);
  translate([0, diameter, chamfer]) cylinder(diameter - 2*chamfer, $thickness);
