module rectangular_project_enclosure_base(
  outer_length = 93,
  outer_width = 93,
  outer_thickness = 15
) {
  // Calculate the inner dimensions
  inner_length = outer_length - 2 * outer_thickness;
  inner_width = outer_width - 2 * outer_thickness;

  // Define the main body
  difference() {
    cube([outer_length, outer_width, outer_thickness], center = true);

    // Define the holes
    translate([outer_thickness, outer_thickness, outer_thickness]) cube([inner_length, inner_width, outer_thickness], center = true);
    translate([outer_length - inner_length, outer_thickness, outer_thickness]) cube([inner_length, inner_width, outer_thickness], center = true);
    translate([outer_thickness, outer_width - inner_width, outer_thickness]) cube([inner_length, inner_width, outer_thickness], center = true);
    translate([outer_length - inner_length, outer_width - inner_width, outer_thickness]) cube([inner_length, inner_width, outer_thickness], center = true);
  }
}

