    // Bottom hole
    translate([0, size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Top hole
    translate([0, -size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Bottom support
    translate([size / 2, size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Top support
    translate([-size / 2, size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Bottom guide
    translate([size / 2, -size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Top guide
    translate([-size / 2, -size / 2, thickness / 2]) cylinder(diameter = size / 4, height = thickness);

    // Bottom guide support
    translate([size / 2, size / 2, thickness / 2 + thickness / 4]) cylinder(diameter = size / 4, height = thickness / 2);

    // Top guide support
    translate([-size / 2, size / 2, thickness / 2 + thickness / 4]) cylinder(diameter = size / 4, height = thickness / 2);

    // Bottom guide support
    translate([size / 2, -size / 2, thickness / 2 + thickness / 4]) cylinder(diameter = size / 4, height = thickness / 2);

