module flange_bushing(
    outer_diameter = 96,
    thickness = 14,
    hole_diameter = 3,
    hole_spacing = 10
){
    // Create the flange
    difference(){
        cylinder(d=outer_diameter, h=thickness);
        cylinder(d=outer_diameter-2*hole_diameter, h=thickness, center=true);
    }

    // Create the mounting holes
    union(){
        for(i=[0:3]){
            for(j=[0:3]){
                translate([i*hole_spacing, j*hole_spacing, 0]){
                    cylinder(d=hole_diameter, h=thickness, center=true);
                }
            }
        }
    }
}

