module corner_gusset(size, thickness, chamfer_thickness) {
    // Define the main body of the corner gusset
    difference() {
        cube([size, size, thickness]);
        translate([0, 0, thickness / 2]) {
            cylinder(r1=thickness / 2, r2=thickness / 2, h=size - thickness);
        }
        translate([0, size - thickness, thickness / 2]) {
            cylinder(r1=thickness / 2, r2=thickness / 2, h=size - thickness);
        }
        translate([size - thickness, 0, thickness / 2]) {
            cylinder(r1=thickness / 2, r2=thickness / 2, h=size - thickness);
        }
        translate([size - thickness, size - thickness, thickness / 2]) {
            cylinder(r1=thickness / 2, r2=thickness / 2, h=size - thickness);
        }
    }

    // Chamfer the primary outer edges
    translate([0, 0, thickness / 2]) {
        cylinder(r1=chamfer_thickness, r2=chamfer_thickness, h=size - thickness);
    }
    translate([size - thickness, 0, thickness / 2]) {
        cylinder(r1=chamfer_thickness, r2=chamfer_thickness, h=size - thickness);
    }
    translate([0, size - thickness, thickness / 2]) {
        cylinder(r1=chamfer_thickness, r2=chamfer_thickness, h=size - thickness);
    }
    translate([size - thickness, size - thickness, thickness / 2]) {
        cylinder(r1=chamfer_thickness, r2=chamfer_thickness, h=size - thickness);
    }
}

