module LBracket(x, y, z, h, t) {
    // Define the main body of the L-bracket
    difference() {
        cylinder(r=x+t/2, h=h+t, center=true, fn=100);
        cylinder(r=x+t/2, h=t, center=true, fn=100);
        cylinder(r=y+t/2, h=t, center=true, fn=100);
        cylinder(r=x+t/2, h=t, center=true, fn=100);
        cylinder(r=y+t/2, h=t, center=true, fn=100);
    }

    // Define the holes in the L-bracket
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 1: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 2: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 3: centered at [x+t/2, y+t/2, t]
    }

    // Define the holes in the L-bracket
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 4: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 5: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 6: centered at [x+t/2, y+t/2, t]
    }

    // Define the holes in the L-bracket
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 7: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 8: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 9: centered at [x+t/2, y+t/2, t]
    }

    // Define the holes in the L-bracket
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 10: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
        cube([t, t, 10]); // Hole 11: centered at [x+t/2, y+t/2, t]
    }
    translate([x+t/2, y+t/2, t]) {
