    // Inner surface
    cylinder(r=48, h=size-thickness-2*chamfer_size, center=true, chamfer=true, chamfer_radius=chamfer_size);

    // Inner edge chamfer
    difference() {
        // Outer surface
        cylinder(r=50, h=size-thickness-2*chamfer_size, center=true, chamfer=true, chamfer_radius=chamfer_size);

        // Inner surface
        cylinder(r=48, h=size-thickness-2*chamfer_size, center=true, chamfer=true, chamfer_radius=chamfer_size);
