    translate([-size/2,0,size/2+thickness/4]) cylinder(r=thickness/4, h=thickness/2, center=true, chamferRadius=thickness/4);
    translate([0,size/2,size/2+thickness/4]) cylinder(r=thickness/4, h=thickness/2, center=true, chamferRadius=thickness/4);
    translate([0,-size/2,size/2+thickness/4]) cylinder(r=thickness/4, h=thickness/2, center=true, chamferRadius=thickness/4);
    translate([size/2,-size/2,size/2+thickness/4]) cylinder(r=thickness/4, h=thickness/2, center=true, chamferRadius=thickness/4);
}

