    // Create the outer shape of the bracket
    cylinder(h=thickness, r1=size/2-2*chamfer, r2=size/2+2*chamfer, center=true, convex=true);

    // Difference the inner and outer cylinders to create the overall bracket
    difference() {
        cylinder(h=thickness-2*chamfer, r1=chamfer, r2=chamfer, center=true, convex=true);
        cylinder(h=thickness, r1=size/2-2*chamfer, r2=size/2+2*chamfer, center=true, convex=true);
