module flanged_bushing(
    thickness = 9mm,
    base_plate_thickness = 10mm,
    mounting_tab_thickness = 3mm,
    mounting_tab_length = 12mm,
    mounting_tab_width = 2mm
) {
    // Base plate with thick base thickness
    difference() {
        union() {
            cylinder(r=30, h=base_plate_thickness);
            translate([0, base_plate_thickness/2, 0]) cylinder(r=30, h=thickness);
        }
    }

    // Mounting tab with specified dimensions
    translate([0, base_plate_thickness/2 + thickness/2, -mounting_tab_thickness/2]) {
        difference() {
            cylinder(r=mounting_tab_width/2, h=mounting_tab_length);
            translate([0, 0, mounting_tab_thickness/2]) cylinder(r=mounting_tab_width/2, h=thickness/2);
        }
    }
}

