    thickness = 5,
    hole_diameter = 5,
    hole_depth = 3,
    shoulder_diameter = 3,
    shoulder_depth = 1
) {
    // Main body of the bushing
    cylinder(r = diameter/2, h = diameter + 2*thickness, center = true, chamfer = 1);

    // Flange
    translate([0, diameter/2 + thickness, 0]) {
        cylinder(r = diameter/2, h = thickness, center = true, chamfer = 1);
    }

    // Holes
    translate([0, diameter/2 + thickness + hole_depth, shoulder_depth]) {
        cylinder(r = hole_diameter/2, h = hole_depth, center = true, chamfer = 1);
    }

    // Shoulder
    translate([0, diameter/2 + thickness + hole_depth + shoulder_depth, 0]) {
        cylinder(r = shoulder_diameter/2, h = shoulder_depth, center = true, chamfer = 1);
    }
}

