module spacer(
    radius = 5,
    thickness = 9,
    num_holes = 4
) {
    // Create a cylinder with the specified radius and thickness
    cylinder(r=radius, h=thickness, center=false, chamfer=true);

    // Create the mounting holes
    for (i=range(num_holes)) {
        // Calculate the position of each hole
        hole_x = radius + thickness * cos(i * 2 * PI / num_holes);
        hole_y = radius + thickness * sin(i * 2 * PI / num_holes);

        // Create the hole at the calculated position
        cylinder(r=0.5, h=thickness, center=true, chamfer=true, translate=[hole_x, hole_y, -thickness/2]);
    }
}

