module shaft_collar(radius, height, thickness) {
    // Top half of the collar
    difference() {
        cylinder(r=radius, h=height, center=true, resolution=36);
        translate([0, height/2, 0]) {
            translate([0, -radius, 0]) {
                cube([2*radius, 2*radius, thickness]);
            }
            translate([radius, -radius, 0]) {
                cube([2*radius, 2*radius, thickness]);
            }
        }
    }

    // Bottom half of the collar
    difference() {
        cylinder(r=radius, h=height, center=true, resolution=36);
        translate([0, -height/2, 0]) {
            translate([0, -radius, 0]) {
                cube([2*radius, 2*radius, thickness]);
            }
            translate([radius, -radius, 0]) {
                cube([2*radius, 2*radius, thickness]);
            }
        }
    }

    // Mounting holes
    translate([0, -height/2, thickness/2]) {
        translate([radius, 0, 0]) {
            cylinder(r=0.5, h=2*radius, center=true, resolution=36);
        }
        translate([-radius, 0, 0]) {
            cylinder(r=0.5, h=2*radius, center=true, resolution=36);
        }
        translate([0, radius, 0]) {
            cylinder(r=0.5, h=2*radius, center=true, resolution=36);
        }
        translate([0, -radius, 0]) {
            cylinder(r=0.5, h=2*radius, center=true, resolution=36);
        }
    }
}

