module corner_gusset(size=33, thickness=3) {
    // Main body
    cube([size-2*thickness, size-2*thickness, thickness]);

    // Holes
    // Top hole
    translate([thickness, thickness, 0]) cube([size-2*thickness, thickness, thickness/2]);
    // Bottom hole
    translate([thickness, size-2*thickness, 0]) cube([size-2*thickness, thickness/2, thickness/2]);
    // Left hole
    translate([thickness, thickness, thickness/2]) cube([thickness/2, size-2*thickness, thickness/2]);
    // Right hole
    translate([size-2*thickness, thickness, thickness/2]) cube([thickness/2, size-2*thickness, thickness/2]);

    // Extend holes past the main body on the Z-axis
    translate([0, 0, thickness]) {
        // Top hole
        difference() {
            union() {
                cube([size-2*thickness, size-2*thickness, thickness/2]);
                translate([thickness, thickness, 0]) cube([size-2*thickness, thickness/2, thickness/2]);
            };
            translate([0, 0, thickness]) cube([thickness/2, size-2*thickness, thickness/2]);
        };
        // Bottom hole
        difference() {
            union() {
                cube([size-2*thickness, size-2*thickness, thickness/2]);
                translate([thickness, size-2*thickness, 0]) cube([size-2*thickness, thickness/2, thickness/2]);
            };
            translate([0, 0, thickness]) cube([thickness/2, size-2*thickness, thickness/2]);
        };
        // Left hole
        difference() {
            union() {
                cube([size-2*thickness, size-2*thickness, thickness/2]);
                translate([thickness, thickness, 0]) cube([thickness/2, size-2*thickness, thickness/2]);
            };
            translate([0, 0, thickness]) cube([thickness/2, size-2*thickness, thickness/2]);
        };
        // Right hole
        difference() {
            union() {
                cube([size-2*thickness, size-2*thickness, thickness/2]);
                translate([thickness, thickness, 0]) cube([thickness/2, size-2*thickness, thickness/2]);
            };
            translate([0, 0, thickness]) cube([thickness/2, size-2*thickness, thickness/2]);
        };
    }
}

