        cylinder(h=thickness, r=bodyOuterDiameter/2, $fn=100);
        cylinder(h=thickness, r=bodyInnerDiameter/2, $fn=100);
    }
    // Create the flange
    difference() {
        cylinder(h=thickness, r=flangeOuterDiameter/2, $fn=100);
