        translate([0, 0, thickness/2]) {
            cylinder(r=radius + chamfer_radius, h=chamfer_length, centered=true);
        }
    }

    // Flange of the bushing
    translate([0, 0, body_height - thickness/2]) {
        cylinder(r=radius + chamfer_radius, h=chamfer_length, centered=true);
    }

    // Hole in the body
    translate([0, 0, body_height - thickness - 3*chamfer_length/2]) {
