module structural_l_bracket(size, thickness) {
  // Define the overall dimensions of the bracket
  size = size || 98; // Default size is 98mm
  thickness = thickness || 14; // Default thickness is 14mm

  // Define the dimensions of the rectangular pattern of mounting holes
  hole_spacing = size / 4; // Calculate spacing between holes

  // Define the dimensions of the holes
  hole_diameter = 5; // Define diameter of the holes

  // Generate the rectangular pattern of mounting holes
  for (x = [0:3]) {
    for (y = [0:3]) {
      translate([x * hole_spacing, y * hole_spacing, -hole_diameter / 2 + thickness / 2]) {
        cylinder(diameter = hole_diameter, height = hole_spacing);
      }
    }
  }

  // Create the main body of the bracket
  translate([0, 0, -thickness / 2]) {
    box(size = [size, size, size], center = true);
  }

  // Add support to the top and bottom of the bracket
  translate([0, 0, size - thickness / 2]) {
    box(size = [size, size, thickness / 2], center = true);
  }
}

