module u_channel_bracket() {
    // Create the base of the bracket
    difference() {
        cube([channel_width, channel_height, thickness], center = true);
        // Create the channel
        difference() {
            cylinder(r = channel_width / 2, h = thickness, center = true);
            translate([0, channel_height / 2, 0]) {
                cylinder(r = channel_height / 2, h = thickness, center = true);
            }
        }
    }

    // Add circular mounting holes
    translate([channel_width / 2, channel_height / 2, thickness / 2]) {
        for (i = [0:3]) {
            for (j = [0:3]) {
                difference() {
                    translate([i * 2 * hole_radius, j * 2 * hole_radius, thickness / 2]) {
                        cylinder(r = hole_radius, h = thickness, center = true);
                    }
                }
            }
        }
    }
}

