module cylinder_spacer(size, hole_diameter, hole_spacing) {
    // Calculate the radius of the cylinder
    radius = size / 2;

    // Calculate the height of the cylinder
    height = size - 2 * hole_spacing;

    // Calculate the outer radius of the holes
    outer_radius = hole_diameter / 2;

    // Calculate the inner radius of the holes
    inner_radius = outer_radius - hole_spacing / 2;

    // Define the cylinder
    cylinder(
        center = [0, 0, height],
        radius = radius,
        height = height
    );

    // Define the holes
    difference() {
        // Define the bottom hole
        translate([0, 0, hole_spacing]) cylinder(
            center = [0, 0, hole_spacing],
            radius = inner_radius
        );

        // Define the top hole
        translate([0, 0, height - hole_spacing]) cylinder(
            center = [0, 0, height - hole_spacing],
            radius = inner_radius
        );

        // Define the left hole
        translate([-hole_spacing / 2, 0, hole_spacing]) cylinder(
            center = [-hole_spacing / 2, 0, hole_spacing],
            radius = inner_radius
        );

        // Define the right hole
        translate([hole_spacing / 2, 0, hole_spacing]) cylinder(
            center = [hole_spacing / 2, 0, hole_spacing],
            radius = inner_radius
        );
    }
}

