module cylinder_spacer(size, thickness, hex_radius) {
    // Create a cylinder
    cylinder(
        radius = size / 2,
        height = size,
        center = [0, 0, 0]
    );

    // Create a hexagonal recess
    hexagon(
        radius = hex_radius,
        center = [0, size / 2, thickness / 2]
    );

    // Subtract the hexagonal recess from the cylinder
    difference() {
        cylinder(
            radius = size / 2,
            height = size,
            center = [0, 0, 0]
        );
        hexagon(
            radius = hex_radius,
            center = [0, size / 2, thickness / 2]
        );
    }
}

