module hexagonal_standoff(size = 81, thickness = 12, chamfer = 2) {
  // Define the hexagonal prism
  hexagonal_prism(size, thickness);

  // Apply the chamfer on the primary outer edges
  chamfer_edges(primary_edges(hexagonal_prism(size, thickness)), chamfer);
}

// Helper function to create a hexagonal prism
module hexagonal_prism(size, thickness) {
  translate([0, 0, thickness / 2])
  linear_extrude(thickness)
  polygon([
    [0, 0],
    [size / 2, size / 2 * sqrt(3)],
    [size, 0],
    [size / 2, -size / 2 * sqrt(3)],
    [0, -size]
  ]);
}

// Helper function to apply a chamfer to a set of edges
module chamfer_edges(edges, chamfer) {
  for (i = [0, length(edges) - 1]) {
    translate([edges[i][0], edges[i][1], 0])
    cylinder(diameter = edges[i][2] - 2 * chamfer, height = thickness, center = true);
  }
}

