module circular_pipe_flange(radius, thickness, hole_radius, hole_spacing, hole_rows) {
    // Create the base of the pipe flange
    translate([0, 0, -thickness]) {
        cylinder(r=radius, h=thickness*2);
    }

    // Define the hole positions
    for (i = [1:hole_rows]) {
        for (j = [1:hole_rows]) {
            translate([i*hole_spacing, j*hole_spacing, -thickness/2]) {
                cylinder(r=hole_radius, h=thickness);
            }
        }
    }
}

