        translate([size / 2 - chamfer_size / 2, size / 2 - chamfer_size / 2, size - chamfer_size]) cube([chamfer_size, chamfer_size, thickness]);
        translate([size / 2 - chamfer_size / 2, size / 2 + chamfer_size / 2, thickness]) cube([chamfer_size, chamfer_size, thickness]);
        translate([size / 2 + chamfer_size / 2, size / 2 - chamfer_size / 2, thickness]) cube([chamfer_size, chamfer_size, thickness]);
