module pipe_flange(radius, thickness) {
    // Define the outer circle
    cylinder(r=radius+thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);

    // Define the inner circle
    cylinder(r=radius-thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);

    // Define the rectangular mounting pattern
    // The pattern is arranged in a square, with 2 holes in each direction
    // The holes are at the center of the rectangular pattern
    // The center of the rectangle is at the origin (0, 0)
    // The side length of the rectangle is 2 * thickness
    // The distance between the holes is 2 * radius (since the holes are at the center of the rectangle)
    // The center of the rectangle is at the origin (0, 0)
    // The side length of the rectangle is 2 * thickness
    // The distance between the holes is 2 * radius (since the holes are at the center of the rectangle)
    translate([0, 0, -thickness/2]) {
        square([2*thickness, 2*thickness], center=true);
        translate([radius, radius, -thickness/2]) {
            cylinder(r=radius-thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);
        }
        translate([radius, -radius, -thickness/2]) {
            cylinder(r=radius-thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);
        }
        translate([-radius, radius, -thickness/2]) {
            cylinder(r=radius-thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);
        }
        translate([-radius, -radius, -thickness/2]) {
            cylinder(r=radius-thickness/2, h=thickness, center=true, chamfer=0.2, chamfer_dir=1);
        }
    }
}

