        translate([-size / 2 + thickness / 2, size / 2 - thickness / 2, 0]) rotate([0, 0, 45]) cylinder(r = thickness / 2, h = size);
        translate([size / 2 - thickness / 2, -size / 2 + thickness / 2, 0]) rotate([0, 0, 45]) cylinder(r = thickness / 2, h = size);
        translate([-size / 2 + thickness / 2, -size / 2 + thickness / 2, 0]) rotate([0, 0, 45]) cylinder(r = thickness / 2, h = size);
    }
}

