// Structural L-bracket with four circular mounting holes
module l_bracket(h = 92, w = 20, t = 14) {
    // Top face
    rotate([90, 0, 0]) {
        translate([0, 0, 0])
            difference() {
                // Bottom face
                cube([w, h - 2 * t, t]);
                // Vertical face
                translate([0, 0, h - t])
                    cube([w, t, h - t - 2 * t]);
                // Horizontal face
                translate([w / 2 - t, 0, h / 2 - t])
                    cube([t, h - t, t]);
            };
    };

    // Mounting holes
    translate([w / 2 - t, 0, 0])
        rotate([90, 0, 0])
            cylinder(r = 3, h = h / 2, center = true);
    translate([w / 2 - t, h / 2 - t, 0])
        rotate([90, 0, 0])
            cylinder(r = 3, h = h / 2, center = true);
    translate([w / 2 - t, h / 2, h / 2 - t])
        rotate([90, 0, 0])
            cylinder(r = 3, h = h / 2, center = true);
    translate([w / 2 - t, h / 2 - t, h / 2 - t])
        rotate([90, 0, 0])
            cylinder(r = 3, h = h / 2, center = true);
}

