// Base plate
module hexagonal_standoff_base(size) {
    // Hexagonal base
    translate([-size/2, 0, 0])
    difference() {
        cylinder(d=size/2, h=size, $fn=100);
        translate([size/2, 0, 0])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, size/2, 0])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, -size/2, 0])
        cylinder(d=size/2, h=size, $fn=100);
    }

    // Thicker base plate
    translate([0, 0, size/2])
    difference() {
        cylinder(d=size/2, h=size, $fn=100);
        translate([size/2, 0, size/2])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, size/2, size/2])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, -size/2, size/2])
        cylinder(d=size/2, h=size, $fn=100);
    }

    // Mounting tab
    translate([size/2, 0, -size/2])
    difference() {
        cylinder(d=size/2, h=size, $fn=100);
        translate([size/2, 0, size/2])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, size/2, size/2])
        cylinder(d=size/2, h=size, $fn=100);
        translate([0, -size/2, size/2])
        cylinder(d=size/2, h=size, $fn=100);
    }
}

