module corner_gusset(size=58, thickness=7, hex_radius=4.5) {
    // Define the main body of the corner gusset
    union() {
        // Create the corner
        difference() {
            // Create the hexagonal recess
            intersection() {
                // Create the hexagonal recess with specified radius
                translate([thickness/2, thickness/2, thickness/2]) {
                    hex(hex_radius, 6);
                }
                // Create the corner with specified size and thickness
                rotate([90, 0, 0]) {
                    cube([size, size, thickness]);
                }
            }
            // Create the body with specified thickness and size
            translate([thickness/2, thickness/2, 0]) {
                cube([size, size, thickness]);
            }
        }
        // Create the opening for the hex nut
        translate([thickness/2, thickness/2, thickness/2]) {
            cylinder(r=hex_radius, h=size, center=[0, 0, 0], resolution=100);
        }
    }
}

