module flat_mounting_plate(length, width, thickness, hex_radius, hex_height, hex_depth) {
    // Create the flat plate
    union() {
        difference() {
            difference() {
                cylinder(r=width/2, h=thickness, center=false);
                cylinder(r=width/2, h=thickness-1, center=false);
            }
            difference() {
                cylinder(r=width/2, h=thickness-1, center=false);
                cylinder(r=width/2, h=thickness-2, center=false);
            }
        }
        difference() {
            difference() {
                cylinder(r=width/2, h=thickness-2, center=false);
                cylinder(r=width/2, h=thickness-3, center=false);
            }
            difference() {
                cylinder(r=width/2, h=thickness-3, center=false);
                cylinder(r=width/2, h=thickness-4, center=false);
            }
        }
    }

    // Create the hexagonal recess
    difference() {
        difference() {
            difference() {
                cylinder(r=hex_radius, h=hex_height, center=false);
                cylinder(r=hex_radius, h=hex_height-1, center=false);
            }
            difference() {
                cylinder(r=hex_radius, h=hex_height-1, center=false);
                cylinder(r=hex_radius, h=hex_height-2, center=false);
            }
        }
        difference() {
            difference() {
                cylinder(r=hex_radius, h=hex_height-2, center=false);
                cylinder(r=hex_radius, h=hex_height-3, center=false);
            }
            difference() {
                cylinder(r=hex_radius, h=hex_height-3, center=false);
                cylinder(r=hex_radius, h=hex_height-4, center=false);
            }
        }
    }

    // Subtract the hexagonal recess from the plate
    difference() {
        difference() {
            difference() {
                cylinder(r=width/2, h=thickness, center=false);
                cylinder(r=width/2, h=thickness-1, center=false);
            }
            difference() {
                cylinder(r=width/2, h=thickness-1, center=false);
                cylinder(r=width/2, h=thickness-2, center=false);
            }
        }
        difference() {
            difference() {
                cylinder(r=width/2, h=thickness-2, center=false);
                cylinder(r=width/2, h=thickness-3, center=false);
            }
            difference() {
                cylinder(r=width/2, h=thickness-3, center=false);
                cylinder(r=width/2, h=thickness-4, center=false);
            }
        }
    }
}

