module spacer(size, thickness, chamfer_size) {
    // Calculate the radius of the cylinder
    radius = size / 2;

    // Calculate the height of the cylinder
    height = size - 2 * thickness;

    // Create the outer cylinder with chamfer
    cylinder(
        r = radius - chamfer_size,
        h = height,
        center = true
    );

    // Create the inner cylinder
    cylinder(
        r = radius,
        h = height,
        center = true
    );

    // Difference between the two cylinders
    difference() {
        cylinder(
            r = radius - chamfer_size,
            h = height,
            center = true
        );
        cylinder(
            r = radius,
            h = height,
            center = true
        );
    }
}

