// Define parameters for the spacer
module cylindrical_spacer(size, thickness, chamfer){
    // Calculate the radius of the spacer
    radius = size / 2 - thickness / 2;

    // Create the spacer with chamfer on the primary outer edges
    difference(){
        cylinder(r=radius, h=size + thickness);
        translate([chamfer, 0, 0]){
            cylinder(r=radius, h=size + thickness);
        }
    }
}

// Call the module with the specified parameters
cylindrical_spacer(size=82, thickness=8, chamfer=2);

module flat_mount_plate(size=45, thickness=10, hole_diameter=5, hole_spacing=10) {
    // Define the main body of the plate
    difference() {
        cube([size, size, thickness]);
        // Create a hole for the mounting screw
        difference() {
            cylinder(diameter=hole_diameter, height=thickness);
            translate([hole_diameter/2, hole_diameter/2, thickness - hole_diameter/2]) {
                rotate([90, 0, 0]) {
                    cylinder(diameter=hole_diameter, height=hole_diameter);
                }
            }
        }
    }
}

// Call the module with the desired parameters
flat_mount_plate(size=45, thickness=10, hole_diameter=5, hole_spacing=10);

module cylinder_spacer(radius, height, hex_diameter, hex_depth) {
    // Base cylinder
    cylinder(radius, height, center=false, chamfer=0.1);

    // Hexagonal recess
    hexagonal_recess(hex_diameter, hex_depth, radius, height - 6);
}

// Example usage
cylinder_spacer(25, 45, 4, 2);

// Define the size and thickness of the L-bracket
module LBracket(size, thickness) {
    // Main body of the L-bracket
    cylinder(h=size, d1=size, d2=size, $fn=10);

    // Subtract the holes to prevent 3D rendering artifacts
    difference() {
        // Front hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true);

        // Back hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true, $offset=size/2);

        // Top hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true, $offset=size/4);

        // Bottom hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true, $offset=-size/4);

        // Left hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true, $offset=-size/2);

        // Right hole
        cylinder(h=thickness, d1=size/2, d2=size/2, $fn=10, center=true, $offset=size/2);
    }
}

// Example usage
LBracket(size=48, thickness=4);

module corner_gusset(size, thickness, hex_radius) {
    // Parameters: size (total size), thickness (layer thickness), hex_radius (hex nut radius)

    // Create the base of the gusset
    difference() {
        // Outer shell of the gusset
        cube([size, size, thickness]);

        // Hexagonal recess for the hex nut
        hexagon([size - 2 * hex_radius, size - 2 * hex_radius, thickness], hex_radius);
    }
}

// Example usage
corner_gusset(77, 7, 10);

module shaftCollar(diameter, thickness) {
    // Create the outer cylinder with the specified diameter and thickness
    difference() {
        cylinder(diameter, height=thickness+1, center=true);
        // Create the central through-hole with the specified diameter
        sphere(diameter/2);
    }
}

// Example usage
shaftCollar(diameter=46mm, thickness=15mm);

module corner_gusset(
    size = 47mm, // overall size in mm
    thickness = 15mm // thickness in mm
) {
    // create the bottom face
    difference() {
        box(size - 2*thickness, thickness, thickness);
        cylinder(h=thickness, r=size/2);
    }

    // create the top face
    cylinder(h=thickness, r=size/2);

    // create the center hole
    translate([size/2, thickness/2, thickness/2]) difference() {
        cylinder(h=size-2*thickness, r=size/2);
    }
}

// call the module with the desired parameters
corner_gusset();

// Define parameterized U-channel bracket dimensions
$fn = 50; // Number of segments per circle for arc rendering
$fn2 = 40; // Number of segments per circle for arc rendering on the second part
$fn3 = 40; // Number of segments per circle for arc rendering on the third part

// Define the main body of the bracket
module u_channel_bracket(size, thickness) {
    // Define the arc for the top part of the bracket
    arc(r = size / 2, d = size + thickness, $fn = $fn2);
    // Define the arc for the bottom part of the bracket
    arc(r = size / 2, d = size + thickness, $fn = $fn2, start = 180, end = 360);
    // Define the arc for the left part of the bracket
    arc(r = size / 2, d = size + thickness, $fn = $fn2, start = 0, end = 90);
    // Define the arc for the right part of the bracket
    arc(r = size / 2, d = size + thickness, $fn = $fn2, start = 90, end = 180);
    // Define the hole for the bottom face of the bracket
    cylinder(r = size / 4, h = thickness - 1, $fn = $fn3);
    // Define the hole for the top face of the bracket
    cylinder(r = size / 4, h = thickness - 1, $fn = $fn3, start = 180, end = 360);
    // Define the hole for the left face of the bracket
    cylinder(r = size / 4, h = thickness - 1, $fn = $fn3, start = 0, end = 90);
    // Define the hole for the right face of the bracket
    cylinder(r = size / 4, h = thickness - 1, $fn = $fn3, start = 90, end = 180);
}

// Call the function with parameter values
u_channel_bracket(size = 33, thickness = 6);

module flat_mounting_plate(size, thickness, chamfer) {
    // Calculate the outer dimensions
    outer_size = size - 2*chamfer;

    // Create the outer cylinder with the specified chamfer
    cylinder(h=outer_size, r=chamfer, center=true);

    // Create the inner cylinder with the specified thickness
    cylinder(h=thickness, r=chamfer, center=true, $fn=32);

    // Create the difference between the outer and inner cylinders
    difference() {
        cylinder(h=outer_size, r=chamfer, center=true);
        cylinder(h=thickness, r=chamfer, center=true, $fn=32);
    }
}

// Call the module with the desired dimensions
flat_mounting_plate(48, 5, 2);

module flanged_bushing(
    diameter = 65,
    thickness = 11,
    recess_height = 3
) {
    // Define the basic body of the bushing
    cylinder(diameter/2, diameter/2 + thickness, 360, center = true, chamfer = 0.5);

    // Hexagonal recess
    hexagon(recess_height, diameter, height = recess_height, center = true, chamfer = 0.5);
}

flanged_bushing();

module flanged_bushing(size = 93, thickness = 8) {
    // Main body
    difference() {
        cube([size, size, thickness]);
        // Flange
        translate([0, 0, thickness - 0.5]) {
            difference() {
                cylinder(r = 3, h = thickness - 2, center = true, chamfer = 1);
                // Holes
                translate([0, -0.5, 0]) difference() {
                    cylinder(r = 1, h = thickness - 0.5, center = true, chamfer = 1);
                }
                translate([0, 1.5, 0]) difference() {
                    cylinder(r = 1, h = thickness - 0.5, center = true, chamfer = 1);
                }
            }
        }
    }
}

// Usage
flanged_bushing(size = 93, thickness = 8);

// Define parameters
module shaft_collar(size = 63, thickness = 13, mounting_hole_spacing = 20, mounting_hole_diameter = 4) {
    // Calculate the dimensions
    diameter = size - 2 * thickness;
    length = diameter;
    height = thickness;

    // Create the shaft collar
    cylinder(r = diameter / 2, h = height, center = true, segments = 32);

    // Add mounting holes
    for (i = [0:3]) {
        for (j = [0:3]) {
            translate([i * mounting_hole_spacing, j * mounting_hole_spacing]) {
                cylinder(r = mounting_hole_diameter / 2, h = length, center = true, segments = 32);
            }
        }
    }
}

// Call the module with specified parameters
shaft_collar();

module base(size, thickness) {
    difference() {
        cube(size);
        cube(thickness, center = true);
    }
}

base(72, 10);

module mounting_plate(
    overall_size = [22, 22, 11],
    chamfer_size = 2
) {
    // Define the top surface with a chamfer
    translate([0, overall_size[1] / 2, 0]) rotate([90, 0, 0]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Define the front surface with a chamfer
    translate([overall_size[0] / 2, 0, 0]) rotate([0, 0, 90]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Define the back surface with a chamfer
    translate([overall_size[0] / 2, overall_size[1] / 2, 0]) rotate([0, 180, 0]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Define the left surface with a chamfer
    translate([0, overall_size[1] / 2, overall_size[2] / 2]) rotate([180, 0, 0]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Define the right surface with a chamfer
    translate([overall_size[0] / 2, overall_size[1] / 2, overall_size[2] / 2]) rotate([0, 0, 180]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Define the bottom surface with a chamfer
    translate([0, 0, overall_size[2] / 2]) rotate([0, 0, 0]) {
        cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
    }

    // Union the top, front, back, left, right, and bottom surfaces
    union() {
        translate([0, overall_size[1] / 2, 0]) rotate([90, 0, 0]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
        translate([overall_size[0] / 2, 0, 0]) rotate([0, 0, 90]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
        translate([overall_size[0] / 2, overall_size[1] / 2, 0]) rotate([0, 180, 0]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
        translate([0, overall_size[1] / 2, overall_size[2] / 2]) rotate([180, 0, 0]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
        translate([overall_size[0] / 2, overall_size[1] / 2, overall_size[2] / 2]) rotate([0, 0, 180]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
        translate([0, 0, overall_size[2] / 2]) rotate([0, 0, 0]) {
            cylinder(r1 = chamfer_size, r2 = chamfer_size, h = overall_size[2], center = true, body = false);
        }
    }
}

// Call the module with the desired parameters
mounting_plate();

module shaft_collar(
    main_body_radius = 30,
    collar_radius = 12,
    collar_thickness = 10,
    overall_size = 53,
    hole_diameter = 10,
    hole_depth = 10
) {
    // Create the main body
    difference() {
        cylinder(r=main_body_radius, h=overall_size-collar_thickness, center=true);
        translate([0, 0, collar_thickness/2]) cylinder(r=collar_radius, h=hole_depth, center=true);
    }

    // Create the hole
    translate([0, 0, overall_size-collar_thickness-hole_depth]) cylinder(r=hole_diameter/2, h=hole_depth, center=true);
}

// Example usage
shaft_collar(
    main_body_radius=30,
    collar_radius=12,
    collar_thickness=10,
    overall_size=53,
    hole_diameter=10,
    hole_depth=10
);

// Define the structural L-bracket parameters
module LBracket(
    sizeX = 67,
    sizeY = 67,
    sizeZ = 11,
    mountingHoleRadius = 2
) {
    // Base of the L-bracket
    difference() {
        cube([sizeX, sizeY, sizeZ]);
        translate([sizeX / 2, sizeY / 2, -sizeZ / 2]) cube([sizeX, sizeY, sizeZ]);

        // Mounting holes arranged in a rectangular pattern
        translate([sizeX / 4, sizeY / 2, -sizeZ / 2]) cylinder(r = mountingHoleRadius, h = sizeZ / 2);
        translate([sizeX / 4, sizeY / 2, -sizeZ / 2]) cylinder(r = mountingHoleRadius, h = sizeZ / 2);

        translate([3 * sizeX / 4, sizeY / 2, -sizeZ / 2]) cylinder(r = mountingHoleRadius, h = sizeZ / 2);
        translate([3 * sizeX / 4, sizeY / 2, -sizeZ / 2]) cylinder(r = mountingHoleRadius, h = sizeZ / 2);
    }
}

// Example usage
LBracket();

module spacer(radius, thickness) {
    // Create a cylindrical spacer
    cylinder(r=radius, h=thickness, center=true, chamfer=0.5, chamfer_radius=0.25, chamfer_type=0);

    // Create a hexagonal recess
    hexagon(hex_radius=radius, thickness=thickness/2, center=true);

    // Subtract the hexagonal recess from the cylinder
    difference() {
        cylinder(r=radius, h=thickness, center=true, chamfer=0.5, chamfer_radius=0.25, chamfer_type=0);
        hexagon(hex_radius=radius, thickness=thickness/2, center=true);
    }
}

// Parameters
radius = 65/2;
thickness = 11;

// Call the module
spacer(radius, thickness);

module corner_gusset(radius, thickness) {
    // Create the body of the corner gusset
    difference() {
        cube([thickness, 100, thickness]); // Create the rectangular body
        translate([radius, thickness, radius]) cylinder(r=radius, h=2*radius, center=true); // Create the circular holes
    }
}

// Define the parameters
radius = 36mm;
thickness = 12mm;

