corner_gusset(radius, thickness);

module circular_pipe_flange(
    radius=33mm,
    thickness=10mm,
    hole_diameter=5mm,
    hole_spacing=5mm
) {
    // Create the flange body
    difference() {
        sphere(r=radius - thickness/2);
        cylinder(h=thickness, r=radius);
    }

    // Add four circular mounting holes
    for (i=[1:4]) {
        for (j=[1:4]) {
            translate([i*hole_spacing, j*hole_spacing, 0]) {
                cylinder(r=hole_diameter/2, h=radius + thickness/2);
            }
        }
    }
}

// Call the function with custom parameters
circular_pipe_flange(radius=33mm, thickness=10mm, hole_diameter=5mm, hole_spacing=5mm);

module shaftCollar(
    mainBody = 82,
    holeDiameter = 3,
    holeDepth = 3,
    holeOffset = 2,
    holeOffsetZ = 2,
    holeSpacing = 10
) {
    // Main body
    difference() {
        cube([mainBody, mainBody, mainBody]);
        translate([0, 0, mainBody/2])
            rotate([90, 0, 0])
            cylinder(r = mainBody/2, h = mainBody, centered = false);
    }

    // Holes
    translate([holeOffset, holeOffset, holeDepth])
        rotate([90, 0, 0])
        cylinder(r = holeDiameter/2, h = holeDepth, centered = false);

    // Additional holes for symmetry
    translate([mainBody - holeOffset, holeOffset, holeDepth])
        rotate([90, 0, 0])
        cylinder(r = holeDiameter/2, h = holeDepth, centered = false);

    translate([holeOffset, mainBody - holeOffset, holeDepth])
        rotate([90, 0, 0])
        cylinder(r = holeDiameter/2, h = holeDepth, centered = false);

    translate([mainBody - holeOffset, mainBody - holeOffset, holeDepth])
        rotate([90, 0, 0])
        cylinder(r = holeDiameter/2, h = holeDepth, centered = false);
}

// Usage
 shaftCollar(mainBody = 82, holeDiameter = 3, holeDepth = 3, holeOffset = 2, holeOffsetZ = 2, holeSpacing = 10);

module cylinderSpacer(
    size = 49,
    thickness = 11,
    holeDiameter = 4
) {
    // Create the cylindrical spacer
    difference() {
        cylinder(r=size/2, h=size, center=true, chamfer=1.0, resolution=50);
        cylinder(r=size/2, h=thickness, center=true, chamfer=1.0, resolution=50);
    }

    // Create the rectangular pattern of mounting holes
    translate([size/2, size/2, thickness]) {
        for (i = [0:3]) {
            for (j = [0:3]) {
                translate([i*10, j*10, -thickness]) {
                    cylinder(diameter=holeDiameter, h=size, center=true, chamfer=1.0, resolution=50);
                }
            }
        }
    }
}

cylinderSpacer();

module circular_pipe_flange(radius, thickness) {
    // Define the main body of the pipe flange
    difference() {
        cube([radius + thickness, radius + thickness, 30]); // Define the base of the pipe
        cylinder(r=radius, h=thickness, center=true); // Define the flange
        translate([0, 0, thickness]) {
            cylinder(r=radius, h=10, center=true); // Define the overhang at the top
        }
    }
}

