module rectangular_project_enclosure_base(width=65mm, height=65mm, thickness=4mm, hole_radius=3mm) {
    // Create the base rectangle
    translate([0, 0, thickness/2]) {
        linear_extrude(height - thickness) {
            rectangle(size=[width, height], center=true);
        }
    }

    // Create the circular mounting holes
    translate([0, 0, thickness/2]) {
        for (i = [0:3]) {
            for (j = [0:3]) {
                translate([i * (width / 4), j * (height / 4), 0]) {
                    cylinder(r=hole_radius, h=thickness);
                }
            }
        }
    }
}

// Call the module with specified parameters
rectangular_project_enclosure_base(width=65mm, height=65mm, thickness=4mm, hole_radius=3mm);

// Define the dimensions
module project_base(size, hex_height) {
    // Define the main body of the project enclosure base
    translate([0, 0, 0]) {
        difference() {
            // Create the main rectangular body
            cube(size);

            // Define the hexagonal recess
            translate([0, size[1]/2, size[2]/2]) {
                hex(hex_height, size[1]/4);
            }
        }
    }
}

// Usage
project_base([51, 30, 5], 3.0);

module mounting_plate(radius=70, thickness=11) {
    cylinder(h=thickness, r=radius, center=true);
    difference() {
        cylinder(h=thickness, r=radius-1);
        translate([0, 0, radius-1]) cylinder(h=thickness, r=radius-2);
    }
}

