        cylinder(d=hole_diam+0.5, h=hole_depth, center=true);
        // Subtract a cylinder for the hole with a still larger diameter to account for the final slight variation in the hole geometry
        cylinder(d=hole_diam+0.6, h=hole_depth, center=true);
        // Subtract a cylinder for the hole with a still larger diameter to account for the final slight variation in the hole geometry
