module hexagonal_recess(radius, thickness) {
    // Define the hexagonal recess geometry
    difference() {
        // Create the hexagonal base
        rotate([90, 0, 0]) {
            hexagon(size=radius);
        }

        // Create the hexagonal top
        rotate([90, 0, 0]) {
            translate([0, radius, 0]) {
                hexagon(size=radius);
            }
        }

        // Create the hexagonal bottom
        rotate([90, 0, 0]) {
            translate([0, -radius, 0]) {
                hexagon(size=radius);
            }
        }

        // Create the hexagonal side
        translate([radius, 0, 0]) {
            rotate([0, 90, 0]) {
                hexagon(size=radius);
            }
        }

        // Create the hexagonal side
        translate([-radius, 0, 0]) {
            rotate([0, 90, 0]) {
                hexagon(size=radius);
            }
        }
    }
}

