// Flat mounting plate parameterized code
module flat_mounting_plate(size_x, size_y, thickness) {
    // Define the corners of the plate
    size_x = size_x / 2; // Half the size in each direction
    size_y = size_y / 2;

    // Create the plate with a circular hole at each corner
    difference() {
        // Base plate (rectangle)
        cube([size_x, size_y, thickness]);

        // Center of the plate
        translate([0, 0, thickness / 2]) {
            // First corner with circular hole
            cylinder(r=10, h=size_y - 20, center=true);

            // Second corner with circular hole
            translate([size_x, 0, thickness / 2]) {
                cylinder(r=10, h=size_y - 20, center=true);

                // Third corner with circular hole
                translate([size_x, size_y, thickness / 2]) {
                    cylinder(r=10, h=size_y - 20, center=true);

                    // Fourth corner with circular hole
                    translate([0, size_y, thickness / 2]) {
                        cylinder(r=10, h=size_y - 20, center=true);
                    }
                }
            }
        }
    }
}

