// Parameterized cylindrical spacer
module cylindricalSpacer(size, thickness) {
    // Define the radius of the cylindrical spacer
    radius = size / 2;

    // Define the outer diameter of the cylindrical spacer
    outerDiameter = size + thickness;

    // Define the height of the cylindrical spacer
    height = thickness;

    // Create the cylindrical spacer using a cylinder and a hole for each mounting hole
    cylinder(d=outerDiameter, h=height, center=true);
    translate([0, thickness/2, 0]) {
        cylinder(d=radius, h=2 * thickness, center=true);
    }
    translate([size, thickness/2, 0]) {
        cylinder(d=radius, h=2 * thickness, center=true);
    }
    translate([0, size - thickness/2, 0]) {
        cylinder(d=radius, h=2 * thickness, center=true);
    }
    translate([size, size - thickness/2, 0]) {
        cylinder(d=radius, h=2 * thickness, center=true);
    }
}

