module corner_gusset(size, thickness) {
    // Define the main body of the corner gusset
    union() {
        // Top face
        difference() {
            translate([0, size/2, 0]) {
                box(size, thickness, thickness);
            }
            translate([0, size/2, thickness]) {
                box(size, thickness, thickness);
            }
        }
        // Bottom face
        difference() {
            translate([0, -size/2, 0]) {
                box(size, thickness, thickness);
            }
            translate([0, -size/2, thickness]) {
                box(size, thickness, thickness);
            }
        }
        // Front face
        difference() {
            translate([-size/2, 0, 0]) {
                box(size, thickness, thickness);
            }
            translate([-size/2, 0, thickness]) {
                box(size, thickness, thickness);
            }
        }
        // Back face
        difference() {
            translate([size/2, 0, 0]) {
                box(size, thickness, thickness);
            }
            translate([size/2, 0, thickness]) {
                box(size, thickness, thickness);
            }
        }
        // Left face
        difference() {
            translate([0, 0, -thickness]) {
                box(size, thickness, size);
            }
            translate([0, size, -thickness]) {
                box(size, thickness, size);
            }
        }
        // Right face
        difference() {
            translate([0, 0, thickness]) {
                box(size, thickness, size);
            }
            translate([0, size, thickness]) {
                box(size, thickness, size);
            }
        }
    }

    // Define the holes for the corner gusset
    translate([size/4, size/4, thickness/2]) {
        difference() {
            cylinder(r=3, h=thickness);
            translate([0, thickness, 0]) {
                cylinder(r=3, h=thickness);
            }
        }
    }
}

