corner_gusset(81, 6);

module UChannelBracket(
    size = 67,
    thickness = 3,
    numHoles = 4
) {
    // Define the U-channel profile
    union() {
        difference() {
            translate([-thickness/2, -thickness/2, -thickness/2]) {
                rectangularPrism(size + thickness, size, thickness);
            }
            translate([-thickness/2, size - thickness/2, -thickness/2]) {
                rectangularPrism(size + thickness, size, thickness);
            }
            translate([-size/2, -thickness/2, -thickness/2]) {
                rectangularPrism(size + thickness, size, thickness);
            }
            translate([size/2, -thickness/2, -thickness/2]) {
                rectangularPrism(size + thickness, size, thickness);
            }
        }
        // Add mounting holes in a rectangular pattern
        for (i = [0:(numHoles-1)/2]) {
            for (j = [0:(numHoles-1)/2]) {
                translate([i*thickness, j*thickness, 0]) {
                    cylinder(r=thickness/2, h=size, center=true);
                }
            }
        }
    }
}

