module shaftCollar(size, thickness, chamfer) {
    // Calculate the dimensions
    diameter = size;
    height = diameter;
    outerRadius = diameter - thickness;
    innerRadius = outerRadius - chamfer;

    // Create the shaft collar
    cylinder(h=height, r1=outerRadius, r2=innerRadius, $fn=100);

    // Apply a 2mm chamfer on the primary outer edges
    chamferCylinder(h=height, r1=outerRadius, r2=innerRadius, $fn=100, chamfer=2mm);
}

