module structLBracket(size=52, thck=9, chamfer=2) {
    // Define the main body of the bracket
    difference() {
        // Create the primary outer edges with a chamfer
        linear_extrude(height=thck, chamfer=chamfer) {
            // Draw the primary outer edges
            polygon(points=[
                [0, 0], [size, 0], [size, thck], [0, thck]
            ]);
        }

        // Create the primary inner edges
        linear_extrude(height=thck) {
            // Draw the primary inner edges
            polygon(points=[
                [chamfer, 0], [size - chamfer, 0], [size - chamfer, thck], [chamfer, thck]
            ]);
        }

        // Create the secondary outer edges
        linear_extrude(height=thck) {
            // Draw the secondary outer edges
            polygon(points=[
                [size / 2, 0], [size / 2, thck], [size, thck], [0, thck]
            ]);
        }

        // Create the secondary inner edges
        linear_extrude(height=thck) {
            // Draw the secondary inner edges
            polygon(points=[
                [size / 2 - chamfer, 0], [size / 2 + chamfer, 0], [size, thck], [0, thck]
            ]);
        }
    }

    // Create the top and bottom faces
    difference() {
        // Create the top face
        linear_extrude(height=thck) {
            // Draw the top face
            polygon(points=[
                [0, thck], [size, thck], [size, size], [0, size]
            ]);
        }

        // Create the bottom face
        linear_extrude(height=thck) {
            // Draw the bottom face
            polygon(points=[
                [0, 0], [size, 0], [size, thck], [0, thck]
            ]);
        }
    }
}

