structLBracket();

module flanged_bushing(radius, outer_thickness, inner_thickness, chamfer_depth, chamfer_radius) {
  // Define the outer flange
  difference() {
    cylinder(r = outer_thickness, h = 2*radius, center = true);
    translate([0, 0, outer_thickness]) {
      cylinder(r = outer_thickness - chamfer_radius, h = 2*radius - 2*chamfer_depth, center = true);
    }
  }

  // Define the inner flange
  difference() {
    cylinder(r = inner_thickness, h = 2*radius, center = true);
    translate([0, 0, inner_thickness]) {
      cylinder(r = inner_thickness - chamfer_radius, h = 2*radius - 2*chamfer_depth, center = true);
    }
  }

  // Create the central hole
  translate([0, 0, radius]) {
    cylinder(r = inner_thickness, h = 2*radius - 2*chamfer_depth, center = true);
  }
}

