module project_enclosure_base(size = 71, thickness = 9) {
    // Define the main body and holes
    difference() {
        cube([size, size, thickness]);

        // Define the hole positions and radii
        translate([thickness, thickness, 0]) hole(r = 4);
        translate([size - 8, thickness, 0]) hole(r = 2);
        translate([size - 8, size - 8, 0]) hole(r = 2);

        // Define the protrusions for the sides and ends
        translate([0, 0, thickness]) difference() {
            cylinder(r = 4, h = size - 2 * thickness);
            cylinder(r = 2, h = size - 2 * thickness);
        }
        translate([size, 0, thickness]) difference() {
            cylinder(r = 4, h = size - 2 * thickness);
            cylinder(r = 2, h = size - 2 * thickness);
        }
        translate([0, size, thickness]) difference() {
            cylinder(r = 4, h = size - 2 * thickness);
            cylinder(r = 2, h = size - 2 * thickness);
        }
        translate([size, size, thickness]) difference() {
            cylinder(r = 4, h = size - 2 * thickness);
            cylinder(r = 2, h = size - 2 * thickness);
        }
    }
}

