    cylinder(d = size, h = thickness, center = true, chamfer = thickness / 2, center_hole = true, chamfer_hole = thickness / 2);

    // Define the inner cylinder for the hole
    cylinder(d = size - thickness, h = thickness, center = true, chamfer = thickness / 2, center_hole = true, chamfer_hole = thickness / 2);

    // Difference operation to create the outer cylinder with the inner cylinder subtracted
    difference() {
        cylinder(d = size, h = thickness, center = true, chamfer = thickness / 2, center_hole = true, chamfer_hole = thickness / 2);
        cylinder(d = size - thickness, h = thickness, center = true, chamfer = thickness / 2, center_hole = true, chamfer_hole = thickness / 2);
