        translate([0, 0, thickness / 2]) cube([length, width, thickness / 2]);
        translate([0, width / 2, thickness / 2]) cube([length, thickness / 2, thickness / 2]);
        translate([length, 0, thickness / 2]) cube([thickness / 2, width, thickness / 2]);
        translate([length, width, thickness / 2]) cube([thickness / 2, thickness / 2, thickness / 2]);
    }

    // Create the chamfer on the primary outer edges
    intersection() {
        translate([chamferSize, chamferSize, thickness / 2]) cube([thickness / 2, width - 2 * chamferSize, thickness / 2]);
        translate([length - chamferSize, chamferSize, thickness / 2]) cube([thickness / 2, width - 2 * chamferSize, thickness / 2]);
        translate([chamferSize, length - chamferSize, thickness / 2]) cube([thickness / 2, width - 2 * chamferSize, thickness / 2]);
        translate([length - chamferSize, length - chamferSize, thickness / 2]) cube([thickness / 2, width - 2 * chamferSize, thickness / 2]);
    }
}

