module circular_pipe_flange(r, h, t) {
    // Main body
    difference() {
        cube([r + t, h, t]);
        translate([r + t, h, 0]) cylinder(r, h, t);
    }

    // Outer edge of the flange
    translate([r + t, 0, 0]) cylinder(r, h, t);

    // Inner edge of the flange
    translate([-r - t, 0, 0]) cylinder(r, h, t);

    // Small hole on the flange
    translate([r + 1.5, h/2, 0]) sphere(r/2);

    // Fine holes in the flange
    for (i = [0:5]) {
        translate([r + 3, h/2 + i * 0.5, 0]) cylinder(r/2, h/2, t);
    }
}

