        }
        translate([chamfer, size[1] - chamfer, 0]) {
            cube([size[0] - 2*chamfer, size[1] - 2*chamfer, thickness]);
        }
        translate([size[0] - chamfer, chamfer, 0]) {
            cube([size[0] - 2*chamfer, size[1] - 2*chamfer, thickness]);
        }
        translate([size[0] - chamfer, size[1] - 2*chamfer, 0]) {
