    positions = [
        [hole_offset, hole_offset, hole_offset],
        [hole_offset, hole_offset, hole_offset + hole_spacing],
        [hole_offset, hole_offset + hole_spacing, hole_offset],
        [hole_offset, hole_offset + hole_spacing, hole_offset + hole_spacing]
    ];

    // Create the mounting holes
    foreach (pos, hole) {
