module LBracket(size, hole_diameter) {
    // Create the L-bracket body
    difference() {
        translate([0, 0, size - hole_diameter])
            cube([size - hole_diameter * 2, hole_diameter, hole_diameter]);
        translate([size / 2, 0, hole_diameter])
            cube([hole_diameter * 2, hole_diameter, hole_diameter]);
        translate([0, size / 2, hole_diameter])
            cube([size - hole_diameter * 2, hole_diameter, hole_diameter]);
        translate([size / 2, size / 2, hole_diameter])
            cube([hole_diameter * 2, hole_diameter, hole_diameter]);
    }

    // Define the hole
    translate([size / 2 - hole_diameter / 2, size / 2 - hole_diameter / 2, 0])
        cylinder(hole_diameter / 2, hole_diameter, hole_diameter);
}

