module corner_gusset(size = 43, thickness = 14) {
    // Main Body
    linear_extrude(size) {
        intersection() {
            box(2 * thickness, size, 2 * thickness);
            rotate([90, 0, 0]) {
                difference() {
                    cube(2 * thickness, size, 2 * thickness);
                    translate([0, size / 2, 0]) {
                        cylinder(r = thickness / 2, h = size, center = true);
                    }
                }
            }
        }
    }

    // Mounting Holes
    translate([size / 2, size / 2, thickness / 2]) {
        rotate([0, 0, 90]) {
            difference() {
                cylinder(r = thickness / 2, h = size, center = true);
                translate([0, 0, thickness]) {
                    circle(r = thickness / 2);
                }
            }
        }
    }

    translate([size / 2, size / 2, size / 2]) {
        rotate([0, 0, 90]) {
            difference() {
                cylinder(r = thickness / 2, h = size, center = true);
                translate([0, 0, thickness]) {
                    circle(r = thickness / 2);
                }
            }
        }
    }

    translate([size / 2, size / 2, size / 2]) {
        rotate([0, 0, 90]) {
            difference() {
                cylinder(r = thickness / 2, h = size, center = true);
                translate([0, 0, thickness]) {
                    circle(r = thickness / 2);
                }
            }
        }
    }
}

