    // Define the dimensions
    length = size;
    width = length - 2 * thickness;
    height = thickness;

    // Create the bracket shape
    translate([0, 0, height]) {
        difference() {
            translate([0, 0, -thickness])
                translate([0, width / 2, -thickness])
                    rotate([90, 0, 0])
                    cube([length, thickness, height]);

            translate([0, -width / 2, -thickness])
                rotate([90, 0, 0])
                cube([length, thickness, height]);

            translate([-width, 0, -thickness])
                rotate([90, 0, 0])
                cube([thickness, width, height]);

            translate([width, 0, -thickness])
                rotate([90, 0, 0])
                cube([thickness, width, height]);
        }
    }
}

