    cylinder(r=radius, h=height);
    translate([0, radius * sqrt(3) / 2, -radius / 2])
    cylinder(r=radius, h=height);
    translate([-radius * sqrt(3) / 2, 0, -radius / 2])
    cylinder(r=radius, h=height);
