module shaft_collar(size, thickness) {
    // Base circle
    cylinder(r=2*size/2, h=size, center=true, chamfer=true);

    // Hexagonal recess
    // The hexagonal recess captures a standard metric hex nut
    // Hexagon parameters: r (radius), d (diagonal), h (height)
    // r = size / 2 - 1
    // d = sqrt(3) * (2 * r)
    // h = 2 * r
    hexagon(r=thickness/2 - 1, d=thickness*sqrt(3), h=2*thickness);
}

