    // Define the corner gusset body
    union() {
        // Hexagonal recess
        difference() {
            hexagon(hex_radius, hex_height, hex_depth);
            translate([0, 0, thickness - hex_height]) sphere(hex_radius);
        }

        // Top and bottom faces
        translate([-size / 2, -size / 2, thickness / 2]) rotate([90, 0, 0]) box([size, size, thickness / 2]);

        translate([size / 2, size / 2, thickness / 2]) rotate([90, 0, 0]) box([size, size, thickness / 2]);
    }
}

