module structural_l_bracket(size=88, thickness=3, chamfer=2) {
  // Define the dimensions of the bracket
  length = size - (2 * thickness); // Subtract 4mm for chamfer on both sides

  // Draw the bracket body
  difference() {
    cube([length, thickness, thickness]);
    // Draw the top edge
    difference() {
      difference() {
        cube([length, thickness, thickness]);
        // Draw the bottom edge
        difference() {
          difference() {
            cube([length, thickness, thickness]);
            // Draw the left edge
            difference() {
              difference() {
                cube([length, thickness, thickness]);
                // Draw the right edge
                difference() {
                  difference() {
                    cube([length, thickness, thickness]);
                    // Draw the top edge with chamfer
                    difference() {
                      translate([chamfer/2, thickness/2, thickness/2]) {
                        cylinder(r=chamfer/2, h=length - (2 * thickness), center=true);
                      }
                      translate([chamfer/2, -thickness/2, thickness/2]) {
                        cylinder(r=chamfer/2, h=length - (2 * thickness), center=true);
                      }
                      translate([length - (chamfer/2), thickness/2, thickness/2]) {
                        cylinder(r=chamfer/2, h=length - (2 * thickness), center=true);
                      }
                      translate([length - (chamfer/2), -thickness/2, thickness/2]) {
                        cylinder(r=chamfer/2, h=length - (2 * thickness), center=true);
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

