module corner_gusset(
    size = 32,  // outer size in mm
    thickness = 3, // thickness in mm
    chamfer = 2   // chamfer depth in mm
) {

    // calculate inner dimensions
    inner_size = size - 2 * chamfer;

    // create the corner gusset using a difference operation
    difference() {
        cube(size, center = true); // create the outer cube
        cube(inner_size, center = true); // create the inner cube
        translate([chamfer, 0, 0]) cube(chamfer, center = true); // create the primary outer edge chamfer
        translate([0, chamfer, 0]) cube(chamfer, center = true); // create the secondary outer edge chamfer
        translate([0, 0, chamfer]) cube(chamfer, center = true); // create the base chamfer
    }
}

