module cylindrical_spacer(radius, thickness, chamfer_radius) {
    // Create the inner cylinder
    translate([0, 0, thickness / 2]) cylinder(r=radius - chamfer_radius, h=thickness);

    // Create the outer cylinder
    translate([0, 0, thickness / 2 + radius]) cylinder(r=radius + chamfer_radius, h=thickness);

    // Create the primary outer edges
    translate([0, 0, thickness / 2 + radius]) round_cylinder(r=radius + chamfer_radius, h=2 * chamfer_radius);

    // Create the secondary outer edges
    translate([0, 0, thickness / 2 + 3 * chamfer_radius]) round_cylinder(r=radius + chamfer_radius, h=2 * chamfer_radius);
}

