// Define the dimensions of the pipe flange
module pipe_flange(radius, thickness) {
    // Create the body of the pipe flange
    difference() {
        cylinder(r=radius, h=thickness, center=true);
        translate([0, thickness/2, 0]) {
            difference() {
                // Hexagonal recess
                difference() {
                    union() {
                        translate([thickness/4, 0, 0]) {
                            rotate([90, 0, 0]) {
                                cylinder(r=radius-1, h=2*thickness/3, center=true);
                            }
                        }
                        translate([thickness/4, 2*thickness/3, 0]) {
                            rotate([90, 0, 0]) {
                                cylinder(r=radius-1, h=2*thickness/3, center=true);
                            }
                        }
                    }
                }
                translate([0, thickness/2, 2*thickness/3]) {
                    translate([0, 2*thickness/3, 0]) {
                        rotate([90, 0, 0]) {
                            cylinder(r=radius-1, h=2*thickness/3, center=true);
                        }
                    }
                    translate([0, 2*thickness/3, 2*thickness/3]) {
                        rotate([90, 0, 0]) {
                            cylinder(r=radius-1, h=2*thickness/3, center=true);
                        }
                    }
                }
            }
        }
    }
}

