        translate([0, 0, size[2] - thickness/2])
        cube(size[0], size[1], thickness, size[3]);
    }

    // Define the holes for the L-bracket
    translate([size[0]/2, size[1]/2, 0])
    cube(thickness, thickness, size[2], thickness);

    translate([size[0]/2, -size[1]/2, 0])
    cube(thickness, thickness, size[2], thickness);

    translate([-size[0]/2, size[1]/2, 0])
    cube(thickness, thickness, size[2], thickness);

    translate([-size[0]/2, -size[1]/2, 0])
    cube(thickness, thickness, size[2], thickness);
}

