module structural_l_bracket(
    size = 39, // Overall size in mm
    thickness = 7, // Thickness in mm
    chamfer_size = 2  // Chamfer size in mm
) {
    // Define the bottom part of the L-bracket
    difference() {
        // Bottom plate
        cube(size - (2 * thickness));

        // Bottom chamfer
        translate([0, 0, thickness + chamfer_size / 2])
            rotate([0, 0, 90])
            cube([size - (2 * thickness), thickness, chamfer_size / 2]);

        // Bottom chamfer
        translate([0, size - thickness - chamfer_size / 2])
            rotate([0, 0, 90])
            cube([size - (2 * thickness), thickness, chamfer_size / 2]);
    }

    // Define the top part of the L-bracket
    translate([0, 0, size - thickness - chamfer_size / 2])
        rotate([0, 0, 90])
        cube([size - (2 * thickness), thickness, thickness - chamfer_size / 2]);
}

