module hexagonal_standoff(
  size = 25,  // overall size in mm
  thickness = 3  // thickness in mm
) {
  // Define the outer hexagon
  translate([0, 0, size / 2]) {
    rotate([0, 0, 60]) {
      difference() {
        // Center the hexagon
        rotate([0, 0, 60]) {
          difference() {
            translate([size / 4, 0, 0]) {
              // Top of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
            translate([size / 2, size / 2, 0]) {
              // Bottom of the hexagon
              cylinder(r = size / 2, h = thickness, center = true, chamfer = thickness / 2);
            }
            translate([size / 4, -size / 4, 0]) {
              // Side of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
            translate([-size / 4, -size / 4, 0]) {
              // Opposite side of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
          }
        }
        // Center the hexagon
        translate([0, 0, size / 2]) {
          difference() {
            translate([size / 4, 0, 0]) {
              // Top of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
            translate([size / 2, size / 2, 0]) {
              // Bottom of the hexagon
              cylinder(r = size / 2, h = thickness, center = true, chamfer = thickness / 2);
            }
            translate([size / 4, -size / 4, 0]) {
              // Side of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
            translate([-size / 4, -size / 4, 0]) {
              // Opposite side of the hexagon
              cylinder(r = size / 2, h = thickness, center = true);
            }
          }
        }
      }
    }
  }
}

