module circular_pipe_flange(d, t, chamfer_thick = 2mm) {
  // Parameters: d - outer diameter, t - thickness, chamfer_thick - thickness of the chamfer

  // Create the pipe body
  cylinder(h = t, r = d / 2, center = true);

  // Apply chamfer to the primary outer edges
  translate([0, 0, -chamfer_thick]) {
    difference() {
      cylinder(h = t, r = d / 2, center = true);
      translate([0, 0, t - chamfer_thick]) {
        cylinder(h = t - chamfer_thick, r = (d / 2) - chamfer_thick / 2, center = true);
      }
    }
  }

  // Optionally, add a secondary chamfer if needed
  translate([0, 0, -chamfer_thick * 2]) {
    difference() {
      cylinder(h = t, r = d / 2, center = true);
      translate([0, 0, t - chamfer_thick * 2]) {
        cylinder(h = t - chamfer_thick * 2, r = (d / 2) - chamfer_thick / 2, center = true);
      }
    }
  }
}

