module cylinder_spacer(param, body_radius, body_height, hole_diameter, hole_depth, hole_position, hole_offset) {
    // Body
    difference() {
        cylinder(body_height, body_radius);
        translate([0, 0, body_height - hole_depth - hole_position]) {
            cylinder(hole_depth, hole_diameter);
        }
    }

    // Holes
    translate([0, 0, hole_position + hole_offset]) {
        translate([0, 0, hole_diameter / 2]) {
            translate([hole_diameter / 2, 0, 0]) {
                cylinder(hole_depth, hole_diameter);
            }
        }
    }

    translate([0, 0, hole_position + hole_offset + hole_diameter / 2]) {
        translate([hole_diameter / 2, 0, 0]) {
            cylinder(hole_depth, hole_diameter);
        }
    }
}

