// Define the overall size and thickness of the pipe flange
module pipe_flange(size, thickness) {
    // Calculate the half-size for the pipe flange
    half_size = size / 2;

    // Create the main body of the pipe flange
    cylinder(r=half_size, h=size, center=true, chamfer=true, chamfer_radius=0.2);

    // Subtract the central hole
    difference() {
        cylinder(r=half_size - thickness, h=size - thickness, center=true, chamfer=true, chamfer_radius=0.2);
        cylinder(r=half_size + thickness, h=size + thickness, center=true, chamfer=true, chamfer_radius=0.2);
    }

    // Subtract the smaller hole
    difference() {
        cylinder(r=half_size - 2 * thickness, h=size - 2 * thickness, center=true, chamfer=true, chamfer_radius=0.2);
        cylinder(r=half_size + 2 * thickness, h=size + 2 * thickness, center=true, chamfer=true, chamfer_radius=0.2);
    }
}

