module circular_pipe_flange(radius, thickness, mounting_hole_count, mounting_hole_spacing) {
    // Define the overall size
    length = 34mm;
    width = 34mm; // Assuming the pipe is square for simplicity

    // Define the mounting holes
    mounting_hole_diameter = 5mm;
    mounting_hole_spacing = 10mm; // Adjust as needed

    // Create the flange
    cylinder(flange_height=length, radius=radius, center=true);

    // Create the mounting holes
    for (i=range(mounting_hole_count)) {
        x = (length - mounting_hole_spacing) / (2 * mounting_hole_spacing) * i;
        y = (width - mounting_hole_spacing) / (2 * mounting_hole_spacing) * i;
        translate([x, y, thickness]) {
            cylinder(diameter=mounting_hole_diameter, height=thickness, center=true);
        }
    }
}

