module corner_gusset(size, thickness) {
    // Define the geometry of the corner gusset
    // The size and thickness are parameters that can be adjusted
    // The corner gusset will have a hexagonal recess to capture a metric hex nut
    // The overall size is 48mm with a thickness of 6mm

    // Top part of the corner gusset
    difference() {
        cube(size - 2*thickness); // Subtract the thickness from the size to create a hollow part
        cylinder(r=1, h=size, center=true); // Create a cylinder for the top part
    }

    // Bottom part of the corner gusset
    difference() {
        cube(size - 2*thickness); // Subtract the thickness from the size to create a hollow part
        cylinder(r=1, h=size, center=true); // Create a cylinder for the bottom part
    }

    // Hexagonal recess in the corner gusset
    difference() {
        cube(size - 2*thickness); // Subtract the thickness from the size to create a hollow part
        cylinder(r=1, h=size, center=true); // Create a cylinder for the recess
    }
}

