module u_channel_bracket(size = 37, thickness = 5, hex_radius = 1.5) {
    // Define the outer U-channel
    difference() {
        cube([size, size, thickness]);
        rotate([90, 0, 0]) {
            intersection() {
                cylinder(radius = size / 2, height = thickness, center = [0, 0, thickness / 2]);
                cylinder(radius = size / 2, height = thickness, center = [size, size / 2, thickness / 2]);
            }
        }
    }

    // Define the hexagonal recess
    rotate([90, 0, 0]) {
        cylinder(radius = hex_radius, height = thickness / 2);
        cylinder(radius = hex_radius, height = thickness / 2, center = [size / 2, 0, thickness / 2]);
        cylinder(radius = hex_radius, height = thickness / 2, center = [0, size / 2, thickness / 2]);
        cylinder(radius = hex_radius, height = thickness / 2, center = [size / 2, size / 2, thickness / 2]);
    }
}

