module cylindrical_spacer(radius, thickness, hole_radius, hole_distance, hole_count_x, hole_count_y) {
    // Calculate dimensions
    spacer_diameter = 2 * radius;
    spacer_height = thickness;
    mounting_hole_diameter = 2 * hole_radius;
    mounting_hole_spacing = hole_distance;
    mounting_hole_count_x = hole_count_x;
    mounting_hole_count_y = hole_count_y;

    // Generate outer cylinder
    cylinder(spacer_diameter, spacer_height, center=true);

    // Generate mounting holes
    for (x = [0:mounting_hole_count_x-1]) {
        for (y = [0:mounting_hole_count_y-1]) {
            translate([mounting_hole_spacing * x, mounting_hole_spacing * y, -thickness/2]) {
                cylinder(mounting_hole_diameter, thickness, center=true);
            }
        }
    }
}

