// Define the parameters
module flanged_bushing(
    overall_size = 73mm,
    thickness = 6mm,
    radius = 20mm,
    clearance = 1mm
) {
    // Create the main body of the bushing
    cylinder(r=radius, h=overall_size, center=true, chamfer=radius/2);

    // Create the flange section
    translate([0, 0, thickness]) {
        cylinder(r=radius+clearance, h=thickness, center=true, chamfer=radius/2);
    }

    // Subtract the flange from the main body
    difference() {
        cylinder(r=radius, h=overall_size, center=true, chamfer=radius/2);
        translate([0, 0, thickness]) {
            cylinder(r=radius+clearance, h=thickness, center=true, chamfer=radius/2);
        }
    }
}

// Call the module with the specified parameters
flanged_bushing(overall_size=73mm, thickness=6mm, radius=20mm, clearance=1mm);

// Define the dimensions
module u_channel_bracket(size = [94, 12, 12]) {
    // Main body
    box(length = size[0], height = size[1], width = size[2], center = true);

    // Center hole
    translate([size[0] / 2, size[1] / 2, size[2]]) {
        cylinder(r = 1, h = size[2], center = true);
    }

    // Corner holes
    translate([0, 0, size[2] - 1]) {
        cylinder(r = 1, h = 2, center = true);
    }
    translate([size[0] - 1, 0, size[2] - 1]) {
        cylinder(r = 1, h = 2, center = true);
    }
    translate([0, size[1] - 1, size[2] - 1]) {
        cylinder(r = 1, h = 2, center = true);
    }
    translate([size[0] - 1, size[1] - 1, 0]) {
        cylinder(r = 1, h = 2, center = true);
    }

    // Additional geometry
    // Here you can add any other parts or holes to the bracket
    // For example, a small hole for a screw or a label
    translate([size[0] / 4, size[1] / 4, size[2] - 3]) {
        cylinder(r = 0.5, h = 2, center = true);
    }
}

// Call the module with the desired size
u_channel_bracket();

module circular_pipe_flange(size, thickness, chamfer_size) {
    // Calculate the dimensions
    outer_diameter = size + 2 * chamfer_size;
    inner_diameter = outer_diameter - 2 * thickness;
    outer_radius = outer_diameter / 2;
    inner_radius = inner_diameter / 2;

    // Create the outer pipe
    difference() {
        cylinder(r=outer_radius, h=outer_diameter + 2 * chamfer_size, center=true);
        cylinder(r=inner_radius, h=inner_diameter + 2 * chamfer_size, center=true);
    }

    // Create the inner pipe
    cylinder(r=inner_radius, h=thickness, center=true);

    // Create the chamfer
    difference() {
        cylinder(r=chamfer_size, h=outer_diameter + 2 * chamfer_size, center=true);
        cylinder(r=chamfer_size, h=thickness, center=true);
    }
}

// Usage
circular_pipe_flange(31, 13, 2);

// Define the main dimensions
module u_channel_bracket(size=43, thickness=12, chamfer=2) {
    // Create the top part of the U-channel bracket
    rotate([90, 0, 0]) {
        difference() {
            // Top part of the bracket
            union() {
                // Main body of the bracket
                cube([size, thickness, thickness]);
                // Chamfer on the primary outer edges
                translate([chamfer/2, 0, 0]) {
                    difference() {
                        translate([-chamfer/2, 0, 0]) {
                            cube([size, thickness, thickness]);
                        }
                        translate([0, chamfer/2, 0]) {
                            cube([size, thickness, thickness]);
                        }
                        translate([0, 0, chamfer/2]) {
                            cube([size, thickness, thickness]);
                        }
                    }
                }
            }
        }
        // Bottom part of the bracket
        translate([0, 0, thickness]) {
            difference() {
                cube([size, thickness, thickness]);
                // Chamfer on the primary outer edges
                translate([chamfer/2, 0, 0]) {
                    difference() {
                        translate([-chamfer/2, 0, 0]) {
                            cube([size, thickness, thickness]);
                        }
                        translate([0, chamfer/2, 0]) {
                            cube([size, thickness, thickness]);
                        }
                        translate([0, 0, chamfer/2]) {
                            cube([size, thickness, thickness]);
                        }
                    }
                }
            }
        }
    }
}

// Call the function with the desired dimensions
u_channel_bracket();

module flanged_bushing(size=50, thickness=4) {
