// Parameterized OpenSCAD code for a hexagonal standoff
// Overall size: 82mm x 82mm x 5mm

module hexagonal_standoff(base_diameter, tab_length) {
    // Base plate
    translate([0, 0, 0]) {
        cylinder(r=base_diameter/2, h=5, center=true, segments=20);
    }

    // Tab
    translate([0, 0, 5 + base_diameter/2]) {
        cylinder(r=base_diameter/2, h=tab_length, center=true, segments=20);
    }
}

