module flanged_bushing(size = 86, thickness = 15) {
    // Define the radius of the flange
    r = size / 2 - thickness;

    // Define the radius of the through-hole
    hole_radius = r / 2 - 2;

    // Create the flange with a hole in the middle
    difference() {
        cylinder(r = size, h = thickness);
        cylinder(r = hole_radius, h = thickness, center = [0, 0, hole_radius]);
    }
}

