module cylindrical_spacer(size, thickness, chamferHeight) {
    // Create the outer cylinder
    cylinder(d=size/2, h=size*2, center=true, chamfer=chamferHeight);

    // Create the inner cylinder
    cylinder(d=size/2-thickness, h=size*2, center=true, chamfer=chamferHeight);

    // Difference between the outer and inner cylinders to get the spacer
    difference() {
        cylinder(d=size/2, h=size*2, center=true, chamfer=chamferHeight);
        cylinder(d=size/2-thickness, h=size*2, center=true, chamfer=chamferHeight);
    }
}

// Call the module with the desired parameters
cylindrical_spacer(75, 14, 2);

module corner_gusset(size, thickness) {
    // Main body of the corner gusset
    difference() {
        cylinder(r = size - thickness, h = thickness + 2, center = true);
        translate([0, thickness / 2, 0]) {
            cylinder(r = size - thickness, h = 2 * thickness, center = true);
        }
    }

    // Chamfer on the primary outer edges
    chamfer(d1 = 2, d2 = 2) {
        translate([0, thickness / 2, 0]) {
            difference() {
                cylinder(r1 = size - thickness, h = thickness + 2, center = true);
                cylinder(r2 = size - thickness, h = 2 * thickness, center = true);
            }
        }
    }
}

// Call the module with the specified parameters
corner_gusset(size = 40, thickness = 12);

