module cylindrical_spacer(radius, height) {
  // Cylinder
  cylinder(r=radius, h=height, center=true);

  // Main body
  translate([0, 0, height/2]) {
    // Subtracting holes
    hole(d=10, r=radius - 5, center=true);
    hole(d=12, r=radius - 10, center=true);
  }

  // Z-axis extension for holes
  translate([0, 0, -15]) {
    difference() {
      cylinder(r=radius, h=15, center=true);
      translate([0, 0, height/2 + 15]) {
        hole(d=10, r=radius - 5, center=true);
        hole(d=12, r=radius - 10, center=true);
      }
    }
  }
}

