    cylinder(size = size, h = 14, center = true, chamfer = 0.5);

    // Create a hexagonal recess
    hexagonal_recess(hex_size);

    // Subtract the hexagonal recess from the outer cylinder
    difference() {
        cylinder(size = size, h = 14, center = true, chamfer = 0.5);
        hexagonal_recess(hex_size);
    }
}

