  cube([size / 2, size / 2, thickness], center = true);
  translate([0, size / 2, 0]) {
    cylinder(r = size / 2, h = thickness, center = true);
  }
  translate([0, -size / 2, 0]) {
    cylinder(r = size / 2, h = thickness, center = true);
  }
  translate([size / 2, 0, 0]) {
    cylinder(r = size / 2, h = thickness, center = true);
  }
  translate([-size / 2, 0, 0]) {
    cylinder(r = size / 2, h = thickness, center = true);
  }

  // Define the hexagonal recess
  translate([0, 0, thickness + 2]) {
    hexagon(h = size / 2, r = 2, center = true);
  }
}

