module u_channel_bracket(d=42, t=4, r=2.5, holes=4, hole_spacing=5) {
    // Base of the bracket
    difference() {
        rectangle([d, t]);
        // Mounting holes
        for (i = [0:holes-1]) {
            translate([r + (hole_spacing * i), t / 2]) cylinder(r=r, h=hole_spacing * (holes + 1), center=true);
        }
    }
}

