// Define the cylindrical spacer with parameters
module cylindricalSpacer(radius, height, thickness, chamferThickness) {
    // Calculate the total length of the spacer
    length = height + 2 * chamferThickness;

    // Create the outer cylindrical part
    cylinder(
        radius = radius,
        height = height,
        chamfer = chamferThickness,
        center = true
    );

    // Create the inner cylindrical part
    cylinder(
        radius = radius,
        height = height - thickness,
        chamfer = chamferThickness,
        center = true
    );

    // Create the chamfering on the primary outer edges
    difference() {
        union() {
            cylinder(
                radius = radius,
                height = thickness,
                chamfer = chamferThickness,
                center = true
            );

            cylinder(
                radius = radius,
                height = thickness,
                chamfer = chamferThickness,
                center = true
            );
        }

        cylinder(
            radius = radius,
            height = thickness / 2,
            chamfer = chamferThickness,
            center = true
        );

        cylinder(
            radius = radius,
            height = thickness / 2,
            chamfer = chamferThickness,
            center = true
        );
    }
}

