module u_channel_bracket(
    outer_diameter = 80,
    outer_thickness = 4,
    mounting_hole_diameter = 2,
    mounting_hole_spacing = 10
);

// Create the outer U-channel
difference() {
    cube([outer_diameter, outer_thickness, outer_thickness]);
    intersection() {
        translate([outer_diameter / 2 - outer_thickness / 2, 0, 0])
            cube([outer_thickness, outer_thickness, outer_thickness]);
        translate([outer_diameter / 2 - outer_thickness / 2, outer_diameter, 0])
            cube([outer_thickness, outer_thickness, outer_thickness]);
        translate([outer_diameter / 2 - outer_thickness / 2, 0, outer_diameter])
            cube([outer_thickness, outer_thickness, outer_thickness]);
        translate([outer_diameter / 2 - outer_thickness / 2, outer_diameter, outer_thickness])
            cube([outer_thickness, outer_thickness, outer_thickness]);
    }
}

