    u_channel_bracket(mounting_hole_diameter = 2);
}

module structural_l_bracket(size, thickness) {
    // Define the dimensions of the L-bracket
    size = size / 2; // Divide size by 2 to make it symmetric
    thickness = thickness / 2; // Divide thickness by 2 to make it symmetric

    // Draw the main body of the L-bracket
    difference() {
        cube(size * 2, center=true); // Create a larger cube as the main body
        translate([0, 0, size]) { // Translate the cube by size to adjust for the thickness
            difference() {
                cube(thickness, center=true); // Create a smaller cube for the top
                translate([0, thickness, 0]) { // Translate the smaller cube to adjust for the thickness
                    cube(size * 2 - thickness, center=true); // Create a larger cube without the top for the bottom
                }
            }
        }
    }
}

