// Define the overall size of the pipe flange
module pipe_flange(size, thickness) {
    // Define the center of the flange
    translate([size/2, size/2, 0]) {
        // Define the cylinder part of the flange
        cylinder(r=size-thickness, h=size, center=true, segments=100);

        // Define the rectangular mounting holes
        translate([0, 0, size/2+thickness]) {
            // Define the first hole
            cylinder(r=2, h=10, center=true, segments=10);
            translate([0, 10, 0]) {
                cylinder(r=2, h=10, center=true, segments=10);
            }
            translate([10, 0, 0]) {
                cylinder(r=2, h=10, center=true, segments=10);
            }
            translate([10, 10, 0]) {
                cylinder(r=2, h=10, center=true, segments=10);
            }
        }
    }
}

