module pipe_flange(
  radius = 10,  // Base radius of the pipe
  thickness = 9, // Thickness of the pipe flange
  hole_diameter = 3  // Diameter of the central through-hole
);

// Create a cylinder as the pipe body
cylinder(
  r = radius + thickness,
  h = 50,  // Height of the pipe body
  center = true,
  chamfer = 1
);

// Create the pipe flange using the difference() operation
difference() {
  cylinder(
    r = radius + thickness,
    h = 50,  // Height of the pipe body
    center = true,
    chamfer = 1
  );
  // Create the through-hole using a difference() subtraction
  difference() {
    translate([0, -hole_diameter / 2, 0]) {
      sphere(
        r = hole_diameter / 2,
        center = true
      );
    }
  };
}

module corner_gusset(size, thickness) {
    // Thick base plate
    difference() {
        sphere(r=size/2, $fn=20);
        translate([0, 0, thickness/2]) {
            cylinder(r=size/2, h=thickness, $fn=20);
        }
    }

    // Thinner extended mounting tab
    translate([0, size/2, 0]) {
        cylinder(r=thickness/2, h=size, $fn=20);
    }

    // Union to combine the thick base plate and the thinner extended mounting tab
    union() {
        difference() {
            sphere(r=size/2, $fn=20);
            translate([0, 0, thickness/2]) {
                cylinder(r=size/2, h=thickness, $fn=20);
            }
        }
        translate([0, size/2, 0]) {
            cylinder(r=thickness/2, h=size, $fn=20);
        }
    }
}

