module shaft_collar(radius, thickness, hole_diameter, hole_spacing) {
    difference() {
        cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
        translate([0, radius+thickness/2, 0]) {
            cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
            translate([0, -radius-thickness/2, 0]) {
                cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
            }
            translate([-radius-thickness/2, 0, 0]) {
                cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
            }
        }
        translate([0, 0, thickness/2]) {
            cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
        }
        translate([radius+thickness/2, 0, thickness/2]) {
            cylinder(radii=radius-thickness/2, h=2*radius+thickness, center=true);
        }
    }

    for (x=[-1, 1], y=[-1, 1]) {
        translate([x*hole_spacing, y*hole_spacing, 0]) {
            cylinder(radii=hole_diameter/2, h=2*hole_diameter, center=true);
        }
    }
}

