module rectangular_base(size, thickness) {
    // Define the primary outer edges with a 2mm chamfer
    translate([size/2 - thickness/2, size/2 - thickness/2, thickness/2])
    rotate([0, 0, 45])
    cylinder(r1=size/2 - thickness/2, r2=size/2, h=thickness);

    // Define the secondary inner edges with a 2mm chamfer
    translate([size/2 - thickness/2 + 2, size/2 - thickness/2 + 2, thickness/2])
    rotate([0, 0, -45])
    cylinder(r1=size/2 - thickness/2 - 2, r2=size/2, h=thickness);

    // Define the additional details
    translate([size/2 - thickness/2, size/2 - thickness/2, thickness/2 + 1])
    rotate([0, 0, 90])
    cylinder(r1=size/2 - thickness/2 - 1, r2=size/2, h=2);

    translate([size/2 - thickness/2 - 1, size/2 - thickness/2, thickness/2 + 1])
    rotate([0, 0, 270])
    cylinder(r1=size/2 - thickness/2 - 1, r2=size/2, h=2);
}

