            difference() {
                // Inner body with chamfer on edges
                cylinder(r=4, h=size-8, chamfer=[0, 0.5, 0.5]);
                // Base
                translate([0, 0, -thickness/2]) {
                    cylinder(r=4, h=8, chamfer=[0, 0.5, 0.5]);
                }
                // Top
                translate([0, size, -thickness/2]) {
                    cylinder(r=4, h=8, chamfer=[0, 0.5, 0.5]);
                }
                // Bottom
                translate([0, -size, -thickness/2]) {
                    cylinder(r=4, h=8, chamfer=[0, 0.5, 0.5]);
                }
            }
        }
    }
}

