module spacer(size = 20, thickness = 15) {
    // Define the cylinder
    cylinder(r = size / 2, h = size, $fn = 32);

    // Define the hexagonal recess
    hexagon_radius = thickness / 2;
    hexagon_points = [[0, 0], [hexagon_radius, -hexagon_radius], [hexagon_radius, hexagon_radius], [0, 0]];

    // Subtract the hexagonal recess
    difference() {
        cylinder(r = size / 2, h = size, $fn = 32);
        hexagon(hexagon_points, thickness / 2);
    }
}

