// Define parameterized L-bracket dimensions
module LBracket(d=92, t=6, c=2) {
    // Create the base rectangle
    translate([0, -t/2, 0]) rectangle([d, t, t]);

    // Create the legs
    translate([c, 0, 0]) cylinder(r=d/2, h=t);
    translate([-c, 0, 0]) cylinder(r=d/2, h=t);

    // Create the chamfer on the primary outer edges
    translate([c, 0, 0]) chamfer(radius=c);
    translate([-c, 0, 0]) chamfer(radius=c);
    translate([0, t/2, 0]) chamfer(radius=c);
    translate([d, t/2, 0]) chamfer(radius=c);
}

