module corner_gusset(size, thickness) {
  // Define the corner gusset
  difference() {
    // Main body with holes
    cube([size, size, thickness], center=true);

    // Top hole
    translate([size/2, size/2, 0]) {
      hole([size/2 - thickness/2, size/2 - thickness/2, thickness]);
    }

    // Bottom hole
    translate([size/2, size/2, thickness + thickness/2]) {
      hole([size/2 - thickness/2, size/2 - thickness/2, thickness]);
    }

    // Front hole
    translate([size/2, size/2, thickness + thickness/2]) {
      rotate([90, 0, 0]) {
        hole([size/2 - thickness/2, size/2 - thickness/2, thickness]);
      }
    }

    // Back hole
    translate([size/2, size/2, thickness + thickness/2]) {
      rotate([-90, 0, 0]) {
        hole([size/2 - thickness/2, size/2 - thickness/2, thickness]);
      }
    }
  }
}

