corner_gusset(55, 13);

module corner_gusset(
    size = 63,
    thickness = 12
) {
    // Create the main body of the gusset
    union() {
        // The base of the gusset
        cube([size, size, thickness]);

        // The front face of the gusset
        difference() {
            cube([size, thickness, size]);
            translate([size/2, thickness/2, 0]) cylinder(r=thickness/2, h=size, center=false);
        }

        // The back face of the gusset
        difference() {
            cube([size, thickness, size]);
            translate([-size/2, thickness/2, 0]) cylinder(r=thickness/2, h=size, center=false);
        }

        // The left face of the gusset
        difference() {
            cube([size, thickness, size]);
            translate([0, thickness/2, size/2]) cylinder(r=thickness/2, h=size, center=false);
        }

        // The right face of the gusset
        difference() {
            cube([size, thickness, size]);
            translate([0, thickness/2, -size/2]) cylinder(r=thickness/2, h=size, center=false);
        }

        // The top face of the gusset
        difference() {
            cube([size, size, thickness]);
            translate([0, size/2, 0]) cylinder(r=thickness/2, h=size, center=false);
        }

        // The bottom face of the gusset
        difference() {
            cube([size, size, thickness]);
            translate([0, -size/2, 0]) cylinder(r=thickness/2, h=size, center=false);
        }
    }
}

