module shaft_collar(size, thickness) {
  // Define the shaft collar as a union of a cylinder and holes
  cylinder(r = size / 2 - thickness / 2, h = size + thickness, center = true);
  // Add four circular mounting holes arranged in a rectangular pattern
  translate([0, 0, size / 2 - thickness / 2]) {
    cylinder(r = thickness / 2, h = size / 2, center = true);
    translate([size / 2, 0, size / 2 - thickness / 2]) {
      cylinder(r = thickness / 2, h = size / 2, center = true);
    }
    translate([0, size / 2, size / 2 - thickness / 2]) {
      cylinder(r = thickness / 2, h = size / 2, center = true);
    }
    translate([size / 2, size / 2, size / 2 - thickness / 2]) {
      cylinder(r = thickness / 2, h = size / 2, center = true);
    }
  }
}

