module structural_l_bracket(length=85, width=20, height=15, chamfer_thickness=2) {
  // Create the primary outer edges with chamfer
  cylinder(radii=[chamfer_thickness/2, length/2, height/2], height=height+2*chamfer_thickness, center=true);

  // Add the main body of the bracket
  difference() {
    cylinder(radii=[chamfer_thickness/2, length/2, height/2], height=height+2*chamfer_thickness, center=true);
    cylinder(radii=[chamfer_thickness/2, width/2, height/2], height=height+2*chamfer_thickness, center=true);
    cylinder(radii=[chamfer_thickness/2, height/2, width/2], height=height+2*chamfer_thickness, center=true);
  }

  // Create the legs of the bracket
  for (i=[-1, 1]) {
    for (j=[-1, 1]) {
      cylinder(radii=[chamfer_thickness/2, length/2, height/2], height=height+2*chamfer_thickness, center=true, translate=[i*length, j*width, -height]);
    }
  }
}

