module corner_gusset(
    size = 32,  // mm
    thickness = 8, // mm
    hole_radius = 2  // mm
) {
    // Top face
    translate([0, size/2 - thickness/2, 0]) {
        cylinder(r=thickness, h=size/2, $fn=100);
    }

    // Bottom face
    translate([0, -size/2 + thickness/2, 0]) {
        cylinder(r=thickness, h=size/2, $fn=100);
    }

    // Front face
    translate([size/2 - thickness/2, 0, 0]) {
        cylinder(r=thickness, h=size/2, $fn=100);
    }

    // Back face
    translate([-size/2 + thickness/2, 0, 0]) {
        cylinder(r=thickness, h=size/2, $fn=100);
    }

    // First circular mounting hole
    translate([thickness, hole_radius, hole_radius]) {
        cylinder(r=hole_radius, h=size/2 - thickness*2, $fn=100);
    }

    // Second circular mounting hole
    translate([-thickness, hole_radius, hole_radius]) {
        cylinder(r=hole_radius, h=size/2 - thickness*2, $fn=100);
    }

    // Third circular mounting hole
    translate([thickness, hole_radius, -hole_radius]) {
        cylinder(r=hole_radius, h=size/2 - thickness*2, $fn=100);
    }

    // Fourth circular mounting hole
    translate([-thickness, hole_radius, -hole_radius]) {
        cylinder(r=hole_radius, h=size/2 - thickness*2, $fn=100);
    }
}

