// Primary outer edges with a 2mm chamfer

module flanged_bushing(size, thickness, chamfer) {
    // Create the primary outer edges
    difference() {
        translate([-size/2, thickness/2, 0])
            cylinder(r1=size/2, r2=size/2+chamfer/2, h=thickness);

        translate([size/2, -thickness/2, 0])
            cylinder(r1=size/2, r2=size/2+chamfer/2, h=thickness);

        translate([0, size/2, thickness/2])
            cylinder(r1=size/2, r2=size/2+chamfer/2, h=thickness);

        translate([0, -size/2, thickness/2])
            cylinder(r1=size/2, r2=size/2+chamfer/2, h=thickness);
    }

    // Create the secondary outer edges
    translate([-size/2, thickness/2-0.1, 0])
        cylinder(r1=size/2, r2=size/2+chamfer/2, h=0.1);

    translate([size/2, -thickness/2-0.1, 0])
        cylinder(r1=size/2, r2=size/2+chamfer/2, h=0.1);

    translate([0, size/2, thickness/2-0.1])
        cylinder(r1=size/2, r2=size/2+chamfer/2, h=0.1);

    translate([0, -size/2, thickness/2-0.1])
