    cube([size, size, thickness]);
    translate([chamfer, chamfer, 0]) rotate([90, 0, 0]) cube([2 * chamfer, size, thickness]);
    translate([-chamfer, size - chamfer, 0]) rotate([90, 0, 0]) cube([2 * chamfer, size, thickness]);
