// Define parameters
module shaft_collar(
    overall_size = 84,
    thickness = 12,
    hole_diameter = 3,
    hole_spacing = 10,
    hole_count = 4
) {
    // Calculate dimensions
    wall_thickness = thickness / 2;
    hole_radius = hole_diameter / 2;
    hole_center = overall_size / 2 - hole_spacing * (hole_count - 1) / 2;

    // Create outer cylinder
    cylinder(
        r = overall_size / 2,
        h = overall_size,
        fn = 100,
        center = true,
        chamfer = 1
    );

    // Create inner cylinder
    cylinder(
        r = overall_size / 2 - thickness,
        h = overall_size,
        fn = 100,
        center = true,
        chamfer = 1
    );

    // Create mounting holes
    for (i = [0:hole_count-1]) {
        translate([
            hole_center - hole_spacing * (i / hole_count + 0.5) - hole_radius,
            hole_center - hole_spacing * (i / hole_count + 0.5) - hole_radius,
            0
        ]) {
            cylinder(
                r = hole_radius,
                h = thickness,
                fn = 50,
                center = true,
                chamfer = 1
            );
        }
    }
}

