    translate([2*radius, 0, thickness/2 + 2*radius]) cylinder(r=1, h=1);
    translate([2*radius, 0, thickness/2 + 4*radius]) cylinder(r=1, h=1);

    // Third hole
    translate([3*radius, 0, thickness/2]) cylinder(r=1, h=1);
    translate([3*radius, 0, thickness/2 + 2*radius]) cylinder(r=1, h=1);
    translate([3*radius, 0, thickness/2 + 4*radius]) cylinder(r=1, h=1);

    // Fourth hole
    translate([4*radius, 0, thickness/2]) cylinder(r=1, h=1);
    translate([4*radius, 0, thickness/2 + 2*radius]) cylinder(r=1, h=1);
    translate([4*radius, 0, thickness/2 + 4*radius]) cylinder(r=1, h=1);
