    hexagonal_recess(thickness, outer_diameter);
}

module hexagonal_recess(thickness, outer_diameter) {
    // Define the hexagonal recess parameters
    // Hexagon center
    h_center = outer_diameter / 2;

    // Hexagon vertices
    vertices = [
        [h_center, -thickness, 0], // Lower left
        [h_center, thickness, 0],  // Lower right
        [h_center - thickness, 0, 0],  // Top left
        [h_center + thickness, 0, 0],  // Top right
        [0, -thickness, 0],  // Center down
        [0, thickness, 0]   // Center up
    ];

    // Connect vertices to form a hexagon
    faces = [
        [0, 1, 4, 5],
        [1, 2, 5, 6],
        [2, 3, 6, 0],
        [3, 4, 7, 1],
        [4, 5, 0, 2],
        [5, 6, 1, 3]
    ];

    // Create the hexagonal recess using the faces
    difference() {
        cylinder(d=outer_diameter, h=thickness);
        hexagon(faces);
    }
}

