        translate([0, height, 0]) {
            cube([radius*2, height, thickness]);
            cylinder(radius=radius, height=thickness, center=true, endstops=true);
        }
    }

    // Draw the central through-hole
    translate([radius, height/2, thickness/2]) {
        cylinder(radius=radius-0.1, height=2*thickness, center=true, endstops=true);
    }
}

