module flanged_bushing(size, thickness, base_thick, tab_thick) {
    // Base plate with increased thickness
    translate([0, 0, base_thick / 2]) {
        cube([size, thickness, base_thick]);
    }

    // Extended mounting tab
    translate([0, 0, (size / 2) - tab_thick / 2]) {
        cube([size, thickness, tab_thick]);
    }

    // Union to combine the base plate and the tab
    union() {
        translate([0, 0, base_thick / 2 - thickness / 2]) {
            cube([size, thickness, thickness]);
        }
    }
}

