module flanged_bushing() {
    // Define the overall size of the bushing
    $fn = 72; // Number of segments for the hexagonal recess
    $s = 31; // Overall size of the bushing in mm
    $t = 8;  // Thickness of the bushing in mm

    // Define the hexagonal recess
    hexagonal_recess($s - t, $s, $fn);

    // Create the flange of the bushing
    cylinder(r1 = ($s - t) / 2, r2 = ($s - t) / 2, h = t, center = true);

    // Union the bushing with the hexagonal recess
    union() {
        cylinder(r1 = ($s - t) / 2, r2 = ($s - t) / 2, h = t, center = true);
        hexagonal_recess($s - t, $s, $fn);
    }
}

