module corner_gusset(size=34, thickness=6, hole_diameter=2) {
  // Create the main body of the corner gusset
  union() {
    // Base of the corner gusset
    translate([-size/2, -size/2, thickness/2]) box([size, size, thickness], center=true);

    // Four circular mounting holes arranged in a rectangular pattern
    rotate([90, 0, 0]) translate([0, 0, thickness/2 + hole_diameter/2]) cylinder(diameter=hole_diameter, height=2*hole_diameter, center=true);
    rotate([180, 0, 0]) translate([0, 0, thickness/2 + hole_diameter/2]) cylinder(diameter=hole_diameter, height=2*hole_diameter, center=true);
    rotate([270, 0, 0]) translate([0, 0, thickness/2 + hole_diameter/2]) cylinder(diameter=hole_diameter, height=2*hole_diameter, center=true);
    rotate([360, 0, 0]) translate([0, 0, thickness/2 + hole_diameter/2]) cylinder(diameter=hole_diameter, height=2*hole_diameter, center=true);
  }
}

