        // Top hole
        translate([0, 0, thickness/2]) {
            sphere(r=thickness/2);
        }

        // Bottom hole
        translate([0, 0, -thickness/2]) {
            sphere(r=thickness/2);
        }

        // Side holes
        translate([thickness/2, 0, 0]) {
            cylinder(r=thickness/2, h=size-2*thickness);
        }

        translate([-thickness/2, 0, 0]) {
            cylinder(r=thickness/2, h=size-2*thickness);
        }
    }
}

