// Define the pipe flange parameters
module pipe_flange(radius, outer_thickness, inner_thickness, chamfer_radius, chamfer_height, chamfer_angle) {
    // Define the pipe body
    cylinder(diameter=2 * (radius + outer_thickness), height=outer_thickness, center=true, chamfer_radius=chamfer_radius, chamfer_height=chamfer_height, chamfer_angle=chamfer_angle);

    // Define the flange
    difference() {
        cylinder(diameter=2 * (radius - inner_thickness), height=outer_thickness, center=true, chamfer_radius=chamfer_radius, chamfer_height=chamfer_height, chamfer_angle=chamfer_angle);
        cylinder(diameter=2 * (radius - inner_thickness), height=2 * chamfer_height, center=true, chamfer_radius=chamfer_radius, chamfer_height=chamfer_height, chamfer_angle=chamfer_angle);
    }
}

