module flanged_bushing(hole_diameter, hole_depth, body_diameter, body_thickness) {
    // Main body
    difference() {
        cylinder(r=body_diameter/2, h=body_thickness, center=true);
        cylinder(r=body_diameter/2, h=body_thickness*1.1, center=true);
    }

    // Flange
    difference() {
        cylinder(r=body_diameter/2, h=hole_depth, center=true);
        cylinder(r=hole_diameter/2, h=hole_depth*1.1, center=true);
    }

    // Subtract hole on Z-axis to prevent artifacts
    translate([0, 0, -hole_depth]) {
        difference() {
            cylinder(r=body_diameter/2, h=body_thickness, center=true);
            cylinder(r=body_diameter/2, h=body_thickness*1.1, center=true);
        }
    }
}

