module pipe_flange(size, thickness) {
    // Main body of the pipe flange
    cylinder(r = size/2, h = 3*size, center = false, chamfer = thickness/2);

    // Hole in the center
    translate([0, 0, thickness/2]) {
        cylinder(r = size/4, h = 3*size, center = false, chamfer = thickness/4);
    }

    // Holes around the circumference
    for (i = [0:360:360]) {
        translate([size/4*sin(i), size/4*cos(i), thickness/2]) {
            cylinder(r = size/4, h = 3*size, center = false, chamfer = thickness/4);
        }
    }
}

