module hexagon(radius, angle_start, angle_end) {
    polygon(points=[
        [radius * cos(angle_start), radius * sin(angle_start)],
        [radius * cos(angle_end), radius * sin(angle_end)],
        [radius * cos(angle_end), -radius * sin(angle_end)],
        [radius * cos(angle_start), -radius * sin(angle_start)]
    ]);
}

