module cylindricalSpacer(size, thickness, chamfer) {
    // Define the cylindrical part
    cylinder(r=size/2, h=size, center=true);

    // Calculate the chamfer radius
    chamfer_radius = chamfer / 2;

    // Calculate the distance from the center to the chamfer edge
    chamfer_distance = size - chamfer_radius;

    // Subtract the chamfer from the cylindrical part
    difference() {
        cylinder(r=size/2, h=size, center=true);
        translate([0, 0, -chamfer_distance]) cylinder(r=chamfer_radius, h=thickness, center=true);
    }
}

