    cylinder(d = size, h = thickness, center = true, chamfer = chamfer);

    // Difference to create the spacer
    difference() {
        cylinder(d = size - (2 * chamfer), h = thickness, center = true, chamfer = chamfer);
        cylinder(d = size, h = thickness, center = true, chamfer = chamfer);
    }
}

