module UChannelBracket(sizeX, sizeY, thickness) {
    // Create the base of the U-channel
    cylinder(r=0.5*thickness, h=sizeY - 2*thickness, center=true, body=true);
    translate([0, sizeY/2, 0]) cylinder(r=0.5*thickness, h=sizeX - 2*thickness, center=true, body=true);

    // Create the flanges
    translate([0, 0, thickness/2]) cylinder(r=0.5*thickness, h=sizeY - 2*thickness, center=true, body=true);
    translate([sizeX - thickness/2, 0, thickness/2]) cylinder(r=0.5*thickness, h=sizeY - 2*thickness, center=true, body=true);

    // Create the mounting holes
    translate([sizeX/4, sizeY/4, thickness]) circle(r=0.2*thickness, $fn=10);
    translate([3*sizeX/4, sizeY/4, thickness]) circle(r=0.2*thickness, $fn=10);
    translate([sizeX/4, 3*sizeY/4, thickness]) circle(r=0.2*thickness, $fn=10);
    translate([3*sizeX/4, 3*sizeY/4, thickness]) circle(r=0.2*thickness, $fn=10);
}

