    // Generate a cylindrical body
    cylinder(r=mainLength/2, h=mainLength, $fn=50);  // Spline curve for a rounded corner

    // Generate a hole in the center
    translate([0, 0, thickness/2]) hole(d=10);  // A simple square hole

    // Generate a smaller hole on the opposite side
    translate([0, 0, mainLength - thickness/2]) hole(d=5);  // A smaller hole

    // Generate a smaller hole on the top
    translate([0, thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the bottom
    translate([0, -thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the left side
    translate([-thickness/2, 0, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the right side
    translate([thickness/2, 0, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the top-left corner
    translate([-thickness/2, -thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the top-right corner
    translate([thickness/2, -thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the bottom-left corner
    translate([-thickness/2, thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole

    // Generate a smaller hole on the bottom-right corner
    translate([thickness/2, thickness/2, mainLength - thickness/2]) hole(d=3);  // A smaller hole
}

