// Define the hexagonal recess
module hex_recess(radius, thickness) {
    translate([0, radius/2, 0]) {
        difference() {
            cylinder(r=radius, h=thickness/2);
        }
        translate([0, radius, thickness/4]) {
            difference() {
                cylinder(r=radius, h=thickness/2);
            }
            translate([0, -radius, thickness/4]) {
                difference() {
                    cylinder(r=radius, h=thickness/2);
                }
            }
            translate([radius, 0, thickness/4]) {
                difference() {
                    cylinder(r=radius, h=thickness/2);
                }
            }
            translate([-radius, 0, thickness/4]) {
                difference() {
                    cylinder(r=radius, h=thickness/2);
                }
            }
        }
    }
}

