module cylindrical_spacer(size, thickness) {
  // Base cylinder
  cylinder(r = size / 2, h = size, center = true, segments = 32);

  // Hexagonal recess
  hexagon(recess_height, recess_width) {
    translate([0, size / 2, recess_height / 2]) {
      difference() {
        cylinder(r = recess_width / 2, h = recess_height, center = true, segments = 32);
        translate([recess_width, 0, recess_height / 2]) {
          cylinder(r = recess_width / 2, h = recess_height, center = true, segments = 32);
        }
        translate([recess_width, recess_width, recess_height / 2]) {
          cylinder(r = recess_width / 2, h = recess_height, center = true, segments = 32);
        }
      }
    }
  }

  // Subtract hexagonal recess from cylinder
  difference() {
    cylinder(r = size / 2, h = size, center = true, segments = 32);
    hexagon(thickness, thickness);
  }
}

