// Shaft collar with circular mounting holes
module shaftCollar(size, thickness, holesPerSide, holeDiameter) {
    // Define the main body of the shaft collar
    difference() {
        cube([size, size, thickness], center=true);
        // Add circular mounting holes
        for (i = [0:holesPerSide-1]) {
            for (j = [0:holesPerSide-1]) {
                translate([i*2*holeDiameter, j*2*holeDiameter, 0.5*thickness]) {
                    cylinder(diameter=holeDiameter, height=0.5*thickness, center=true);
                }
            }
        }
    }
}

