module shaft_collar(param = 94, t = 6, c = 2) {
    // Primary outer edges with chamfer
    difference() {
        cube([param - 2*t, 100, 100], center = [0, 0, 0]);
        union() {
            translate([t, 0, 0]) {
                cylinder(r = 5, h = 100, center = [0, 0, 0]);
            }
            translate([0, t, 0]) {
                cylinder(r = 5, h = 100, center = [0, 0, 0]);
            }
            translate([0, 0, t]) {
                cylinder(r = 5, h = 100, center = [0, 0, 0]);
            }
        }
        chamfer([param - 2*t, 100, 100], [0, 1, 0], c);
    }

    // Secondary inner edges
    translate([t, t, t]) {
        cylinder(r = 3, h = 100, center = [0, 0, 0]);
    }
    translate([0, t, t]) {
        cylinder(r = 3, h = 100, center = [0, 0, 0]);
    }
    translate([t, 0, t]) {
        cylinder(r = 3, h = 100, center = [0, 0, 0]);
    }

    // Inner body
    translate([2*t, 2*t, 2*t]) {
        cylinder(r = 2, h = 100, center = [0, 0, 0]);
    }
}

