        translate([overall_size/2, thickness/2, -overall_size/2]) cylinder(r1=overall_size/2-r/2, r2=overall_size/2, h=overall_size/2);
        translate([overall_size/2, -thickness/2, overall_size/2]) cylinder(r1=overall_size/2-r/2, r2=overall_size/2, h=overall_size/2);
        translate([overall_size/2, -thickness/2, -overall_size/2]) cylinder(r1=overall_size/2-r/2, r2=overall_size/2, h=overall_size/2);
        translate([overall_size/2, 0, overall_size/2]) cylinder(r1=overall_size/2-r/2, r2=overall_size/2, h=thickness);
    }
}

