// Define parameters
module u_channel_bracket(
    width = 20,  // mm
    height = 10,  // mm
    depth = 10,  // mm
    hole_diameter = 3,  // mm
    hole_depth = 1  // mm
) {

    // Create the main body of the bracket
    translate([0, 0, depth - hole_depth / 2])
    linear_extrude(height)
    square([width, height]);

    // Create the holes
    translate([0, 0, hole_depth / 2])
    difference() {
        square([width, height]);
        cylinder(diameter = hole_diameter, height = hole_depth);
    }

    // Ensure all subtracted hole geometries extend past the main body on the Z-axis
    translate([0, 0, hole_depth])
    linear_extrude(depth)
    square([width, height]);
}

