module circular_pipe_flange(r, t) {
    // Calculate the dimensions
    r_inner = r - t;
    r_outer = r + t;

    // Create the outer cylinder
    cylinder(r_outer, h, center=true);

    // Create the inner cylinder
    cylinder(r_inner, h, center=true);

    // Calculate the difference between the outer and inner cylinders
    difference() {
        cylinder(r_outer, h, center=true);
        cylinder(r_inner, h, center=true);
    }
}

