        translate([0, 0, thickness/2]) {
            difference() {
                cylinder(radii = [hole_diameter/2, hole_diameter/2], height = hole_depth, center = [0, 0, hole_depth/2]);
                translate([hole_diameter/2, hole_diameter/2]) {
                    cylinder(radii = [hole_diameter/2, hole_diameter/2], height = hole_depth, center = [0, 0, hole_depth/2]);
                }
