module flat_mounting_plate(size=49, thickness=14, chamfer_thickness=2) {
    // Define the main body of the plate
    linear_extrude(height=size - chamfer_thickness) {
        difference() {
            union() {
                polygon([
                    [chamfer_thickness, 0],
                    [chamfer_thickness, size],
                    [size - chamfer_thickness, size],
                    [size - chamfer_thickness, chamfer_thickness]
                ]);
                polygon([
                    [0, 0],
                    [chamfer_thickness, 0],
                    [chamfer_thickness, chamfer_thickness],
                    [0, chamfer_thickness]
                ]);
            }
            polygon([
                [0, size - chamfer_thickness],
                [size - chamfer_thickness, size - chamfer_thickness],
                [size, size - chamfer_thickness],
                [size, chamfer_thickness]
            ]);
            polygon([
                [chamfer_thickness, size - chamfer_thickness],
                [size - chamfer_thickness, size - chamfer_thickness],
                [size, size - chamfer_thickness],
                [size, chamfer_thickness]
            ]);
        }
    }
}

// Call the module with the desired dimensions
