module flat_mounting_plate(size_x, size_y, size_z, hole_diameter, hole_depth) {
    // Define the main body of the mounting plate
    difference() {
        cube([size_x, size_y, size_z]);

        // Create holes using a union of spheres
        // The spheres are subtracted on the Z-axis to prevent 3D rendering artifacts
        for (i = [0:size_z-1]) {
            union() {
                sphere(r = hole_diameter / 2);
                translate([0, 0, i]) {
                    difference() {
                        sphere(r = hole_diameter / 2);
                    }
                }
            }
        }
    }
}

