    cylinder(d = height, r = chamfer_size, h = thickness, center = [0, 0, 0], chamfer = [0, 0, -1]);

    // Define the secondary inner edges
    cylinder(d = height - 2*chamfer_size, r = thickness, h = height, center = [0, 0, 0], chamfer = [0, 0, 1]);
    cylinder(d = height - 2*chamfer_size, r = thickness, h = height, center = [0, 0, 0], chamfer = [0, 0, -1]);

    // Define the primary inner edges with chamfer
    difference() {
        cylinder(d = height - 2*chamfer_size, r = thickness, h = height, center = [0, 0, 0], chamfer = [0, 0, 1]);
        cylinder(d = height - 2*chamfer_size, r = thickness, h = height, center = [0, 0, 0], chamfer = [0, 0, -1]);
    }

    // Define the secondary outer edges with chamfer
    difference() {
        cylinder(d = height, r = chamfer_size, h = thickness, center = [0, 0, 0], chamfer = [0, 0, 1]);
        cylinder(d = height, r = chamfer_size, h = thickness, center = [0, 0, 0], chamfer = [0, 0, -1]);
    }
}

