module flat_mounting_plate(size, hex_radius, hex_height, hex_depth) {
    // Define the overall size of the flat mounting plate
    translate([0, 0, 0]) {
        // Create a rectangular base
        rect([size, size], [0, size]);

        // Create a hexagonal recess
        difference() {
            // Define the hexagon
            rotate(hex_height) {
                cube([hex_radius * 2, hex_height, hex_depth]);
            }
            // Create the recessed portion
            translate([hex_radius, hex_radius, hex_depth]) {
                cylinder(hex_radius, hex_height, hex_depth);
            }
        }

        // Create the hex nut recess
        translate([hex_radius, hex_radius, hex_depth + hex_height]) {
            // Define the hex nut
            rotate(hex_height) {
                cylinder(hex_radius, hex_height, hex_depth);
            }
            // Create the recessed portion
            translate([hex_radius, hex_radius, hex_depth + 2 * hex_height]) {
                cylinder(hex_radius, hex_height, hex_depth);
            }
        }
    }
}

