module hex_recess(size, depth) {
    // Create a hexagon recess
    // Parameters:
    // size: Radius of the hexagon
    // depth: Depth of the recess

    // Center of the hexagon
    center = [0, 0, depth];

    // Vertices of the hexagon
    v1 = [size, 0, depth];
    v2 = [size * cos(2 * M_PI / 6), size * sin(2 * M_PI / 6), depth];
    v3 = [size * cos(4 * M_PI / 6), size * sin(4 * M_PI / 6), depth];
    v4 = [size * cos(6 * M_PI / 6), size * sin(6 * M_PI / 6), depth];
    v5 = [size * cos(8 * M_PI / 6), size * sin(8 * M_PI / 6), depth];
    v6 = [size * cos(10 * M_PI / 6), size * sin(10 * M_PI / 6), depth];

    // Faces of the hexagon
    f1 = [v1, v2, v3];
    f2 = [v2, v4, v5];
    f3 = [v3, v5, v6];
    f4 = [v4, v6, v1];
    f5 = [v5, v1, v2];

    // Hexagon mesh
    hex = convex_hull(f1, f2, f3, f4, f5);
}

module cylindrical_spacer(length, thickness, hex_size, hex_depth) {
    // Create a cylindrical spacer
    // Parameters:
    // length: Length of the spacer
    // thickness: Thickness of the spacer
    // hex_size: Radius of the hexagonal recess
    // hex_depth: Depth of the hexagonal recess

    // Create the cylindrical body
    cylinder(size=length, h=thickness, center=[0, 0, 0], center_offset=[0, 0, -thickness/2]);

    // Subtract the hexagonal recess
    space = difference([
        cylinder(size=length, h=thickness, center=[0, 0, 0], center_offset=[0, 0, -thickness/2]),
        hex_recess(hex_size, hex_depth)
    ]);
}

