module project_enclosure_base(size_x, size_y, thickness) {
    // Define the overall size of the base
    size_x = size_x / 2;
    size_y = size_y / 2;

    // Calculate the dimensions of the inner rectangle
    inner_x = size_x - 2 * thickness;
    inner_y = size_y - 2 * thickness;

    // Define the through-hole size
    hole_diameter = 2 * thickness;

    // Create the base with a difference operation to subtract the through-hole
    difference() {
        // Define the outer rectangle
        rectangle(size_x * 2, size_y * 2, thickness);
        // Define the through-hole
        cylinder(hole_diameter / 2, hole_diameter / 2, thickness, $fn=100);
    }
}

