module flange(radius, thickness) {
    // Base plate
    translate([-radius/2, -radius/2, thickness/2]) {
        difference() {
            cylinder(r=radius, h=radius*2, center=true);
            cube([radius*2, radius*2, thickness]);
        }
    }

    // Mounting tab
    translate([radius/2, radius/2, radius*2+thickness/2]) {
        difference() {
            cylinder(r=radius-0.1, h=radius*2, center=true);
            cylinder(r=radius+0.1, h=radius*2, center=true);
            translate([0, 0, 0.1]) {
