module flat_mounting_plate(size, thickness) {
    // Define the size and thickness of the plate
    plate_width = size * 0.95; // 95% of the size to account for some clearance
    plate_height = size * 0.95;
    plate_depth = thickness * 1.05; // 105% of the thickness to account for some clearance

    // Define the radius of the holes
    hole_radius = plate_width * 0.10; // 10% of the plate width for the holes

    // Define the spacing between the holes
    hole_spacing = plate_width * 0.15; // 15% of the plate width for the spacing

    // Define the dimensions of the rectangular pattern of holes
    pattern_width = 2 * hole_radius + hole_spacing;
    pattern_height = 2 * hole_radius + hole_spacing;

    // Define the position of the pattern of holes
    pattern_position = plate_width / 2 - pattern_width / 2;

    // Define the center of the plate
    plate_center_x = plate_width / 2;
    plate_center_y = plate_height / 2;
    plate_center_z = plate_depth / 2;

    // Create the plate
    translate([0, 0, plate_depth / 2]) {
        translate([plate_center_x, plate_center_y, 0]) {
            cube([plate_width, plate_height, plate_depth], center = true);
        }
    }

    // Create the holes
    for (x = [0:4]) {
        for (y = [0:4]) {
            translate([pattern_position + x * pattern_width, pattern_position + y * pattern_height, 0]) {
                hole(r = hole_radius);
            }
        }
    }
}

