module shaftCollar(radius, thickness, holes) {
    // Define the outer diameter and thickness of the shaft collar
    diameter = 52; // mm
    t = thickness; // mm
    hole_radius = radius / 2; // mm

    // Create the outer cylinder for the shaft collar
    cylinder(
        radius = diameter / 2 + t / 2,
        height = diameter + t,
        center = [0, 0, diameter / 2 + t / 2],
        segments = 32
    );

    // Create the inner cylinder for the shaft collar
    cylinder(
        radius = diameter / 2 - t / 2,
        height = diameter + t,
        center = [0, 0, diameter / 2 - t / 2],
        segments = 32
    );

    // Create the rectangular pattern of circular mounting holes
    for (x = [0, 0, diameter - holes * diameter]) {
        for (y = [0, 0, diameter - holes * diameter]) {
            translate([x, y, hole_radius]) {
                cylinder(
                    radius = hole_radius,
                    height = diameter,
                    center = [0, 0, hole_radius],
                    segments = 32
                );
            }
        }
    }
}

