module hexagonal_standoff(size = 62, thickness = 11) {
  // Define the size of the hexagon
  radius = size / 2;

  // Define the length of the legs of the hexagon
  leg_length = radius * sqrt(3);

  // Define the height of the hexagon
  hex_height = 2 * radius;

  // Define the angle between two adjacent legs of the hexagon
  angle = (2 * PI) / 6;

  // Define the points of the hexagon
  points = [
    [radius, 0],
    [radius * cos(angle), radius * sin(angle)],
    [radius * cos(angle * 2), radius * sin(angle * 2)],
    [radius * cos(angle * 3), radius * sin(angle * 3)],
    [radius * cos(angle * 4), radius * sin(angle * 4)],
    [radius * cos(angle * 5), radius * sin(angle * 5)]
  ];

  // Define the faces of the hexagon
  faces = [
    [[0, 1, 2], [0, 2, 3]],
    [[0, 3, 4], [0, 4, 5]],
    [[0, 4, 1], [0, 1, 2]],
    [[1, 2, 3], [1, 3, 4]],
    [[1, 4, 5], [1, 5, 2]],
    [[2, 3, 4], [2, 4, 5]]
  ];

  // Define the difference operation to subtract the through-hole
  difference() {
    // Define the through-hole radius
    throughhole_radius = 5;

    // Define the through-hole height
    throughhole_height = 2 * throughhole_radius;

    // Define the through-hole center
    throughhole_center = [radius, 0];

    // Define the through-hole points
    throughhole_points = [
      [throughhole_radius, 0],
      [throughhole_radius * cos(angle), throughhole_radius * sin(angle)],
      [throughhole_radius * cos(angle * 2), throughhole_radius * sin(angle * 2)],
      [throughhole_radius * cos(angle * 3), throughhole_radius * sin(angle * 3)],
      [throughhole_radius * cos(angle * 4), throughhole_radius * sin(angle * 4)],
      [throughhole_radius * cos(angle * 5), throughhole_radius * sin(angle * 5)]
    ];

    // Define the through-hole faces
    throughhole_faces = [
      [[0, 1, 2], [0, 2, 3]],
      [[0, 3, 4], [0, 4, 5]],
      [[0, 4, 1], [0, 1, 2]],
      [[1, 2, 3], [1, 3, 4]],
      [[1, 4, 5], [1, 5, 2]],
      [[2, 3, 4], [2, 4, 5]]
    ];

    // Define the through-hole difference
    translate([throughhole_center[0] - throughhole_radius, throughhole_center[1] - throughhole_radius])
    cylinder(r=throughhole_radius, h=throughhole_height, center=true);

    // Define the hexagonal standoff
    polygon(points, faces);
  }
}

