module structural_l_bracket(size, thickness, chamfer) {
  size = size || 37;  // Default size is 37mm
  thickness = thickness || 4;  // Default thickness is 4mm
  chamfer = chamfer || 2;  // Default chamfer is 2mm

  // Define the L-bracket geometry
  cylinder(radius = thickness / 2, height = size, center = true, chamfer = chamfer);
  cylinder(radius = thickness / 2, height = size / 2, center = true, chamfer = chamfer);

  // Create the outer edges with a chamfer
  difference() {
    cylinder(radius = thickness / 2, height = size / 2, center = true);
    cylinder(radius = thickness / 2, height = size, center = true);
  }

  union() {
    difference() {
      cylinder(radius = thickness / 2, height = size / 2, center = true);
      cylinder(radius = thickness / 2, height = size, center = true);
    }
    difference() {
      cylinder(radius = thickness / 2, height = size / 2, center = true);
      cylinder(radius = thickness / 2, height = size, center = true);
    }
  }
}

