module cylindrical_spacer(radius, height) {
    // Calculate the dimensions of the hexagonal recess
    radius_hex = radius * 0.8;  // Adjust the radius by a factor to fit the hex nut
    side_length_hex = radius_hex * 2 * sqrt(3);  // Calculate the side length of the hexagon

    // Calculate the height of the hexagonal recess
    height_hex = height - (2 * radius_hex) * sqrt(3);  // Subtract the height of the hexagon from the overall height

    // Calculate the height of the cylindrical spacer
    height_cyl = height - height_hex;  // Subtract the height of the hexagonal recess from the overall height

    // Calculate the length of the cylindrical spacer
    length_cyl = 2 * radius + radius_hex;  // Sum the radius of the cylinder and the radius of the hexagon

    // Calculate the surface area of the hexagonal recess
    surface_area_hex = 6 * radius_hex^2 * sqrt(3);

    // Calculate the volume of the hexagonal recess
    volume_hex = (3 * sqrt(3) / 2) * radius_hex^3;

    // Calculate the surface area of the cylindrical spacer
    surface_area_cyl = 2 * 3.14159 * radius_cyl * (radius_cyl + height_cyl);

    // Calculate the volume of the cylindrical spacer
    volume_cyl = 3.14159 * radius_cyl^2 * height_cyl;

    // Calculate the total surface area of the cylindrical spacer
    total_surface_area = surface_area_hex + surface_area_cyl;

    // Calculate the total volume of the cylindrical spacer
    total_volume = volume_hex + volume_cyl;

    // Calculate the weight of the cylindrical spacer
    weight = total_volume * 0.8;  // Adjust the weight by a factor to fit the hex nut

    // Create the cylindrical spacer
    cylinder(spine=radius_cyl, height=height_cyl, color=[0.8, 0.8, 0.8]);

    // Create the hexagonal recess
    hexagon_points = [
        [0, 0, 0],
        [radius_hex, 0, 0],
        [radius_hex * 2, radius_hex * sqrt(3) / 2, 0],
        [radius_hex, radius_hex * 2 * sqrt(3) / 2, 0],
        [0, radius_hex * 2 * sqrt(3) / 2, 0],
        [-radius_hex, radius_hex * 2 * sqrt(3) / 2, 0],
        [-radius_hex * 2, radius_hex * sqrt(3) / 2, 0],
        [-radius_hex, 0, 0]
    ];

    hexagon_vertices = flatten(hexagon_points);

    hexagon_faces = [
        [0, 1, 2, 3],
        [4, 5, 6, 7],
        [0, 2, 4, 6],
        [1, 3, 5, 7]
    ];

    hexagon = polygon(hexagon_vertices, hexagon_faces, color=[0.2, 0.2, 0.2]);

    // Subtract the hexagonal recess from the cylindrical spacer
    result = difference(cylindrical_spacer, hexagon);
}

