    // Add a hole in the corner
    translate([size/2, size/2, -10]) rotate([90, 0, 0]) cylinder(hole_diameter/2, hole_diameter/2, hole_diameter, 360);

    // Ensure the hole extends past the main body on the Z-axis
    translate([size/2, size/2, size-20]) rotate([90, 0, 0]) cylinder(hole_diameter/2, hole_diameter/2, 20, 360);
}

