module flat_mounting_plate(size=28, thickness=8, chamfer=2) {
    // Define the outer edges of the mounting plate
    cylinder(r1=size/2, r2=size/2 - chamfer, h=thickness, center=true, chamfer=true);

    // Define the inner edges of the mounting plate
    cylinder(r1=size/2 - chamfer, r2=size/2 - 2*chamfer, h=thickness, center=true, chamfer=true);
}

// Call the module with the desired parameters
flat_mounting_plate();

module flanged_bushing(size, thickness) {
    // Define the flange
    cylinder(d = size - 2 * thickness, h = thickness, center = true);

    // Create a hole in the center
    difference() {
        // Base flange
        cylinder(d = size - 2 * thickness, h = thickness, center = true);

        // Central hole
        cylinder(d = thickness, h = size - 2 * thickness, center = true, extrude = -size + 2 * thickness);
    }
}

// Call the function with the desired size and thickness
flanged_bushing(size = 28, thickness = 4);

