        difference() {
            cube([size, size, size]);
            translate([0, 0, thickness]) {
                cylinder(diameter = size/2, height = thickness/2);
            }
            translate([size/2, 0, thickness/2]) {
                cylinder(diameter = size/2, height = thickness/2);
            }
            translate([0, size/2, thickness/2]) {
                cylinder(diameter = size/2, height = thickness/2);
            }
            translate([size/2, size/2, thickness/2]) {
                cylinder(diameter = size/2, height = thickness/2);
            }
        }
    }
}

