module structural_l_bracket(hole_d, hole_d2, hole_d3) {
    // Main body
    union() {
        translate([0, 0, 15]) cube([66, 66, 15]);
        translate([0, 0, 15]) cylinder(r=15, h=15, $fn=20); // Bottom cap
        translate([0, 0, 15]) cylinder(r=15, h=15, $fn=20); // Top cap
    }

    // Subtracted holes
    difference() {
        translate([0, 0, 15 + 15]) cylinder(r=hole_d, h=66, $fn=20); // Bottom hole
        translate([0, 0, 15 + 15]) cylinder(r=hole_d2, h=66, $fn=20); // Middle hole
        translate([0, 0, 15 + 15]) cylinder(r=hole_d3, h=66, $fn=20); // Top hole
    }
}

