        cylinder(h=height, r=radius, $fn=100);
        translate([0, height/2, 0]) rotate([90, 0, 0]) cylinder(h=thickness, r=radius/2, $fn=100);
        translate([0, -height/2, 0]) rotate([90, 0, 0]) cylinder(h=thickness, r=radius/2, $fn=100);
        translate([radius, 0, 0]) rotate([90, 0, 0]) cylinder(h=thickness, r=radius/2, $fn=100);
    }
}

