module LBracket(
    size = [56, 24, 3],
    chamfer = 2
) {
    // Define the primary structure of the L-bracket
    difference() {
        // Base part of the bracket
        difference() {
            translate([0, 0, size[2]])
                cube(size[0], size[1], size[2]);

            // Secondary part of the bracket
            translate([size[0] / 2, size[1] / 2, size[2]])
                cube(size[0] / 2, size[1] / 2, size[2]);

            // Primary outer edges
            translate([0, 0, size[2]])
                cube([chamfer, size[1], size[2]]);
            translate([size[0], 0, size[2]])
                cube([chamfer, size[1], size[2]]);
            translate([size[0], size[1], size[2]])
                cube([size[0], size[1], chamfer]);
            translate([0, size[1], size[2]])
                cube([size[0], chamfer, size[2]]);
            translate([size[0], size[1], size[2]])
                cube([size[0], size[1], size[2]]);
        }
    }
}

