module rectangular_project_enclosure_base(
    length = 37,
    width = 37,
    thickness = 9,
    hole_diameter = 2,
    hole_spacing = 20
) {
    difference() {
        cube([length, width, thickness]);

        translate([0, 0, thickness / 2 + hole_spacing / 2]) rotate([90, 0, 0]) {
            circular_hole(hole_diameter);
        }

        translate([length - hole_spacing, 0, thickness / 2 + hole_spacing / 2]) rotate([90, 0, 0]) {
            circular_hole(hole_diameter);
        }

        translate([length / 2 - hole_spacing, 0, thickness / 2 + hole_spacing / 2]) rotate([90, 0, 0]) {
            circular_hole(hole_diameter);
        }

        translate([0, width - hole_spacing, thickness / 2 + hole_spacing / 2]) rotate([90, 0, 0]) {
            circular_hole(hole_diameter);
        }
    }
