module structural_l_bracket(
    thickness = 11mm,
    overall_length = 63mm
) {
    // Define the dimensions of the L-bracket
    module l_bracket_base(
        length = overall_length - 2*thickness,
        width = 2*thickness,
        height = thickness
    ) {
        // Base of the L-bracket
        difference() {
            cube([length, width, height]);
        }
    }

    module hex_recess(
        radius = 5mm,
        height = 2*thickness
    ) {
        // Hexagonal recess
        difference() {
            cylinder(r = radius, h = height, start = [0, 0, 0], end = [0, 0, height]);
            translate([0, 0, height / 2]) {
                cylinder(r = radius, h = height / 2, start = [0, 0, height / 4], end = [0, 0, 3*height / 4]);
            }
        }
    }

    // Combine the base and the recess
    difference() {
        l_bracket_base();
        hex_recess();
    }
}

