structural_l_bracket();

module pipe_flange(radius, thickness, holes=4, hole_diameter=5mm, hole_distance=10mm) {
    // Define the outer circle of the pipe flange
    cylinder(r=radius+thickness/2, h=radius*2+thickness/2, center=true, chamfer=top, chamfer_length=thickness/4);

    // Define the inner circle of the pipe flange
    cylinder(r=radius-thickness/2, h=radius*2+thickness/2, center=true, chamfer=top, chamfer_length=thickness/4);

    // Define the rectangular pattern of mounting holes
    for (i = [0:holes-1]) {
        for (j = [0:holes-1]) {
            translate([i*hole_distance, j*hole_distance, 0]) {
                cylinder(r=hole_diameter/2, h=thickness, center=true, chamfer=top, chamfer_length=thickness/4);
            }
        }
    }
}

// Call the module with the desired parameters
pipe_flange(20mm, 7mm);

module base_project(overall_size = 63, thickness = 8, mounting_hole_diameter = 3, mounting_hole_spacing = 10) {
    // Top part of the base
    cylinder(r = overall_size / 2, h = thickness, center = true, chamfer = 1);

    // Bottom part of the base
    translate([0, 0, thickness])
    cylinder(r = overall_size / 2, h = thickness, center = true, chamfer = 1);

    // Left side of the base
    translate([-overall_size / 2, 0, 0])
    cylinder(r = overall_size / 2, h = overall_size + 2 * thickness, center = true, chamfer = 1);

    // Right side of the base
    translate([overall_size / 2, 0, 0])
    cylinder(r = overall_size / 2, h = overall_size + 2 * thickness, center = true, chamfer = 1);

    // Center mount hole
    translate([0, 0, overall_size / 2 - mounting_hole_diameter / 2])
    cylinder(r = mounting_hole_diameter / 2, h = thickness, center = true, chamfer = 1);

    // Left mounting hole
    translate([-overall_size / 2 + mounting_hole_spacing, 0, overall_size / 2 - mounting_hole_diameter / 2])
    cylinder(r = mounting_hole_diameter / 2, h = thickness, center = true, chamfer = 1);

    // Right mounting hole
    translate([overall_size / 2 - mounting_hole_spacing, 0, overall_size / 2 - mounting_hole_diameter / 2])
    cylinder(r = mounting_hole_diameter / 2, h = thickness, center = true, chamfer = 1);

    // Front mounting hole
    translate([0, 0, overall_size / 2 - mounting_hole_diameter / 2])
    cylinder(r = mounting_hole_diameter / 2, h = thickness, center = true, chamfer = 1);

    // Back mounting hole
    translate([0, 0, overall_size / 2 + thickness + mounting_hole_diameter / 2])
    cylinder(r = mounting_hole_diameter / 2, h = thickness, center = true, chamfer = 1);
}

base_project();

