module pipe_flange(radius, thickness) {
    // Outer circle
    difference() {
        cylinder(r = radius + thickness/2, h = 2*thickness);
        cylinder(r = radius - thickness/2, h = 2*thickness);
    }

    // Central through-hole
    translate([0, 0, thickness])
    cylinder(r = thickness/2, h = radius + thickness/2);
}

