module shaft_collar(radius, height) {
    // Define the main body shape
    cylinder(diameter=radius*2, height=height, center=true, holes=true);

    // Subtract the hole geometries
    difference() {
        // Remove the outer hole
        union() {
            cylinder(diameter=radius*2-2, height=height, center=true, holes=true);
            // Remove the inner hole
            cylinder(diameter=radius*2-4, height=height, center=true, holes=true);
        }
        // Ensure all subtracted hole geometries extend past the main body on the Z-axis
        translate([0, 0, 0]) {
            cylinder(diameter=radius*2-8, height=2*radius, center=true, holes=true);
        }
    }
}

// Example usage:
shaft_collar(radius=45, height=80);

