module cylindricalSpacer(radius, thickness, holes, holeSpacing) {
    // Create the cylindrical spacer
    cylinder(r = radius + thickness/2, h = 70 + thickness/2);

    // Calculate hole radius
    holeRadius = radius - thickness;

    // Create holes
    difference() {
        // First hole
        translate([0, 0, thickness/2]) cylinder(r = holeRadius, h = 70 + thickness/2);
        // Second hole
        translate([holeSpacing, 0, thickness/2]) cylinder(r = holeRadius, h = 70 + thickness/2);
        // Third hole
        translate([holeSpacing * 2, 0, thickness/2]) cylinder(r = holeRadius, h = 70 + thickness/2);
        // Fourth hole
        translate([holeSpacing * 3, 0, thickness/2]) cylinder(r = holeRadius, h = 70 + thickness/2);
    }
}

