module corner_gusset(size = 63, thickness = 12, chamfer = 2) {
    // Calculate dimensions
    outer_radius = size / 2 - thickness / 2;
    inner_radius = outer_radius - chamfer;

    // Define the geometry
    cylinder(h = thickness, r1 = inner_radius, r2 = outer_radius);
    difference() {
        cylinder(h = thickness, r1 = inner_radius, r2 = outer_radius);
        translate([0, 0, thickness / 2]) {
            cylinder(h = thickness, r1 = inner_radius, r2 = inner_radius);
        }
    }
}

