module flanged_bushing(radius, thickness) {
    // Main body of the flanged bushing
    difference() {
        cylinder(r=radius, h=thickness, center=true);
        circle(d=radius, r=radius-1);
        circle(d=radius, r=radius+1);
        circle(d=radius-2, r=radius-2);
        circle(d=radius-2, r=radius-2);
    }

    // Hexagonal recess for capturing a standard metric hex nut
    difference() {
        cylinder(r=radius-3, h=thickness-4, center=true);
        polygon(points=[[radius-4, thickness-4], [radius-4, thickness-5], [radius-3, thickness-5], [radius-3, thickness-4]]);
    }
}

