// Create the flange bushing
module flange_bushing(
    diameter = 43,
    thickness = 14,
    chamfer_size = 2
) {
    // Create the primary outer edges with chamfer
    linear_extrude(height = chamfer_size, center = true) {
        circle(diameter - chamfer_size);
    }

    // Create the secondary outer edges with chamfer
    linear_extrude(height = chamfer_size, center = true) {
        circle(diameter + chamfer_size);
    }

    // Create the main body with thickness
    difference() {
        cylinder(radii = diameter / 2, height = thickness);
        linear_extrude(height = -thickness, center = true) {
            circle(diameter - thickness);
        }
    }

    // Create the end cap
    cylinder(radii = diameter / 2, height = chamfer_size, center = true);
}

