module hexagonal_standoff(size, thickness) {
    // Hexagonal standoff
    // size: Overall size of the standoff
    // thickness: Thickness of the standoff

    // Main body
    difference() {
        cube([size, size, thickness]);
        // Top hole
        translate([0, 0, thickness / 2]) cube([size / 2, size / 2, thickness / 2]);
        // Bottom hole
        translate([size / 2, size / 2, thickness / 2]) cube([size / 2, size / 2, thickness / 2]);
        // Side holes
        translate([size / 4, 0, thickness / 2]) cube([size / 4, size / 2, thickness / 2]);
        translate([3 * size / 4, 0, thickness / 2]) cube([size / 4, size / 2, thickness / 2]);
        translate([0, size / 4, thickness / 2]) cube([size / 2, size / 4, thickness / 2]);
        translate([0, 3 * size / 4, thickness / 2]) cube([size / 2, size / 4, thickness / 2]);
    }

    // Subtracted hole
    translate([size / 4, size / 4, thickness / 2]) cube([size / 4, size / 4, thickness / 2]);
}

