// Define the overall size and thickness
module shaft_collar(radius, height, thickness) {
    // Calculate the diameter of the shaft
    diameter = 2 * radius;

    // Create a cylindrical part with the given radius and height
    cylinder(diameter, height, center = true);

    // Create a rectangular pattern of circular mounting holes
    // Each hole has a diameter of 2mm and is centered within the cylindrical part
    translate([0, height/2 - thickness/2, 0]) {
        for (i = [1:4]) {
            translate([i*radius - diameter/2, 0, 0]) {
                cylinder(diameter, 2, center = true);
            }
        }
    }
}

