module flanged_bushing(size, thickness, hex_radius) {
    // Create the overall flange
    difference() {
        cylinder(d=size, h=thickness, center=true);
        difference() {
            cylinder(d=size-1, h=1, center=true);
            sphere(r=thickness/2, center=true);
        }
    }

    // Create the hexagonal recess
    union() {
        // Centered hexagon
        translate([0, 0, 1]) {
            cylinder(d=hex_radius, h=thickness-2, center=true);
        }
        // Radial hexagon
        translate([0, 0, 1]) {
            cylinder(d=hex_radius/2, h=thickness-2, center=true);
            difference() {
                cylinder(d=hex_radius, h=1, center=true);
                sphere(r=thickness/2-1, center=true);
            }
        }
        // Hexagonal recess (inside)
        translate([0, 0, 1]) {
            cylinder(d=hex_radius/2, h=thickness-4, center=true);
