                cylinder(r=radius, h=thickness, $fn=50);
            }
            // Define the secondary outer edge of the pipe body
            translate([thickness/2, thickness/2, -thickness]) {
                cylinder(r=radius, h=thickness, $fn=50);
            }
        }

        // Define the chamfer on the primary outer edges
        translate([thickness/2, thickness/2, 0]) {
            difference() {
                cylinder(r=radius-chamfer_radius, h=thickness, $fn=50);
                cylinder(r=radius+chamfer_radius, h=thickness, $fn=50);
            }
        }
        translate([thickness/2, thickness/2, -thickness]) {
            difference() {
                cylinder(r=radius-chamfer_radius, h=thickness, $fn=50);
                cylinder(r=radius+chamfer_radius, h=thickness, $fn=50);
            }
        }
    }
}

