    module HexRecess(radius = thickness / 4, height = 2 * thickness) {
        polygon([radius, radius - height, radius - height / 2, radius, radius - height / 2, radius - height / 4]);
    }

    // Main body of the L-bracket
    intersection() {
        difference() {
            // Top part of the L-bracket
            translate([0, 0, thickness / 2]) {
                rotate([90, 0, 0]) {
                    cylinder(r = length / 2, h = thickness / 2, $fn = 50);
                }
            }

            // Bottom part of the L-bracket
            translate([0, 0, -thickness / 2]) {
                rotate([90, 0, 0]) {
                    cylinder(r = length / 2, h = thickness / 2, $fn = 50);
                }
            }

            // Hexagonal recess
            translate([0, length / 2, -thickness / 2]) {
                HexRecess(radius, height);
            }

            // Hexagonal recess in the other direction
            translate([0, -length / 2, -thickness / 2]) {
                HexRecess(radius, height);
            }
        }
    }
}

