        cylinder(r=radius+thickness/2, h=58, center=true);

        // Create the inner cylinder
        cylinder(r=radius-thickness/2, h=58, center=true);

        // Create the mounting holes
        for (i=range(numHoles)) {
            // Position the holes in a rectangular pattern
            translate([i*spacing, 0, 0]) {
                sphere(r=holeSize/2, center=true);
            }
        }
    }
}

