module u_channel_bracket(
    body_diameter = 24,
    body_thickness = 6,
    hole_diameter = 3,
    hole_depth = 1,
    screw_thread_diameter = 0.8,
    screw_thread_pitch = 0.25,
    screw_thread_length = 5,
    screw_thread_magnitude = 1
) {
    // Body
    difference() {
        cube([body_diameter, body_diameter, body_thickness]);
        translate([0, 0, body_thickness]) {
            cylinder(d = body_thickness - hole_depth, h = hole_depth, r = hole_diameter / 2);
        }
    }

    // Hole
    translate([0, 0, body_thickness + hole_diameter / 2]) {
        cylinder(d = hole_diameter, h = hole_depth, r = hole_diameter / 2);
    }

    // Screw thread
    translate([0, 0, body_thickness + hole_diameter / 2]) {
        cylinder(d = hole_diameter, h = screw_thread_length, r = hole_diameter / 2);
        translate([0, screw_thread_length / 2, 0]) {
            cylinder(d = screw_thread_diameter, h = screw_thread_pitch * screw_thread_magnitude, r = hole_diameter / 2);
        }
    }
}

