// Define parameters for the project enclosure base
module rectangular_base(length, width, thickness) {
    // Define the size of the rectangular base
    size = [length, width];

    // Calculate the center of the base
    center = size / 2;

    // Define the dimensions of the circular mounting holes
    hole_diameter = 5; // Adjust the diameter as needed
    hole_spacing = 20; // Adjust the spacing as needed

    // Define the position of the first hole
    hole_position = [center[0] - hole_spacing, center[1] + hole_spacing];

    // Create the first circular mounting hole
    difference() {
        sphere(r=hole_diameter / 2);
        translate(hole_position) sphere(r=hole_diameter / 2);
    }

    // Create the second circular mounting hole
    translate([center[0] + hole_spacing, center[1] + hole_spacing]) sphere(r=hole_diameter / 2);

    // Create the third circular mounting hole
    translate([center[0] - hole_spacing, center[1] - hole_spacing]) sphere(r=hole_diameter / 2);

    // Create the fourth circular mounting hole
    translate([center[0] + hole_spacing, center[1] - hole_spacing]) sphere(r=hole_diameter / 2);
}

