        // Outer ring with hex recess
        translate([0, 0, -hex_depth])
            cylinder(r=outer_radius, h=outer_depth, center=true);

        // Inner ring with hex recess
        translate([0, 0, 0])
            cylinder(r=inner_radius, h=inner_depth, center=true);
    }

    // Outer bushing
