            cylinder(r=outer_radius, h=outer_depth, center=true);

        // Outer wall
        translate([0, 0, 0])
            cylinder(r=outer_radius, h=outer_depth, center=true);
    }

    // Inner bushing
    difference() {
        // Hexagonal recess
        translate([0, 0, -hex_depth])
            cylinder(r=inner_radius, h=outer_depth, center=true);

