module shaft_collar(size, thickness) {
    // Calculate dimensions
    radius = size / 2;
    hole_radius = radius - thickness / 2;
    hole_distance = hole_radius * 2;

    // Create the shaft collar
    cylinder(center=[0, 0, 0], radius=radius, height=2*thickness);

    // Add circular mounting holes
    for (i=[0, 1], j=[0, 1]) {
        translate([hole_distance * i, hole_distance * j, -thickness / 2]) {
            cylinder(center=[0, 0, 0], radius=hole_radius, height=2*thickness);
        }
    }
}

