module shaft_collar(size, thickness, hole_diameter, hole_distance) {
    // Define the overall size of the shaft collar
    size = size + 2 * thickness; // Add twice the thickness for both sides of the collar

    // Create a rectangular body for the shaft collar
    cylinder(size=size - thickness, diameter=thickness, center=true, holes=hole_diameter / 2, holes_distance=hole_distance);

    // Add four circular mounting holes arranged in a rectangular pattern
    translate([thickness, thickness, thickness]) {
        cylinder(diameter=hole_diameter, height=hole_distance * 2, center=true);
        translate([thickness * 2, thickness, thickness]) {
            cylinder(diameter=hole_diameter, height=hole_distance * 2, center=true);
        }
        translate([thickness, thickness * 2, thickness]) {
            cylinder(diameter=hole_diameter, height=hole_distance * 2, center=true);
        }
        translate([thickness * 2, thickness * 2, thickness]) {
            cylinder(diameter=hole_diameter, height=hole_distance * 2, center=true);
        }
    }
}

