module spacer(r, h, t) {
    // Define the main body of the spacer
    cylinder(d=2*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);

    // Define the holes
    difference() {
        // First hole
        cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);

        // Second hole
        cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);

        // Third hole
        cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);
    }

    // Ensure the holes extend past the main body on the Z-axis
    translate([0, 0, -t]) {
        difference() {
            // First hole
            cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);

            // Second hole
            cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);

            // Third hole
            cylinder(d=0.5*r, h=h, center=true, chamfer=true, chamfer_radius=r/10);
        }
    }
}

