// Hexagonal standoff parameterized by size and thickness
module hexagonal_standoff(size, thickness) {
    // Hexagon vertices
    vertex(0, size / 2, 0);
    vertex(size / 2, size / 2, thickness);
    vertex(size / 2, -size / 2, thickness);
    vertex(-size / 2, -size / 2, thickness);
    vertex(-size / 2, size / 2, thickness);
    vertex(-size / 2, size / 2, 0);

    // Hexagon edges
    edge([0, size / 2, 0], [size / 2, size / 2, thickness]);
    edge([size / 2, size / 2, thickness], [size / 2, -size / 2, thickness]);
    edge([size / 2, -size / 2, thickness], [-size / 2, -size / 2, thickness]);
    edge([-size / 2, -size / 2, thickness], [-size / 2, size / 2, thickness]);
    edge([-size / 2, size / 2, thickness], [-size / 2, size / 2, 0]);
    edge([-size / 2, size / 2, 0], [0, size / 2, 0]);

    // Hexagonal recess
    difference() {
        cube([size, size, thickness], center=true);
        hexagon(size / 2, center=true);
    }
}

