// Parameterized shaft collar
module shaft_collar(
    outer_diameter = 56mm,
    inner_diameter = 32mm, // Assuming the inner diameter is 32mm for simplicity
    thickness = 14mm
) {

    // Thick base plate
    cylinder(
        radius = outer_diameter/2 + thickness/2,
        height = 2 * thickness,
        center = true,
        resolution = 32
    );

    // Thin extended mounting tab
    cylinder(
        radius = inner_diameter/2 + thickness/2,
        height = thickness/2,
        center = true,
        resolution = 32
    );

    // Combine the base plate and the mounting tab
    union() {
        cylinder(
            radius = outer_diameter/2 + thickness/2,
            height = 2 * thickness,
            center = true,
            resolution = 32
        );
        cylinder(
            radius = inner_diameter/2 + thickness/2,
            height = thickness/2,
            center = true,
            resolution = 32
        );
    }
}

// Call the function with parameters
shaft_collar(outer_diameter=56mm, inner_diameter=32mm, thickness=14mm);

module cylindrical_spacer(r, t) {
    // Create the cylindrical part
    cylinder(r=r, h=97-r-t, center=false);

    // Create the through-hole
    difference() {
        cylinder(r=r, h=5, center=false);
        cylinder(r=r-5, h=97-r-t-5, center=false);
    }
}

