module bushing(parametric_size=22, parametric_thickness=6) {
  // Define the outer cylinder of the bushing
  cylinder(radius=parametric_size/2, height=parametric_thickness);

  // Define the hexagonal recess
  hexagonal_recess(radius=parametric_size/4, height=parametric_thickness);

  // Subtract the hexagonal recess from the outer cylinder
  difference() {
    cylinder(radius=parametric_size/2, height=parametric_thickness);
    hexagonal_recess(radius=parametric_size/4, height=parametric_thickness);
  }
}

