bushing(parametric_size=22, parametric_thickness=6);

// Shaft collar with parameterized dimensions
module shaft_collar(
  diameter = 41, // Overall diameter in mm
  thickness = 12  // Thickness in mm
) {
  // Main body of the collar
  cube([diameter/2, diameter/2, thickness]);

  // Subtracted holes
  difference() {
    // Outer hole
    cylinder(diameter/4, thickness/2, diameter/2, $fn=32);

    // Inner hole
    cylinder(diameter/4, thickness/4, diameter/4, $fn=32);
  }
}

