module base_project(size=59mm, thickness=13mm) {
  // Main body of the project enclosure base
  translate([0, 0, thickness / 2 - 1.5]) {
    difference() {
      // Main body dimensions
      cube([size, size, thickness], center=true);

      // Primary outer edges chamfer
      translate([size / 2, size / 2, thickness / 2]) {
        difference() {
          // Create four rectangular bodies with chamfers
          cube([thickness, size, thickness], center=true);
          translate([0, thickness, 0]) {
            translate([thickness / 2, size / 2, 0]) {
              translate([0, 0, thickness / 2]) {
                translate([thickness / 2, 0, thickness / 2]) {
                  difference() {
                    cube([thickness / 2, thickness, thickness / 2], center=true);
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

base_project();

module hex_recess(radius, depth) {
    hull(
        [radius, radius, 0], [radius, 0, depth],
        [0, -radius, depth], [0, radius, depth],
        [radius, radius, depth], [radius, radius, 0]
    );
}

module spacer(radius, thickness) {
    // Hex recess size
    hex_size = 11.5; // mm
    hex_depth = 6; // mm

    // Hex recess
    hex_recess(hex_size, hex_depth);

    // Cylindrical spacer
    cylinder(r=radius, h=thickness);
}

// Example usage
spacer(49, 6);

module rectangular_project_enclosure_base(
    overall_size_x = 98mm,
    overall_size_y = 98mm,
    thickness = 5mm,
    chamfer_size = 2mm
) {
    // Calculate dimensions with chamfer
    chamfered_x = overall_size_x - 2 * chamfer_size;
    chamfered_y = overall_size_y - 2 * chamfer_size;

    // Construct the base with chamfer
    difference() {
        // Create the base without chamfer
        cube([overall_size_x, overall_size_y, thickness]);

        // Chamfer the edges of the base
        cylinder(r=chamfer_size, h=overall_size_z, start=chamfer_size, end=chamfered_x);
        cylinder(r=chamfer_size, h=overall_size_z, start=chamfer_size, end=chamfered_y);
        cylinder(r=chamfer_size, h=thickness, start=0, end=chamfer_size);
        cylinder(r=chamfer_size, h=thickness, start=overall_size_x - chamfer_size, end=overall_size_x);
        cylinder(r=chamfer_size, h=thickness, start=overall_size_y - chamfer_size, end=overall_size_y);
    }
}

// Example usage
rectangular_project_enclosure_base();

module structural_l_bracket(size=97, thickness=9, hole_diameter=3.5) {
  // Define the L-bracket shape
  translate([0, 0, -thickness/2]) {
    difference() {
      translate([size/2, 0, 0]) {
        linear_extrude(size/2) {
          square([size, thickness], join=false);
        }
      }
      translate([-size/2, 0, 0]) {
        linear_extrude(size/2) {
          square([size, thickness], join=false);
        }
      }
    }
  }

  // Define the holes
  translate([0, 0, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
  translate([size/2, 0, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
  translate([-size/2, 0, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
  translate([0, size/2, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
  translate([size/2, size/2, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
  translate([-size/2, size/2, thickness/2 + hole_diameter/2]) {
    cylinder(hole_diameter, thickness, $fn=100);
  }
}

// Call the module with the specified parameters
structural_l_bracket();

