    // Define the primary outer edge of the shaft collar
    cylinder(d = size - 2 * chamfer, h = thickness, center = true);

    // Chamfer the primary outer edges
    difference() {
        cylinder(d = size - 2 * chamfer, h = thickness, center = true);
        cylinder(d = size - 2 * chamfer - chamfer, h = thickness, center = true);
