// Hexagonal standoff
// Parameters:
// - base_plate_thickness: Base plate thickness (mm)
// - mounting_tab_thickness: Mounting tab thickness (mm)
// - standoff_length: Standoff length (mm)

module hexagonal_standoff(base_plate_thickness = 8, mounting_tab_thickness = 4, standoff_length = 78) {
    // Base plate
    difference() {
        cube([standoff_length, standoff_length, base_plate_thickness]);
        translate([standoff_length / 2, standoff_length / 2, 0]) {
            hexagon(standoff_length);
        }
    }

    // Mounting tab
    translate([standoff_length / 2, standoff_length / 2 + base_plate_thickness, standoff_length - mounting_tab_thickness]) {
        hexagon(standoff_length - mounting_tab_thickness);
    }
}

