        cylinder(r = r + t, h = h + 2 * t);
        cylinder(r = r - t, h = h - 2 * t);
        translate([0, 0, t]) cylinder(r = r + t, h = h);
        translate([0, 0, -t]) cylinder(r = r - t, h = h);
    }
}

