module flat_mount_plate(size, thickness) {
    cylinder(d=size/2, h=thickness, center=true);
    translate([0, size/2, thickness/2]) rotate([90, 0, 0]) cylinder(d=size/2, h=thickness, center=true);
    translate([0, -size/2, thickness/2]) rotate([90, 0, 0]) cylinder(d=size/2, h=thickness, center=true);
    translate([size/2, 0, thickness/2]) rotate([90, 0, 0]) cylinder(d=size/2, h=thickness, center=true);
    translate([-size/2, 0, thickness/2]) rotate([90, 0, 0]) cylinder(d=size/2, h=thickness, center=true);
}

