module u_channel_bracket(size = [53, 5, 5], holes = 4) {
    // Define the base of the bracket
    linear_extrude(height = size[2]) {
        cube(size);
    }

    // Define the mounting holes
    for (i = [0:holes-1]) {
        // Calculate the position of the hole
        translate([size[0]/2, size[1]/2 + i*(size[1]-holes[i]/2)/holes, size[2]]) {
            cylinder(r = size[1]/2, h = holes[i]/2, center = true);
        }
    }
}

