module flat_mounting_plate(size, thickness) {
    // Calculate the dimensions for the mounting plate
    x_size = size[0];
    y_size = size[1];
    z_size = thickness;

    // Create the mounting plate with a hole
    difference() {
        // Create the base of the mounting plate
        cube([x_size, y_size, z_size], center = [true, true, true]);

        // Create the central through-hole
        cylinder(h = z_size / 2, r = z_size / 4, center = [true, true, true]);
    }
}

