// Define the dimensions of the bracket
module u_channel_bracket(size = 36, hex_radius = 10, hex_depth = 5, hex_offset = 2, hex_height = 5) {
    // Define the hexagonal recess
    difference() {
        // Create the hexagonal recess
        hex(hex_radius, hex_depth, hex_offset, hex_height);

        // Define the U-channel section
        union() {
            // Create the bottom U-channel section
            linear_extrude(hex_height) {
                polygon([
                    [0, size],
                    [size/2, size],
                    [size/2, hex_depth],
                    [0, hex_depth]
                ]);
            };

            // Create the top U-channel section
            linear_extrude(hex_height) {
                polygon([
                    [0, size],
                    [size/2, size],
                    [size/2, -hex_depth],
                    [0, -hex_depth]
                ]);
            };
        };
    };
};

