module flanged_bushing(radius, thickness, hole_diameter, hole_spacing, flange_width, flange_height) {
    // Define the main body
    difference() {
        cylinder(h=thickness, r=radius);
        // Add flange on the Z-axis to prevent artifacts
        rotate([0, 0, 90]) {
            cylinder(h=flange_height, r=radius);
        }
    }
    // Define the holes
    translate([0, 0, thickness + flange_height]) {
        difference() {
            cylinder(h=hole_diameter, r=radius);
            // Add holes to the Z-axis to prevent artifacts
            rotate([0, 0, 90]) {
                cylinder(h=hole_diameter, r=radius);
            }
        }
    }
}

