module flanged_bushing(
    hole_diameter = 2.0,
    hole_distance = 5.0,
    hole_spacing = 2.0,
    overall_length = 39.0,
    overall_width = 4.0
) {
    // Define the flange
    difference() {
        // Create a rectangular prism for the flange
        difference() {
            cylinder(r=0.5, h=overall_length, center=true);
            cylinder(r=0.5, h=overall_width, center=true);
        }
        // Cut out the circular holes
        translate([hole_distance/2, overall_width/2, 0]) {
            difference() {
                cylinder(r=hole_diameter/2, h=overall_length, center=true);
                cylinder(r=hole_diameter/2, h=overall_width, center=true);
            }
        }
        translate([overall_length-hole_distance/2, overall_width/2, 0]) {
            difference() {
                cylinder(r=hole_diameter/2, h=overall_length, center=true);
                cylinder(r=hole_diameter/2, h=overall_width, center=true);
            }
        }
        translate([overall_length-hole_distance/2, overall_width-hole_distance/2, 0]) {
            difference() {
                cylinder(r=hole_diameter/2, h=overall_length, center=true);
                cylinder(r=hole_diameter/2, h=overall_width, center=true);
            }
        }
        translate([overall_length/2, overall_width-hole_distance/2, 0]) {
            difference() {
                cylinder(r=hole_diameter/2, h=overall_length, center=true);
                cylinder(r=hole_diameter/2, h=overall_width, center=true);
            }
        }
    }
}

