// Define the parameters for the corner gusset
module corner_gusset(size, thickness) {
    // Define the main body of the corner gusset
    cube(size - 2 * thickness, size - 2 * thickness, thickness, center=true);

    // Define the holes in the corner gusset
    difference() {
        // Define the hole on the left side
        cube(size - 4 * thickness, size - 4 * thickness, 4 * thickness, center=true);

        // Define the hole on the right side
        cube(size - 4 * thickness, size - 4 * thickness, 4 * thickness, center=true);

        // Define the hole on the top side
        cube(size - 4 * thickness, 4 * thickness, size - 4 * thickness, center=true);

        // Define the hole on the bottom side
        cube(size - 4 * thickness, size - 4 * thickness, 4 * thickness, center=true);
    }

    // Define the subtracted hole geometry to extend past the main body on the Z-axis
    difference() {
        // Define the hole on the left side
        cube(size - 6 * thickness, size - 6 * thickness, 6 * thickness, center=true);

        // Define the hole on the right side
        cube(size - 6 * thickness, size - 6 * thickness, 6 * thickness, center=true);

        // Define the hole on the top side
        cube(size - 6 * thickness, 6 * thickness, size - 6 * thickness, center=true);

        // Define the hole on the bottom side
        cube(size - 6 * thickness, size - 6 * thickness, 6 * thickness, center=true);
    }
}

