module u_channel_bracket(size, thickness) {
    // Define the basic dimensions of the U-channel
    module u_channel(size) {
        difference() {
            cube([size, size, thickness]);
            translate([0, 0, thickness / 2]) cube([size, size, thickness / 2]);
            translate([size / 2, 0, 0]) cube([size / 2, size, thickness / 2]);
            translate([size / 2, size / 2, 0]) cube([size / 2, size / 2, thickness / 2]);
        }
    }

    // Main body of the U-channel bracket
    u_channel(size);

    // Add chamfer to the primary outer edges
    translate([0, 0, thickness / 2 - 1]) cylinder(diameter=size, height=2, chamfer_radius=1.5);
    translate([size, 0, thickness / 2 - 1]) cylinder(diameter=size, height=2, chamfer_radius=1.5);
    translate([size / 2, 0, thickness / 2 - 1]) cylinder(diameter=size / 2, height=2, chamfer_radius=1.5);
    translate([size / 2, size / 2, thickness / 2 - 1]) cylinder(diameter=size / 2, height=2, chamfer_radius=1.5);
}

