    difference() {
        cylinder(r=thickness/2, h=length, center=true, chamfer=.5);
        cylinder(r=thickness/2, h=thickness, center=true, chamfer=.5);
        translate([0, 0, thickness/2]) cylinder(r=width/2, h=length, center=true, chamfer=.5);
    }

    // Top L-section
    difference() {
        cylinder(r=thickness/2, h=length, center=true, chamfer=.5);
        cylinder(r=thickness/2, h=thickness, center=true, chamfer=.5);
        translate([0, 0, length + thickness/2]) cylinder(r=width/2, h=length, center=true, chamfer=.5);
    }

    // Bottom hole
    translate([0, -width/2, thickness/2]) cylinder(r=thickness/4, h=length, center=true, chamfer=.5);

    // Top hole
    translate([0, width/2, length + thickness/2]) cylinder(r=thickness/4, h=length, center=true, chamfer=.5);
}

