    hexagon_rounded_height = thickness - 0.5; // Adjust the height to match the thickness of the base plate
    hexagon_rounded_corner_radius = 0.5; // Adjust the corner radius as needed

    difference() {
        cube([length, width, hexagon_rounded_height]);
        rotate([0, 0, 90]) {
            translate([0, 0, hexagon_rounded_height - hexagon_rounded_radius]) {
                polygon([
                    [hexagon_rounded_radius, hexagon_rounded_radius],
                    [hexagon_rounded_radius + hexagon_rounded_radius * sqrt(3), hexagon_rounded_radius],
                    [hexagon_rounded_radius + hexagon_rounded_radius * sqrt(3), hexagon_rounded_radius * sqrt(3)],
                    [hexagon_rounded_radius, hexagon_rounded_radius * sqrt(3)]
                ]);
            }
        }
    }
}

