// Shaft Collar Parameterized Code
module shaft_collar(size, hole_radius, hole_spacing) {
    // Define the main shaft collar
    cylinder(r=0.5*size/2, h=size-4*hole_radius, center=true, chamfer=0.5*size/2);

    // Calculate the center of the mounting holes
    center_x = (size - hole_spacing) / 2 + hole_radius;
    center_y = (size - hole_spacing) / 2 - hole_radius;

    // Add four circular mounting holes
    difference() {
        cylinder(r=hole_radius, h=size-4*hole_radius, center=true, chamfer=0.5*size/2);

        translate([center_x, center_y, 0]) cylinder(r=hole_radius, h=4*hole_radius, center=true, chamfer=0.5*size/2);
        translate([center_x - hole_spacing, center_y, 0]) cylinder(r=hole_radius, h=4*hole_radius, center=true, chamfer=0.5*size/2);
        translate([center_x, center_y - hole_spacing, 0]) cylinder(r=hole_radius, h=4*hole_radius, center=true, chamfer=0.5*size/2);
        translate([center_x + hole_spacing, center_y - hole_spacing, 0]) cylinder(r=hole_radius, h=4*hole_radius, center=true, chamfer=0.5*size/2);
    }
}

