    // Mounting holes
    translate([size[0]/2 - hole_diameter/2 - hole_center_offset[0], size[1]/2 - hole_diameter/2 - hole_center_offset[1], size[2] + hole_center_offset[2]]) {
        cylinder(hole_diameter, hole_diameter, hole_spacing);
    }
    translate([size[0]/2 + hole_diameter/2 - hole_center_offset[0], size[1]/2 - hole_diameter/2 - hole_center_offset[1], size[2] + hole_center_offset[2]]) {
        cylinder(hole_diameter, hole_diameter, hole_spacing);
    }
    translate([size[0]/2 - hole_diameter/2 - hole_center_offset[0], size[1]/2 + hole_diameter/2 - hole_center_offset[1], size[2] + hole_center_offset[2]]) {
        cylinder(hole_diameter, hole_diameter, hole_spacing);
    }
    translate([size[0]/2 + hole_diameter/2 - hole_center_offset[0], size[1]/2 + hole_diameter/2 - hole_center_offset[1], size[2] + hole_center_offset[2]]) {
        cylinder(hole_diameter, hole_diameter, hole_spacing);
    }
}

