module project_enclosure_base(size, thickness) {
    // Define the main body
    difference() {
        cube([size[0], size[1], size[2]]);

        // Add holes to prevent artifacts
        difference() {
            union() {
                hole([thickness/2, thickness/2, size[2] + thickness]);
                hole([size[0] - thickness/2, size[1] - thickness/2, size[2] + thickness]);
                hole([size[0] - thickness/2, thickness/2, size[2] + thickness]);
                hole([thickness/2, size[1] - thickness/2, size[2] + thickness]);
            }
        }
    }

    // Additional optional features like a window
    difference() {
        union() {
            hole([size[0]/2 - 2*thickness, size[1]/2 - 2*thickness, size[2] + thickness]);
            hole([size[0]/2 + 2*thickness, size[1]/2 - 2*thickness, size[2] + thickness]);
            hole([size[0]/2 + 2*thickness, size[1]/2 + 2*thickness, size[2] + thickness]);
            hole([size[0]/2 - 2*thickness, size[1]/2 + 2*thickness, size[2] + thickness]);
        }
    }
}

