module structural_l_bracket(size=66mm, thickness=7mm, hole_radius=3mm) {
    // Create the L-bracket body
    // (This is a simplified version and would need more detailed modeling for a realistic L-bracket)
    difference() {
        // Create the base of the L-bracket
        rotateX(90) {
            translate([0, 0, thickness/2]) {
                box(size-[0, thickness/2, 0]);
            }
        }
        // Create the top of the L-bracket
        rotateX(-90) {
            translate([0, 0, size[2]]) {
                box(size-[0, size[2], 0]);
            }
        }
        // Create the bottom of the L-bracket
        translate([0, 0, -size[2]]) {
            box(size-[0, size[2], 0]);
        }
        // Create the side of the L-bracket
        translate([size[1]/2, 0, 0]) {
            box(size-[size[1], 0, 0]);
        }
    }

    // Add circular mounting holes
    for (x=[0:3], y=[0:3]) {
        translate([x* hole_radius + hole_radius/2, y* hole_radius + hole_radius/2, 0]) {
            cylinder(r=hole_radius, h=thickness);
        }
    }
}

