module pipe_flange(size = 54, thickness = 4, hole_diameter = 2, hole_distance = 5) {
    // Define the pipe body
    union() {
        // Top face
        difference() {
            cylinder(r=size/2, h=size/2 + thickness);
            cylinder(r=size/2, h=size/2);
        }
        // Bottom face
        difference() {
            cylinder(r=size/2, h=size/2 + thickness);
            cylinder(r=size/2, h=size/2);
        }
        // Side faces
        translate([0, size/2 + thickness/2, 0]) {
            cylinder(r=size/2, h=size - 2*thickness);
        }
        translate([0, -size/2 - thickness/2, 0]) {
            cylinder(r=size/2, h=size - 2*thickness);
        }
        translate([size/2 + thickness/2, 0, 0]) {
            cylinder(r=size/2, h=size - 2*thickness);
        }
        translate([-size/2 - thickness/2, 0, 0]) {
            cylinder(r=size/2, h=size - 2*thickness);
        }
    }

    // Define the mounting holes
    difference() {
        // First hole
        translate([hole_distance/2, hole_distance/2, hole_distance/2]) {
            cylinder(r=hole_diameter/2, h=hole_distance);
        }
        // Second hole
        translate([size/2 + hole_distance/2, hole_distance/2, hole_distance/2]) {
            cylinder(r=hole_diameter/2, h=hole_distance);
        }
        // Third hole
        translate([hole_distance/2, size/2 + hole_distance/2, hole_distance/2]) {
            cylinder(r=hole_diameter/2, h=hole_distance);
        }
        // Fourth hole
        translate([size/2 + hole_distance/2, size/2 + hole_distance/2, hole_distance/2]) {
            cylinder(r=hole_diameter/2, h=hole_distance);
        }
    }
}

pipe_flange();

module pipe_flange(size=30, thickness=15, chamfer=2) {
  // Calculate the inner and outer diameters
  inner_diameter = size - 2 * thickness;
  outer_diameter = size;

  // Create the main cylinder
  cylinder(inner_diameter/2, outer_diameter/2, 1000, center=true);

  // Chamfer the primary outer edges
  chamfered_pipe_flange(size, thickness, chamfer);
}

module chamfered_pipe_flange(size, thickness, chamfer) {
  // Create the cylinder with chamfered edges
  cylinder(inner_diameter/2 - chamfer, outer_diameter/2 - chamfer, 1000, chamfer=true, chamfer_radius=chamfer/2);

  // Translate the chamfered cylinder to its original position
  translate([0, 0, thickness/2 + chamfer]) {
    cylinder(inner_diameter/2, outer_diameter/2, 1000, chamfer=true, chamfer_radius=chamfer/2);
  }
}

