// Create the U-channel bracket
module UChannelBracket() {
    // Bottom part
    translate([-thickness/2, -thickness/2, -thickness/2])
    cube([40, 40, thickness]);

    // Top part
    translate([thickness/2, thickness/2, -thickness/2])
    cube([40, 40, thickness]);

    // Side part
    translate([-thickness/2, thickness/2, thickness/2])
    cube([thickness, 40, 40]);

    // Front part
    translate([-thickness/2, -thickness/2, thickness/2])
    cube([thickness, thickness, 40]);

    // Back part
    translate([thickness/2, thickness/2, thickness/2])
    cube([thickness, thickness, 40]);
}

// Define the mounting holes
module MountingHoles() {
    translate([-thickness/2, thickness/2, thickness/2])
    cylinder(r=$radius, h=2*$radius, n=$fn);

    translate([thickness/2, thickness/2, thickness/2])
    cylinder(r=$radius, h=2*$radius, n=$fn);
}

