        cylinder(diameter = centralHoleDiameter, height = centralHoleDepth, center = [0, 0, centralHolePosition[2]]);
    }

    // Create the central through-hole
    difference() {
        cube([outerSize, outerSize, thickness]);
        cylinder(diameter = centralHoleDiameter, height = centralHoleDepth, center = [0, 0, centralHolePosition[2]]);
    }

