module hex_recess(size, thickness) {
    // Hexagonal recess
    rotate(120) {
        intersection() {
            hull() {
                linear_extrude(thickness) {
                    difference() {
                        translate([0, 0, thickness / 2]) {
                            sphere(r = size / 2);
                        }
                        translate([0, size / 2, 0]) {
                            sphere(r = size / 2);
                        }
                        translate([-size / 2, size / 2, 0]) {
                            sphere(r = size / 2);
                        }
                        translate([size / 2, -size / 2, 0]) {
                            sphere(r = size / 2);
                        }
                    }
                }
            }
            translate([0, 0, -thickness / 2]) {
                sphere(r = size / 2);
            }
        }
    }
}

