    translate([0, 0, outer_thickness/2])
    difference() {
        cube([outer_length, outer_width, outer_thickness]);

        // Add a chamfer to the primary outer edges
        translate([0, 0, outer_thickness/2 - chamfer_size])
        cube([outer_length, chamfer_size, outer_thickness]);

        translate([0, outer_width, outer_thickness/2 - chamfer_size])
        cube([chamfer_size, outer_width, outer_thickness]);

        translate([outer_length, 0, outer_thickness/2 - chamfer_size])
        cube([outer_length, chamfer_size, outer_thickness]);
    }

    // Define the opening in the top and bottom of the L-bracket
    translate([0, outer_length/2, outer_thickness/2])
    difference() {
        cube([outer_length, outer_width/2, outer_thickness]);

        translate([0, 0, outer_thickness/2 - chamfer_size])
        cube([outer_length, chamfer_size, outer_thickness]);

        translate([0, outer_width/2, outer_thickness/2 - chamfer_size])
        cube([chamfer_size, outer_width/2, outer_thickness]);

        translate([outer_length, 0, outer_thickness/2 - chamfer_size])
        cube([outer_length, chamfer_size, outer_thickness]);
    }
}

