module LBracket(size = [36, 10, 10], chamfer = 2) {
  // Primary outer edges with chamfer
  difference() {
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
  }

  // Secondary outer edges with chamfer
  difference() {
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
    cube([size[0], size[1] + 2 * chamfer, size[2]]);
  }

  // Main body
  difference() {
    cube(size);
  }

  // Top edge
  difference() {
    translate([0, size[1] - chamfer, 0]) cube([size[0], chamfer, size[2]]);
    translate([0, size[1] - chamfer, 0]) cube([size[0], chamfer, size[2]]);
    translate([0, size[1] - chamfer, 0]) cube([size[0], chamfer, size[2]]);
    translate([0, size[1] - chamfer, 0]) cube([size[0], chamfer, size[2]]);
    translate([0, size[1] - chamfer, 0]) cube([size[0], chamfer, size[2]]);
  }

  // Bottom edge
  difference() {
    translate([0, 0, size[2] - chamfer]) cube([size[0], size[1] + 2 * chamfer, chamfer]);
    translate([0, 0, size[2] - chamfer]) cube([size[0], size[1] + 2 * chamfer, chamfer]);
    translate([0, 0, size[2] - chamfer]) cube([size[0], size[1] + 2 * chamfer, chamfer]);
    translate([0, 0, size[2] - chamfer]) cube([size[0], size[1] + 2 * chamfer, chamfer]);
    translate([0, 0, size[2] - chamfer]) cube([size[0], size[1] + 2 * chamfer, chamfer]);
  }
}

