module flat_mounting_plate(
    size = [62, 5, 5],
    hole_radius = 2.5,
    hole_spacing = 10
){
    // Base plate
    linear_extrude(size[2], segments = 10){
        difference(){
            cube(size[0]);
            translate([-hole_spacing/2, -hole_spacing/2, 0]){
                rotate([90, 0, 0]){
                    cylinder(r = hole_radius, h = size[2], $fn = 50);
                }
            }
        }
    }

    // Mounting holes
    translate([-hole_spacing/2, -hole_spacing/2, size[2] + hole_spacing]){
        translate([hole_radius, hole_radius, 0]){
            cylinder(r = hole_radius, h = hole_spacing - hole_radius, $fn = 50);
        }
    }

    translate([hole_spacing, hole_spacing, size[2] + hole_spacing]){
        translate([hole_radius, hole_radius, 0]){
            cylinder(r = hole_radius, h = hole_spacing - hole_radius, $fn = 50);
        }
    }

    translate([-hole_spacing, hole_spacing, size[2] + hole_spacing]){
        translate([hole_radius, hole_radius, 0]){
            cylinder(r = hole_radius, h = hole_spacing - hole_radius, $fn = 50);
        }
    }
}

