    translate([0, 0, -thickness]) {
      cylinder(r = holeDiameter / 2, h = holeDepth, center = true);
      cylinder(r = height / 2, h = height - holeDepth, center = true);
    }
    translate([0, 0, height - thickness]) {
      cylinder(r = holeDiameter / 2, h = holeDepth, center = true);
    }
  }

  // Subtracted hole geometries extending past the main body on the Z-axis
  translate([0, 0, height - thickness]) {
    difference() {
      translate([0, 0, -thickness]) {
        cylinder(r = holeDiameter / 2, h = holeDepth, center = true);
      }
      translate([0, 0, height]) {
        cylinder(r = holeDiameter / 2, h = holeDepth, center = true);
      }
    }
  }
}

