module corner_gusset(size, thickness, chamfer) {
    // Corner gusset geometry
    translate([0, size/2, 0])
    difference() {
        cube([size, thickness, thickness]);
        translate([size/2, 0, thickness/2])
        difference() {
            cube([thickness, thickness, thickness/2]);
            translate([thickness/2, thickness/2, thickness/2])
            difference() {
                cube([thickness, thickness, thickness/2]);
                translate([thickness/2, thickness/2, thickness/2])
                difference() {
                    cube([thickness, thickness, thickness/2]);
                }
            }
        }
    }

    // Chamfer on primary outer edges
    translate([0, size/2, 0])
    difference() {
        cube([size, thickness, thickness]);
        translate([size/2, 0, thickness/2])
        difference() {
            cube([thickness, thickness, thickness/2]);
            translate([thickness/2, thickness/2, thickness/2])
            difference() {
                cube([thickness, thickness, thickness/2]);
                translate([thickness/2, thickness/2, thickness/2])
                difference() {
                    cube([thickness, thickness, thickness/2]);
                    translate([thickness/2, thickness/2, thickness/2])
                    difference() {
                        cube([thickness, thickness, thickness/2]);
                        translate([thickness/2, thickness/2, thickness/2])
                        difference() {
                            cube([thickness, thickness, thickness/2]);
                            translate([thickness/2, thickness/2, thickness/2])
                            difference() {
                                cube([thickness, thickness, thickness/2]);
                            }
                        }
                    }
                }
            }
        }
    }
}

