module hexagon_recess(size, thickness, hex_diameter, hex_depth) {
    // Calculate the radius of the hexagon
    radius = hex_diameter / 2;

    // Create the hexagon
    difference() {
        // Hexagon base
        rotate([0, 0, 90]) {
            cube([radius * 2, hex_diameter, thickness]);
        }
        // Hexagon caps
        translate([radius, 0, thickness]) {
            cylinder(radius, thickness, radius);
        }
        translate([-radius, 0, thickness]) {
            cylinder(radius, thickness, radius);
        }
    }
}

