module flat_mounting_plate(size, thickness) {
    // Define the dimensions of the plate
    size = size || 75; // Set default size to 75mm if not provided
    thickness = thickness || 6; // Set default thickness to 6mm if not provided

    // Create the plate body using a difference() subtraction
    difference() {
        // Create the plate using a union() addition
        union() {
            // Create the top of the plate
            cube([size, thickness, thickness]);

            // Create the bottom of the plate
            cube([size, thickness, thickness]);

            // Create the sides of the plate
            translate([-size/2, thickness/2, thickness/2]) {
                cube([size, thickness, thickness]);
            }
            translate([size/2, thickness/2, thickness/2]) {
                cube([size, thickness, thickness]);
            }

            // Create the central through-hole using a difference() subtraction
            difference() {
                cube([size/2, thickness, thickness]);
                cube([size/2, thickness, thickness]);
            }
        }
    }
}

