  // Create the main cylinder with a hole
  cylinder(r=radius, h=main_height - thickness, center=false, chamfer=thickness/4, chamfer_radius=thickness/2);

  // Create the hole with a chamfer
  cylinder(r=radius + 2*thickness, h=thickness, center=false, chamfer=thickness/4, chamfer_radius=thickness/2);
}

