cylindricalSpacer(radius=10mm, thickness=11mm, main_height=35mm);

module flanged_bushing(radius, thickness, mounting_hole_radius, mounting_hole_spacing) {
    // Outer cylinder
    cylinder(diameter=54+2*thickness, height=11, center=false);

    // Inner cylinder
    cylinder(diameter=54-2*thickness, height=11, center=false);

    // Mounting holes
    translate([0, 54/2 + thickness/2, 0]) {
        for (i = [0:3]) {
            translate([i*mounting_hole_spacing, 0, 0]) {
                cylinder(diameter=mounting_hole_radius, height=thickness, center=false);
            }
        }
    }
}

