module corner_gusset(size, thickness) {
    // Define the size of the corner gusset
    size = size || 57;
    thickness = thickness || 13;

    // Define the dimensions of the mounting holes
    hole_diameter = 4;
    hole_distance = 10;

    // Calculate the dimensions of the rectangular pattern of holes
    hole_rows = size / hole_distance;
    hole_cols = hole_rows;

    // Calculate the dimensions of the gusset
    gusset_width = hole_cols * hole_diameter;
    gusset_height = hole_rows * hole_diameter;
    gusset_depth = thickness;

    // Create the rectangular pattern of holes
    for (x = [0:(hole_cols-1)]) {
        for (y = [0:(hole_rows-1)]) {
            translate([x * hole_distance, y * hole_distance, 0]) {
                cylinder(diameter = hole_diameter, height = hole_diameter, center = true);
            }
        }
    }

    // Create the gusset
    translate([gusset_width / 2, gusset_height / 2, thickness / 2]) {
        rotate([90, 0, 0]) {
            cylinder(diameter = size, height = thickness, center = true);
        }
    }
}

