            cylinder(r = radius, h = 2*radius);
        }
        translate([radius, 0, thickness]) {
            cylinder(r = radius, h = 2*radius);
        }
        translate([radius, radius, thickness]) {
            cylinder(r = radius, h = 2*radius);
        }
        translate([0, 0, thickness-chamfer]) {
            cylinder(r = radius, h = thickness);
        }
        translate([0, radius, thickness-chamfer]) {
            cylinder(r = radius, h = thickness);
        }
        translate([radius, 0, thickness-chamfer]) {
            cylinder(r = radius, h = thickness);
        }
        translate([radius, radius, thickness-chamfer]) {
