module circular_pipe_flange(radius, thickness, chamfer_size) {
    // Define the primary outer circle
    cylinder(r=radius, h=thickness+2*chamfer_size, center=true);

    // Define the inner circle
    cylinder(r=radius-chamfer_size, h=thickness, center=true);

    // Chamfer the primary outer edges
    difference() {
        union() {
            difference() {
                cylinder(r=radius, h=thickness+2*chamfer_size, center=true);
                difference() {
                    cylinder(r=radius-chamfer_size, h=thickness, center=true);
                    translate([radius, 0, 0]) cylinder(r=chamfer_size, h=thickness+2*chamfer_size, center=true);
                }
            }
            translate([-radius, 0, 0]) cylinder(r=chamfer_size, h=thickness+2*chamfer_size, center=true);
        }
        translate([0, thickness/2, 0]) cylinder(r=radius, h=chamfer_size, center=true);
    }
}

