module cylindricalSpacer(size, thickness) {
    // Create the main cylindrical body
    cylinder(r=size/2, h=thickness, center=true, chamfer=0.02, chamfer_radius=0.01);

    // Subtract the hole on the top surface
    difference() {
        // Outer cylinder with small chamfer for a rounded top
        cylinder(r=(size-2)/2, h=thickness+0.01, center=true, chamfer=0.02, chamfer_radius=0.01);

        // Inner cylinder with small chamfer for a rounded bottom
        cylinder(r=(size-4)/2, h=thickness-0.01, center=true, chamfer=0.02, chamfer_radius=0.01);
    }

    // Subtract the hole on the bottom surface
    difference() {
        // Outer cylinder with small chamfer for a rounded top
        cylinder(r=(size-2)/2, h=thickness+0.01, center=true, chamfer=0.02, chamfer_radius=0.01);

        // Inner cylinder with small chamfer for a rounded bottom
        cylinder(r=(size-4)/2, h=thickness-0.01, center=true, chamfer=0.02, chamfer_radius=0.01);
