module LBracket(size, thickness) {
    // Define the dimensions of the L-bracket
    L = size - thickness * 2; // inner dimensions

    // Define the circular mounting holes
    h = size / 2 - thickness; // hole diameter
    d = size / 4; // hole spacing

    // Define the hole pattern
    for (i = [0:d:2*h]) {
        for (j = [0:h:2*h]) {
            translate([j, i, 0]) {
                cylinder(r = h, h = L, $fn = 72);
            }
        }
    }

    // Define the base and top of the L-bracket
    translate([0, 0, thickness]) {
        cube([L, L, thickness], center = true);
    }
    translate([0, 0, -thickness]) {
        cube([L, L, thickness], center = true);
    }

    // Define the legs
    translate([0, -L/2, -thickness]) {
        cube([L/2, L/2, thickness], center = true);
    }
    translate([0, L/2, -thickness]) {
        cube([L/2, L/2, thickness], center = true);
    }
    translate([-L/2, 0, -thickness]) {
        cube([L/2, L/2, thickness], center = true);
    }
    translate([L/2, 0, -thickness]) {
        cube([L/2, L/2, thickness], center = true);
    }
}

