module spacer(
    R = 5, // radius of the cylindrical spacer
    H = 91 // height of the cylindrical spacer
) {
    // Create the main cylindrical body
    cylinder(R = R, H = H, centered = true, chamfer = 0.1);

    // Create the first subtracted hole (x-axis)
    translate([10, 0, 0]) {
        cylinder(R = R - 1, H = H - 10, centered = true, chamfer = 0.1);
    }

    // Create the second subtracted hole (y-axis)
    translate([0, 10, 0]) {
        cylinder(R = R - 1, H = H - 10, centered = true, chamfer = 0.1);
    }

    // Create the third subtracted hole (z-axis)
    translate([0, 0, 10]) {
        cylinder(R = R - 1, H = H - 10, centered = true, chamfer = 0.1);
    }
}

