module shaft_collar(hole_diameter, hole_length, outer_diameter, outer_length) {
    // Create the shaft body
    cylinder(d=outer_diameter, h=outer_length);

    // Create the hole
    cylinder(d=hole_diameter, h=hole_length, center=false, resolution=20);

    // Subtract the hole from the shaft body
    difference() {
        cylinder(d=outer_diameter, h=outer_length);
        cylinder(d=hole_diameter, h=hole_length, center=false, resolution=20);
    }

    // Ensure the hole extends past the main body on the Z-axis
    translate([0, 0, 0.5*hole_length]) {
        union() {
            difference() {
                cylinder(d=outer_diameter, h=outer_length);
                cylinder(d=hole_diameter, h=hole_length, center=false, resolution=20);
            }
            difference() {
                cylinder(d=outer_diameter, h=outer_length);
                cylinder(d=hole_diameter, h=hole_length, center=false, resolution=20);
            }
        }
    }
}

