// Parameterized circular pipe flange code
module pipe_flange(size, thickness, chamfer) {
    // Calculate the radius of the pipe
    radius = size / 2;
    // Calculate the diameter of the pipe
    diameter = 2 * radius;

    // Create the outer surface of the pipe
    difference() {
        cylinder(radiuss, diameter, chamfer);
        translate([0, -thickness / 2, 0]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, thickness / 2, 0]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, -thickness / 2, thickness]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, thickness / 2, thickness]) cylinder(radiuss, diameter - thickness, chamfer);
    }

    // Create the inner surface of the pipe
    difference() {
        cylinder(radiuss, diameter, chamfer);
        translate([0, -thickness / 2, 0]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, thickness / 2, 0]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, -thickness / 2, thickness]) cylinder(radiuss, diameter - thickness, chamfer);
        translate([0, thickness / 2, thickness]) cylinder(radiuss, diameter - thickness, chamfer);
    }

    // Create the central hole for the pipe
    cylinder(radius, thickness / 2, chamfer);
}

