    cylinder(r1=thickness/2, r2=thickness/2, h=size+thickness*2);

    // Define the holes
    hole(d=thickness, pos=[0, 0, thickness/2]);
    hole(d=thickness, pos=[0, size/2, thickness/2]);
    hole(d=thickness, pos=[size/2, 0, thickness/2]);
    hole(d=thickness, pos=[size/2, size/2, thickness/2]);

    // Ensure all subtracted hole geometries extend past the main body on the Z-axis
    translate([0, 0, thickness/2]) {
        difference() {
            cylinder(r1=thickness/2, r2=thickness/2, h=size+thickness*2);
            hole(d=thickness, pos=[0, 0, thickness/2]);
            hole(d=thickness, pos=[0, size/2, thickness/2]);
            hole(d=thickness, pos=[size/2, 0, thickness/2]);
            hole(d=thickness, pos=[size/2, size/2, thickness/2]);
        }
    }
}

