// Define the dimensions
module hexagonal_standoff(size, thickness) {
    // Calculate the radius of the hexagon
    radius = size / 2;

    // Calculate the height of the hexagon
    height = 2 * radius * sin(pi / 6);

    // Define the vertices of the hexagon
    v1 = [0, 0, thickness];
    v2 = [radius * cos(pi / 3), radius * sin(pi / 3), thickness];
    v3 = [radius * cos(2 * pi / 3), radius * sin(2 * pi / 3), thickness];
    v4 = [radius, 0, thickness];
    v5 = [-radius, 0, thickness];
    v6 = [-radius * cos(2 * pi / 3), radius * sin(2 * pi / 3), thickness];

    // Define the edges of the hexagon
    e1 = [v1, v2, v3];
    e2 = [v2, v4, v5];
    e3 = [v4, v6, v1];
    e4 = [v6, v5, v2];
    e5 = [v1, v6, v3];

    // Create the hexagon
    difference() {
        cube([2 * radius, 2 * radius, thickness]);
        translate([0, 0, thickness]) rotate([90, 0, 0]) cube([radius, radius, height]);
    }

    // Define the through-hole
    sphere(r=5, d=10, center=true);
}

