        // Large hole
        cylinder(r = size / 4 - thickness / 4, h = size / 8 + thickness / 4, center = true, chamfer = true);

        // Small hole
        cylinder(r = size / 4 - thickness / 8, h = size / 16 + thickness / 8, center = true, chamfer = true);
