module base_rectangle(width, height, thickness) {
    difference() {
        // Bottom layer: rectangular base
        cube([width, height, thickness]);

        // Top layer: rectangular base with holes
        translate([0, 0, thickness]) {
            union() {
                // Top part: outer rectangle
                cube([width, height, thickness]);

                // Inner holes: circular
                translate([width/2, height/2, thickness/2]) {
                    difference() {
                        // Circle for hole 1
                        circle(r = 5, $fn = 100);

                        // Circle for hole 2
                        translate([0, height/2, thickness/2]) {
                            circle(r = 5, $fn = 100);
                        }

                        // Circle for hole 3
                        translate([-width/2, height/2, thickness/2]) {
                            circle(r = 5, $fn = 100);
                        }

                        // Circle for hole 4
                        translate([-width/2, -height/2, thickness/2]) {
                            circle(r = 5, $fn = 100);
                        }
                    }
                }
            }
        }
    }
}

