module cylindrical_spacer(radius, thickness) {
    // Create the outer cylinder
    cylinder(radius + thickness / 2, 2 * radius + thickness, center=true);

    // Create the inner cylinder
    cylinder(radius, thickness / 2, center=true);

    // Subtract the inner cylinder from the outer cylinder to create the spacer
    difference() {
        cylinder(radius + thickness / 2, 2 * radius + thickness, center=true);
        cylinder(radius, thickness / 2, center=true);
    }
}

