module flanged_bushing(
    diameter = 36,
    thickness = 14,
    hole_diameter = 6,
    hole_depth = 2,
    hole_position = [0, 0, 0]
) {
    // Create the outer flange
    cylinder(
        radius1 = diameter / 2,
        radius2 = diameter / 2 - thickness / 2,
        height = thickness,
        center = [0, 0, thickness / 2]
    );

    // Create the inner flange
    cylinder(
        radius1 = diameter / 2 - thickness / 2,
        radius2 = diameter / 2 - thickness / 2 - hole_diameter / 2,
        height = thickness,
        center = [0, 0, thickness / 2 - hole_depth / 2]
    );

    // Create the hole
    difference() {
        cylinder(
            radius1 = hole_diameter / 2,
            radius2 = hole_diameter / 2,
            height = hole_depth,
            center = hole_position
        );
        cylinder(
            radius1 = hole_diameter / 2 - thickness / 2,
            radius2 = hole_diameter / 2 - thickness / 2 - hole_diameter / 2,
            height = thickness,
            center = hole_position
        );
    }
}

