module base_project_enclosure(
    length = 52,
    width = 35,
    thickness = 5
) {
    // Create the base with a rectangular shape
    translate([0, 0, thickness / 2]) cube([length, width, thickness], center = true);

    // Define the center of the base
    center_point = translate([length / 2, width / 2, thickness / 2]);

    // Define the radius for the circular holes
    hole_radius = 3;

    // Add four circular mounting holes at specified positions
    translate([center_point[0] + 15, center_point[1], center_point[2]]) difference() {
        cylinder(r=hole_radius, h=thickness - 2 * hole_radius, center = true);
    }
    translate([center_point[0] - 15, center_point[1], center_point[2]]) difference() {
        cylinder(r=hole_radius, h=thickness - 2 * hole_radius, center = true);
    }
    translate([center_point[0], center_point[1] + 15, center_point[2]]) difference() {
        cylinder(r=hole_radius, h=thickness - 2 * hole_radius, center = true);
    }
    translate([center_point[0], center_point[1] - 15, center_point[2]]) difference() {
        cylinder(r=hole_radius, h=thickness - 2 * hole_radius, center = true);
    }
}

