module hexagonal_standoff(hex_size, hole_diameter, hole_depth) {
  // Main body
  cylinder(h=hex_size*2, r=hex_size/2, $fn=36);

  // Hexagonal holes
  translate([hex_size/2, 0, -hole_depth]) {
    for (i=[0:5]) {
      rotate([i*360/6, 0, 0]) {
        cylinder(h=hole_depth, r=hole_diameter/2, $fn=36);
      }
    }
  }

  // Subtracted holes extend past the main body on the Z-axis
  translate([0, 0, -hex_size/2]) {
    for (i=[0:5]) {
      rotate([i*360/6, 0, 0]) {
        cylinder(h=hole_depth, r=hole_diameter/2, $fn=36);
      }
    }
  }
}

