module pipe_flange(
    outer_radius = 45,
    inner_radius = 35,
    thickness = 10,
    hole_radius = 3,
    hole_spacing = 5,
    hole_height = 3
) {
    // Create the outer pipe body
    translate([0, 0, -thickness / 2]) {
        cylinder(r1 = outer_radius, r2 = inner_radius, h = outer_radius + thickness);
    }

    // Create the inner pipe body
    translate([0, 0, -thickness / 2]) {
        cylinder(r1 = inner_radius, r2 = inner_radius - thickness, h = inner_radius);
    }

    // Create the hole on the outer pipe
    translate([0, 0, -thickness / 2 + hole_height / 2]) {
        difference() {
            union() {
                cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                translate([0, 0, -hole_height / 2]) {
                    cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                }
            }
            union() {
                cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                translate([0, 0, -hole_height / 2]) {
                    cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                }
            }
        }
    }

    // Create the holes on the inner pipe
    translate([0, 0, -thickness / 2 + hole_height / 2]) {
        difference() {
            union() {
                cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                translate([0, 0, -hole_height / 2]) {
                    cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                }
            }
            union() {
                cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                translate([0, 0, -hole_height / 2]) {
                    cylinder(r1 = hole_radius, r2 = hole_radius, h = hole_height);
                }
            }
        }
    }
}

