module pipe_flange(radius, thickness, chamfer_size) {
    // Define the flange
    difference() {
        // Outer flange
        cylinder(d=radius+thickness, h=thickness*2);
        // Inner hole
        cylinder(d=radius, h=thickness*2);
        // Chamfer
        translate([0, -thickness/2+chamfer_size, 0]) {
            cylinder(d=radius, h=thickness);
        }
        translate([0, thickness/2-chamfer_size, 0]) {
            cylinder(d=radius, h=thickness);
        }
        translate([thickness/2, 0, -thickness/2+chamfer_size]) {
            cylinder(d=radius, h=thickness);
        }
        translate([thickness/2, 0, thickness/2-chamfer_size]) {
            cylinder(d=radius, h=thickness);
