            cylinder(r=main_radius, h=main_thickness, $fn=100);
        }
        translate([0, 0, -flange_thickness]) {
            cylinder(r=main_radius, h=flange_thickness, $fn=100);
        }
        translate([0, 0, main_thickness - flange_thickness]) {
            cylinder(r=main_radius, h=main_length, $fn=100);
        }
    }

    // Flange
    difference() {
        translate([0, 0, main_thickness]) {
            cylinder(r=flange_radius, h=flange_thickness, $fn=100);
        }
        translate([0, 0, main_thickness + flange_thickness]) {
            cylinder(r=flange_radius, h=flange_length, $fn=100);
        }
    }
}

