        cylinder(diameter=thickness, height=size / 2 - thickness / 4, center=true);
    }

    // Top hole
    translate([0, size / 2, size / 2 - thickness / 4]) {
        cylinder(diameter=thickness, height=size / 2 - thickness / 4, center=true);
    }

    // Bottom hole
    translate([0, -size / 2, size / 2 - thickness / 4]) {
        cylinder(diameter=thickness, height=size / 2 - thickness / 4, center=true);
    }

    // Center hole
    translate([size / 2 - thickness / 4, 0, size / 2 - thickness / 4]) {
        cylinder(diameter=thickness, height=size / 2 - thickness / 4, center=true);
    }

    // Left side hole
    translate([0, size / 2 - thickness / 4, size / 2 - thickness / 4]) {
        cylinder(diameter=thickness, height=size / 2 - thickness / 4, center=true);
    }

    // Right side hole
    translate([size / 2 + thickness / 4, size / 2 - thickness / 4, size / 2 - thickness / 4]) {
