    inner_radius = outer_radius - thickness / 2;
    slot_width = 4 * hole_diameter;
    slot_height = 10; // Example slot height

    // Define the bushing body
    difference() {
        // Create the outer body
        cylinder(r=outer_radius, h=size, center=true);
        // Create the inner body
        cylinder(r=inner_radius, h=size, center=true);
    }

    // Define the slots
    for (y = [0:size / slot_height]) {
        for (x = [0:size / slot_width]) {
            translate([x * slot_width, y * slot_height]) {
                cylinder(r=hole_diameter, h=slot_height, center=true);
