module hexagonal_standoff(size = 29, thickness = 5, chamfer = 2) {
    // Calculate dimensions
    base_width = size - (2 * thickness);
    base_height = size - (2 * thickness);
    base_radius = size / 2 - (chamfer / 2);

    // Generate the base of the standoff
    cylinder(r = base_radius, h = base_height, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, 0, thickness]);

    // Generate the top of the standoff
    cylinder(r = base_radius, h = thickness, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, base_height, thickness]);

    // Generate the sides of the standoff
    difference() {
        // Top-left side
        translate([chamfer, 0, 0]) {
            rotate([90, 0, 0]) {
                cylinder(r = base_radius, h = base_width, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, base_width, thickness]);
            }
        }

        // Top-right side
        translate([-chamfer, 0, 0]) {
            rotate([90, 0, 0]) {
                cylinder(r = base_radius, h = base_width, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, base_width, thickness]);
            }
        }

        // Bottom-left side
        translate([chamfer, base_height, 0]) {
            rotate([90, 0, 0]) {
                cylinder(r = base_radius, h = base_width, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, base_width, thickness]);
            }
        }

        // Bottom-right side
        translate([-chamfer, base_height, 0]) {
            rotate([90, 0, 0]) {
                cylinder(r = base_radius, h = base_width, center = true, chamfer = chamfer, start = [0, 0, 0], end = [0, base_width, thickness]);
            }
        }
    }
}

