// Parameterized corner gusset for a 67mm diameter with a 5mm thickness
module corner_gusset(size, thickness) {
  // Define the main body
  cylinder(d=size, h=thickness, center=true, chamfer=0.5);

  // Define the hole center
  hole(d=3.0, h=0.0, center=true);

  // Define the hole radius
  radius=3.0;

  // Subtract the hole from the main body
  difference() {
    cylinder(d=size, h=thickness, center=true, chamfer=0.5);
    cylinder(d=radius, h=thickness, center=true);
  }
}

