module UChannelBracket(width, height, thickness, hole_diameter, hole_depth, hole_spacing, hole_number) {
    // Define the main body
    translate([0, 0, -thickness/2]) {
        box(size = [width, height, thickness]);
    }

    // Define the holes
    for (i = [0:hole_number-1]) {
        translate([width/2, height/2, thickness/2 + hole_depth + hole_spacing * i]) {
            difference() {
                cylinder(d = hole_diameter, h = thickness - hole_depth);
                translate([0, 0, thickness/2]) {
                    box(size = [width, hole_diameter, hole_spacing * i + hole_depth]);
                }
            }
        }
    }
}

