        cube(size=[height+base_plate_thickness, 2*radius, 11mm]);
    }

    // Define the mounting tab
    difference() {
        cylinder(r=radius, h=tab_thickness, center=true);
        cube(size=[tab_thickness, 2*radius, 11mm]);
    }

    // Combine the base plate and mounting tab using union
    union() {
        difference() {
            cylinder(r=radius, h=height+base_plate_thickness, center=true);
            cube(size=[height+base_plate_thickness, 2*radius, 11mm]);
        }
        cylinder(r=radius, h=tab_thickness, center=true);
        cube(size=[tab_thickness, 2*radius, 11mm]);
