        difference(){
            hull(){
                translate([0, -thickness, 0])
                    cube(size-2*thickness);
                translate([0, thickness, 0])
                    cube(size-2*thickness);
                translate([0, 0, size-2*thickness])
                    cube(size-2*thickness);
                translate([0, 0, 0])
                    cube(size-2*thickness);
            }
            translate([0, 0, thickness/2])
                cube(size-2*thickness);
        }
    }
    // Chamfer
    translate([size/2, thickness/2]){
        difference(){
            hull(){
                translate([0, -thickness, 0])
                    cube(size-2*thickness);
                translate([0, thickness, 0])
                    cube(size-2*thickness);
                translate([0, 0, size-2*thickness])
                    cube(size-2*thickness);
                translate([0, 0, 0])
                    cube(size-2*thickness);
            }
            translate([0, 0, thickness/2])
                cube(size-2*thickness-chamfer);
        }
    }
}

