module cylindrical_spacer(hole_diameter, hole_depth, outer_diameter, outer_depth) {
    // Create the outer cylinder
    cylinder(r=outer_diameter/2, h=outer_depth, center=true);

    // Create the inner cylinder with a hole
    cylinder(r=outer_diameter/2-hole_diameter/2, h=hole_depth, center=true);

    // Define the hexagonal recess
    hexagon(h=hole_diameter, r=hole_diameter/2);

    // Remove the hexagonal recess from the outer cylinder
    difference() {
        cylinder(r=outer_diameter/2, h=outer_depth, center=true);
        hexagon(h=hole_diameter, r=hole_diameter/2);
    }
}

