  translate([0, size / 2, thickness / 2]) cylinder(r = size / 2, height = thickness, center = [0, 0, 0], diameter = size, segments = 12);
  translate([size / 2, 0, thickness / 2]) cylinder(r = size / 2, height = thickness, center = [0, 0, 0], diameter = size, segments = 12);
  translate([size / 2, size / 2, thickness / 2]) cylinder(r = size / 2, height = thickness, center = [0, 0, 0], diameter = size, segments = 12);

