module u_channel_bracket(
    width = 57,
    height = 4,
    depth = 4,
    hole_diameter = 1
) {
    // Define the main body of the bracket
    difference() {
        cube([width, height, depth], center = [true, true, true]);
        // Define the holes in the bracket
        translate([0, height/2 - hole_diameter/2, 0]) {
            cylinder(r = hole_diameter / 2, h = height, center = true);
        }
        translate([width - hole_diameter, height/2 - hole_diameter/2, 0]) {
            cylinder(r = hole_diameter / 2, h = height, center = true);
        }
        translate([0, height/2 - hole_diameter/2, depth - hole_diameter]) {
            cylinder(r = hole_diameter / 2, h = height, center = true);
        }
        translate([width - hole_diameter, height/2 - hole_diameter/2, depth - hole_diameter]) {
            cylinder(r = hole_diameter / 2, h = height, center = true);
        }
    }
}

