// Define the flanged bushing parameters
module flangedBushing(
    diameter = 53,
    thickness = 12,
    holeDiameter = 2,
    holeDepth = 2,
    flankWidth = 0.5,
    flankHeight = 2
) {
    // Main body of the bushing
    difference() {
        cube([diameter, thickness, 1]);

        // Flank geometry
        difference() {
            cylinder(r = flankWidth, h = flankHeight);
            translate([0, 0, thickness/2 - flankHeight/2]) {
                cylinder(r = flankWidth, h = thickness - flankHeight);
            }
        }
    }

    // Holes in the flange
    translate([0, 0, thickness/2 + holeDepth]) {
        difference() {
            cylinder(r = holeDiameter, h = holeDepth);
            translate([0, holeDiameter/2, holeDepth]) {
                cylinder(r = holeDiameter, h = holeDepth);
            }
        }
    }

    // Holes in the body
    translate([diameter/2 - holeDiameter/2, 0, thickness/2 + holeDepth]) {
        difference() {
            cylinder(r = holeDiameter, h = holeDepth);
            translate([holeDiameter/2, holeDiameter/2, holeDepth]) {
                cylinder(r = holeDiameter, h = holeDepth);
            }
        }
    }

    // Holes in the flange on the Z-axis
    translate([0, 0, thickness]) {
        difference() {
            cylinder(r = holeDiameter, h = holeDepth);
            translate([0, holeDiameter/2, holeDepth]) {
                cylinder(r = holeDiameter, h = holeDepth);
            }
        }
    }
}

