    cylinder(d=size-2*thickness, h=size+2*thickness, center=true);

    // Define the inner cylindrical bore
    cylinder(d=thickness, h=size+2*thickness, center=true);

    // Define the mounting holes
    translate([0, 0, thickness+1]) cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);
    translate([0, size-2*thickness-1, thickness+1]) cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);
    translate([size-2*thickness-1, 0, thickness+1]) cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);
    translate([size-2*thickness-1, size-2*thickness-1, thickness+1]) cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);

    // Define the flange
    difference() {
        cylinder(d=size-2*thickness, h=size+2*thickness, center=true);
        cylinder(d=thickness, h=size+2*thickness, center=true);
        cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);
        cylinder(d=mountingHoleDiameter, h=2*thickness, center=true);
    }
}

