    cylinder(d=size/2, h=size, center=false);

    // Outer edge of the shaft collar
    cylinder(d=size-2*thickness, h=thickness, center=false);

    // Inner edge of the shaft collar
    cylinder(d=size-2*thickness, h=thickness, center=false, offset=-thickness/2);

    // Subtract the outer edge from the main body
    difference() {
        cylinder(d=size/2, h=size, center=false);
        cylinder(d=size-2*thickness, h=thickness, center=false);
    }

    // Subtract the inner edge from the shaft collar
    difference() {
        cylinder(d=size/2, h=size, center=false);
        cylinder(d=size-2*thickness, h=thickness, center=false, offset=-thickness/2);
    }
}

// Example usage
shaftCollar(46, 15);
